@Slf4j
@Singleton
public class BUChatService implements BUPluginLifecycle {

    private static final Set<ChatMessageType> CHAT_MESSAGE_TYPES_TO_APPLY_ICON_TO = ImmutableSet.of(
        ChatMessageType.PUBLICCHAT,
        ChatMessageType.CLAN_CHAT,
        ChatMessageType.FRIENDSCHAT,
        ChatMessageType.PRIVATECHAT
    );
    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private ChatMessageManager chatMessageManager;
    @Inject
    private BUPluginConfig config;
    @Inject
    private AccountConfigurationService accountConfigurationService;
    @Inject
    private BUResourceService buResourceService;
    private Subscription accountConfigSubscription;
    @Inject
    private MemberService memberService;
    @Inject
    private BUEventService buEventService;
    @Inject
    private ChatMessageProvider chatMessageProvider;
    @Inject
    private BUSoundHelper buSoundHelper;
    @Inject
    private CollectionLogService collectionLogService;
    private final ConcurrentLinkedQueue<String> pendingMessages = new ConcurrentLinkedQueue<>();
    // Chatbox varbits are only reliable after the first post-login tick.
    private volatile boolean awaitingFirstTickAfterLogin = false;

    @Override
    public void startUp() throws Exception {
        clearPendingMessages();
        accountConfigSubscription = accountConfigurationService.currentAccountConfiguration()
            .subscribe(this::currentAccountConfigurationChangeListener);

        manageIconOnChatbox(false);
        if (client.getGameState() == GameState.LOGGED_IN) {
            awaitingFirstTickAfterLogin = true;
        }
    }

    @Override
    public void shutDown() throws Exception {
        manageIconOnChatbox(true);
        if (accountConfigSubscription != null) {
            accountConfigSubscription.dispose();
            accountConfigSubscription = null;
        }
        clearPendingMessages();
    }

    public void onChatMessage(ChatMessage chatMessage) {
        if (!accountConfigurationService.isReady()
            || accountConfigurationService.getCurrentAccountConfiguration() == null) {
            return;
        }

        MessageNode messageNode = chatMessage.getMessageNode();
        ChatMessageType chatMessageType = chatMessage.getType();

        if (CHAT_MESSAGE_TYPES_TO_APPLY_ICON_TO.contains(chatMessageType)) {
            String name = messageNode.getName();
            String sanitizedName = TextUtils.sanitizePlayerName(name);
            Member member = memberService.getMemberByName(sanitizedName);
            if (member == null) {
                return;
            }

            addIconToChatMessage(chatMessage);
        }

        // Mirror the same check that PetDropService does to ensure we process all messages
        if (chatMessageType != ChatMessageType.GAMEMESSAGE
            && chatMessageType != ChatMessageType.SPAM) {
            return;
        }

        ParsedGameMessage parsedGameMessage =
            GameMessageParser.tryParseGameMessage(chatMessage.getMessage());
        if (parsedGameMessage == null) {
            return;
        }

        // Track collection log unlocks for overlay suppression (must be synchronous, before async publish)
        if (parsedGameMessage instanceof CollectionLogUnlockParsedGameMessage) {
            CollectionLogUnlockParsedGameMessage clogMessage =
                (CollectionLogUnlockParsedGameMessage) parsedGameMessage;
            collectionLogService.addRecentCollectionLogUnlock(clogMessage.getItemName());
        }

        BUEvent event = GameMessageToEventTransformer.transformGameMessage(
            parsedGameMessage, client.getAccountHash());

        if (event == null) {
            return;
        }

        withErrorLogging(buEventService.publishEvent(event), "error publishing game message event")
            .thenRun(() -> log.debug("published game message event"));
    }

    public void onScriptCallbackEvent(ScriptCallbackEvent scriptCallbackEvent) {
        String eventName = scriptCallbackEvent.getEventName();
        if (eventName.equals("setChatboxInput")) {
            manageIconOnChatbox(false);
        }
    }

    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            awaitingFirstTickAfterLogin = true;
        }
    }

    public void onGameTick(GameTick event) {
        if (awaitingFirstTickAfterLogin && client.getGameState() == GameState.LOGGED_IN) {
            awaitingFirstTickAfterLogin = false;
            drainPendingMessages();
        }
    }

    /**
     * Sends a restriction message with standardized formatting and plays the disabled sound.
     *
     * @param key the message key for the restriction message
     */
    public void sendRestrictionMessage(MessageKey key) {
        ChatMessageBuilder builder = new ChatMessageBuilder();
        builder.append(config.chatRestrictionColor(), chatMessageProvider.messageFor(key));
        sendMessage(builder.build());
        buSoundHelper.playDisabledSound();
    }

    public void sendErrorMessage(String message) {
        ChatMessageBuilder builder = new ChatMessageBuilder();
        builder.append(config.chatErrorColor(), message);
        sendMessage(builder.build());
    }

    public void sendMessage(String message) {
        log.debug("Sending chat message: {}", message);
        pendingMessages.add(message);
        clientThread.invokeLater(this::drainPendingMessages);
    }

    private void currentAccountConfigurationChangeListener(
        AccountConfiguration accountConfiguration) {
        manageIconOnChatbox(false);
    }

    private void addIconToChatMessage(ChatMessage chatMessage) {
        String messageChatIcon = getMessageChatIconTag();
        if (messageChatIcon == null) {
            return;
        }

        MessageNode messageNode = chatMessage.getMessageNode();
        String name = TextUtils.sanitizePlayerName(messageNode.getName());

        String newName = messageChatIcon + name;
        messageNode.setName(newName);
    }

    private void manageIconOnChatbox(boolean isShuttingDown) {
        String messageChatIcon = getMessageChatIconTag();
        if (messageChatIcon == null) {
            return;
        }

        AccountConfiguration accountConfiguration = accountConfigurationService.getCurrentAccountConfiguration();

        Widget chatboxInput = client.getWidget(InterfaceID.Chatbox.INPUT);
        if (chatboxInput == null) {
            return;
        }

        String currentText = chatboxInput.getText();
        if (currentText == null) {
            return;
        }

        if (isShuttingDown || accountConfiguration == null) {
            // Remove
            if (!currentText.contains(messageChatIcon)) {
                return;
            }
            String newText = currentText.replace(messageChatIcon, "");
            chatboxInput.setText(newText);
        } else {
            // Add
            if (currentText.contains(messageChatIcon)) {
                return;
            }
            chatboxInput.setText(messageChatIcon + currentText);
        }
    }

    private String getMessageChatIconTag() {
        BUResourceService.BUModIcons buModIcons = buResourceService.getBuModIcons();
        if (buModIcons == null) {
            log.error("buModIcons is null, can't get chatIconId");
            return null;
        }
        int chatIconId = buModIcons.getChatIconId();
        return "<img=" + chatIconId + ">";
    }

    public CompletableFuture<String> getItemIconTag(int itemId) {
        return buResourceService.getOrSetupItemImageModIconId(itemId)
            .thenApply((id) -> "<img=" + id + ">");
    }

    public CompletableFuture<String> getItemIconTagIfEnabled(int itemId) {
        if (config.useItemIconsInChat()) {
            return getItemIconTag(itemId);
        }
        return CompletableFuture.completedFuture(null);
    }

    static ChatboxStyle resolveChatboxStyle(boolean isResized, int chatboxTransparencyValue) {
        // Fixed mode never uses the transparent chatbox palette.
        if (!isResized) {
            return ChatboxStyle.OPAQUE;
        }

        return chatboxTransparencyValue == 1 ? ChatboxStyle.TRANSPARENT : ChatboxStyle.OPAQUE;
    }

    private void drainPendingMessages() {
        if (!isReadyToSendPendingMessages()) {
            return;
        }

        String message;
        while ((message = pendingMessages.poll()) != null) {
            queueFormattedMessage(message);
        }
    }

    private void queueFormattedMessage(String message) {
        String messageChatIcon = getMessageChatIconTag();
        if (messageChatIcon == null) {
            throw new IllegalStateException("Chat icon has not been set");
        }

        Color chatColor = resolveCurrentChatColor();

        ChatMessageBuilder builder = new ChatMessageBuilder();
        // We need to supply a color here, otherwise the image does not work...
        builder.append(chatColor, messageChatIcon + " ");
        // Replacing all closing cols with our chat color to reset it back to our default
        if (config.useChatColor()) {
            String pluginChatColorTag = ColorUtil.colorTag(chatColor);
            String chatColorFixedMessage = message.replaceAll(
                "</col>",
                pluginChatColorTag
            );
            builder.append(chatColor, chatColorFixedMessage);
        } else {
            builder.append(message);
        }

        String formattedMessage = builder.build();
        QueuedMessage queuedMessage = QueuedMessage.builder()
            .type(ChatMessageType.GAMEMESSAGE)
            .runeLiteFormattedMessage(formattedMessage)
            .build();
        chatMessageManager.queue(queuedMessage);
    }

    private boolean isReadyToSendPendingMessages() {
        return client.getGameState() == GameState.LOGGED_IN && !awaitingFirstTickAfterLogin;
    }

    private Color resolveCurrentChatColor() {
        ChatboxStyle chatboxStyle = resolveChatboxStyle(
            client.isResized(),
            client.getVarbitValue(VarbitID.CHATBOX_TRANSPARENCY)
        );
        return chatboxStyle == ChatboxStyle.TRANSPARENT
            ? config.chatColorTransparent()
            : config.chatColorOpaque();
    }

    private void clearPendingMessages() {
        pendingMessages.clear();
        awaitingFirstTickAfterLogin = false;
        log.debug("cleared pending chat messages");
    }

    enum ChatboxStyle {
        OPAQUE,
        TRANSPARENT
    }
}

package com.elertan;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.events.CommandExecuted;

/**
 * Handles "::bu" commands for plugin functionality and testing.
 */
@Slf4j
@Singleton
public class BUCommandService implements BUPluginLifecycle {

    @Inject
    private BUPluginConfig config;
    @Inject
    private PetDropService petDropService;
    @Inject
    private BUChatService buChatService;

    private final List<CommandInfo> commands = new ArrayList<>();
    private final List<CommandInfo> debugCommands = new ArrayList<>();

    @Override
    public void startUp() throws Exception {
        // General commands
        commands.add(new CommandInfo(
            "help",
            "Show available commands",
            null,
            this::handleHelp
        ));

        // Debug commands for pet detection testing
        debugCommands.add(new CommandInfo(
            "pet_following",
            "Simulate pet follow msg",
            null,
            this::handlePetFollowing
        ));
        debugCommands.add(new CommandInfo(
            "pet_backpack",
            "Simulate pet backpack msg",
            null,
            this::handlePetBackpack
        ));
        debugCommands.add(new CommandInfo(
            "pet_duplicate",
            "Simulate pet duplicate msg",
            null,
            this::handlePetDuplicate
        ));
        debugCommands.add(new CommandInfo(
            "pet_collection",
            "Simulate collection log",
            "<name>",
            this::handlePetCollection
        ));
    }

    @Override
    public void shutDown() throws Exception {
        commands.clear();
        debugCommands.clear();
    }

    /**
     * Process a command executed event and handle "::bu" commands.
     *
     * @param event the command executed event
     */
    public void onCommandExecuted(CommandExecuted event) {
        if (!event.getCommand().equalsIgnoreCase("bu")) {
            return;
        }

        String[] args = event.getArguments();
        if (args.length == 0) {
            buChatService.sendErrorMessage("Please enter a subcommand. Use ::bu help for list.");
            return;
        }

        String commandName = args[0].toLowerCase();
        String argument = args.length > 1 ? args[1] : null;

        log.debug("Parsed command: '{}', argument: '{}'", commandName, argument);

        Stream<CommandInfo> commandStream = config.enableDebugCommands()
            ? Stream.concat(commands.stream(), debugCommands.stream())
            : commands.stream();

        commandStream
            .filter(c -> c.getName().equals(commandName))
            .findFirst()
            .ifPresentOrElse(
                c -> c.getHandler().handle(argument),
                () -> buChatService.sendErrorMessage(
                    "Unknown command: ::bu " + commandName + ". Use ::bu help for list.")
            );
    }

    private void handleHelp(String arg) {
        buChatService.sendMessage("[Bronzeman Unleashed Commands]");
        commands.stream().map(this::formatCommandHelp).forEach(buChatService::sendMessage);

        if (!config.enableDebugCommands() || debugCommands.isEmpty()) {
            return;
        }

        buChatService.sendMessage("[Debug Commands]");
        debugCommands.stream().map(this::formatCommandHelp).forEach(buChatService::sendMessage);
    }

    private String formatCommandHelp(CommandInfo cmd) {
        StringBuilder sb = new StringBuilder();
        sb.append("::bu ").append(cmd.getName());
        Optional.ofNullable(cmd.getArgs()).ifPresent((args) -> sb.append(" ").append(args));
        sb.append(" - ").append(cmd.getDescription());
        return sb.toString();
    }

    private void handlePetFollowing(String arg) {
        log.debug("Debug: Simulating pet_following message");
        simulatePetMessage("You have a funny feeling like you're being followed.");
    }

    private void handlePetBackpack(String arg) {
        log.debug("Debug: Simulating pet_backpack message");
        simulatePetMessage("You feel something weird sneaking into your backpack.");
    }

    private void handlePetDuplicate(String arg) {
        log.debug("Debug: Simulating pet_duplicate message");
        simulatePetMessage("You have a funny feeling like you would have been followed...");
    }

    private void handlePetCollection(String petName) {
        if (petName == null || petName.isEmpty()) {
            buChatService.sendMessage("Usage: ::bu pet_collection <name>");
            return;
        }
        simulatePetMessage("New item added to your collection log: " + petName);
    }

    private void simulatePetMessage(String message) {
        petDropService.handleGameMessage(message);
        buChatService.sendMessage("[Debug] Pet drop simulated");
    }

    @Value
    private static class CommandInfo {

        String name;
        String description;
        String args;
        CommandHandler handler;
    }

    @FunctionalInterface
    private interface CommandHandler {

        void handle(String argument);
    }
}

package com.elertan;

import com.elertan.data.LastEventDataProvider;
import com.elertan.event.BUEvent;
import com.elertan.utils.Observable;
import com.elertan.utils.Subscription;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.time.OffsetDateTime;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

@Slf4j
@Singleton
public class BUEventService implements BUPluginLifecycle {

    private static final int STALE_EVENT_THRESHOLD_SECONDS = 30;
    private static final int CLEANUP_DELAY_SECONDS = 10;

    // Note: This observable is event-based (transient), not stateful.
    // It holds the "last event" and notifies on each new event.
    @Getter
    private final Observable<BUEvent> lastEvent = Observable.empty();
    private ScheduledExecutorService scheduler;
    private Subscription lastEventDataProviderSubscription;

    @Inject
    private LastEventDataProvider lastEventDataProvider;

    @Override
    public void startUp() throws Exception {
        scheduler = Executors.newSingleThreadScheduledExecutor();
        lastEventDataProviderSubscription = lastEventDataProvider.getEvents()
            .subscribe(event -> lastEvent.set(event));

        lastEventDataProvider.await(null).whenComplete((__, throwable) -> {
            if (throwable != null) {
                log.error("LastEventDataProvider await failed", throwable);
                return;
            }
            cleanupStaleEvents();
        });
    }

    @Override
    public void shutDown() throws Exception {
        if (lastEventDataProviderSubscription != null) {
            lastEventDataProviderSubscription.dispose();
            lastEventDataProviderSubscription = null;
        }
        if (scheduler != null) {
            scheduler.shutdown();
        }
    }

    public CompletableFuture<String> publishEvent(BUEvent event) {
        return lastEventDataProvider.add(event).thenApply(entryKey -> {
            if (entryKey != null) {
                // Events use POST to create unique entries (prevents data races).
                // Writer cleans up own entry after 10s - enough time for SSE propagation.
                // Stale events (>30s) cleaned on startup as fallback.
                scheduler.schedule(() -> {
                    lastEventDataProvider.remove(entryKey)
                        .exceptionally(ex -> {
                            log.error("Failed to cleanup own event", ex);
                            return null;
                        });
                }, CLEANUP_DELAY_SECONDS, TimeUnit.SECONDS);
            }
            return entryKey;
        });
    }

    private void cleanupStaleEvents() {
        lastEventDataProvider.readAll().thenAccept(entries -> {
            OffsetDateTime threshold = OffsetDateTime.now().minusSeconds(STALE_EVENT_THRESHOLD_SECONDS);
            for (Map.Entry<String, BUEvent> entry : entries.entrySet()) {
                BUEvent event = entry.getValue();
                if (event.getTimestamp() == null || event.getTimestamp().getValue().isBefore(threshold)) {
                    lastEventDataProvider.remove(entry.getKey())
                        .exceptionally(ex -> {
                            log.error("Failed to cleanup stale event", ex);
                            return null;
                        });
                }
            }
        }).exceptionally(ex -> {
            log.error("Failed to read events for cleanup", ex);
            return null;
        });
    }
}

package com.elertan;

import com.elertan.models.AccountConfiguration;
import com.elertan.overlays.ItemUnlockOverlay;
