    @Override
    public void startUp() throws Exception {
        unlockedItemsMapListener = new UnlockedItemsDataProvider.UnlockedItemsMapListener() {

            @Override
            public void onUpdate(UnlockedItem unlockedItem) {
                // Defer overlay to client thread to:
                // 1. Ensure any collection log chat messages from the same tick are processed first
                // 2. Safely access client.getAccountHash()
                clientThread.invokeLater(() -> {
                    boolean isLocalPlayer = client.getAccountHash() == unlockedItem.getAcquiredByAccountHash();

                    if (isLocalPlayer && collectionLogService.tryConsumeOverlaySuppression(unlockedItem.getName())) {
                        // Suppress overlay - native collection log UI already shows it
                        return;
                    }

                    itemUnlockOverlay.enqueueShowUnlock(
                        unlockedItem.getId(),
                        unlockedItem.getAcquiredByAccountHash(),
                        unlockedItem.getDroppedByNPCId()
                    );
                });

                // Chat notification - keep existing code below unchanged
                boolean hideChat = buPluginConfig.hideUnlockChatInMinigames() && minigameService.isInMinigameOrInstance();
                if (buPluginConfig.showItemUnlocksInChat() && !hideChat) {
                    buChatService.getItemIconTagIfEnabled(unlockedItem.getId())
                        .whenComplete((itemIconTag, throwable) -> {
                            if (throwable != null) {
                                log.error("Failed to get item icon tag", throwable);
                                return;
                            }

                            clientThread.invokeLater(() -> {
                                ChatMessageBuilder builder = new ChatMessageBuilder();
                                builder.append("Unlocked item ");
                                if (itemIconTag != null) {
                                    builder.append(buPluginConfig.chatHighlightColor(), itemIconTag);
                                    builder.append(" ");
                                }
                                builder.append(
                                    buPluginConfig.chatItemNameColor(),
                                    unlockedItem.getName()
                                );

                                if (client.getAccountHash()
                                    != unlockedItem.getAcquiredByAccountHash()) {
                                    Member member = memberService.getMemberByAccountHash(
                                        unlockedItem.getAcquiredByAccountHash());

                                    builder.append(" by ");
                                    builder.append(
                                        buPluginConfig.chatPlayerNameColor(),
                                        member.getName()
                                    );
                                }
                                Integer droppedByNpcId = unlockedItem.getDroppedByNPCId();
                                if (droppedByNpcId != null) {
                                    NPCComposition npcComposition = client.getNpcDefinition(
                                        droppedByNpcId);
                                    builder.append(" (drop from ");
                                    builder.append(
                                        buPluginConfig.chatNPCNameColor(),
                                        npcComposition.getName()
                                    );
                                    builder.append(")");
                                }

                                buChatService.sendMessage(builder.build());
                            });
                        }
                    );
                }

            }

            @Override
            public void onDelete(UnlockedItem unlockedItem) {
                // We can consider this re-locking items

                buChatService.getItemIconTagIfEnabled(unlockedItem.getId())
                    .whenComplete((itemIconTag, throwable) -> {
                    if (throwable != null) {
                        log.error("Failed to get item icon tag", throwable);
                        return;
                    }

                    ChatMessageBuilder builder = new ChatMessageBuilder();
                    if (itemIconTag != null) {
                        builder.append(buPluginConfig.chatHighlightColor(), itemIconTag);
                        builder.append(" ");
                    }
                    builder.append(buPluginConfig.chatItemNameColor(), unlockedItem.getName());
                    builder.append(" has been removed from unlocked items.");
                    buChatService.sendMessage(builder.build());
                });
            }
        };
        unlockedItemsDataProvider.addUnlockedItemsMapListener(unlockedItemsMapListener);
        stateSubscription = unlockedItemsDataProvider.getState()
            .subscribe(state -> unlockedItemDataProviderStateListener(state));
        accountConfigSubscription = accountConfigurationService.currentAccountConfiguration()
            .subscribe(this::currentAccountConfigurationChangeListener);
    }

    @Override
    public void shutDown() throws Exception {
        stateSubscription.dispose();
        accountConfigSubscription.dispose();
        unlockedItemsDataProvider.removeUnlockedItemsMapListener(unlockedItemsMapListener);
    }

    public void onGameStateChanged(GameStateChanged event) {
        if (!accountConfigurationService.isReady()
            || accountConfigurationService.getCurrentAccountConfiguration() == null) {
            return;
        }
        GameState gameState = event.getGameState();
        if (gameState == GameState.LOGGED_IN) {
            checkAndNotifyNonSupportedWorldType();
        } else if (gameState == GameState.LOGIN_SCREEN || gameState == GameState.HOPPING) {
            hasNotifiedPlayerOfNonSupportedWorldType = false;
        }
    }

    public void onItemContainerChanged(ItemContainerChanged event) {
        if (unlockedItemsDataProviderNotReady()) {
            return;
        }

        int containerId = event.getContainerId();
        if (!INCLUDED_CONTAINER_IDS.contains(containerId)) {
            return;
        }
        ItemContainer itemContainer = event.getItemContainer();
        unlockItemsFromItemContainer(itemContainer);
    }

    public void onServerNpcLoot(ServerNpcLoot event) {
        if (unlockedItemsDataProviderNotReady()) {
            return;
        }

        int npcId = event.getComposition().getId();
        event.getItems().stream()
            .map(ItemStack::getId)
            .filter(id -> !hasUnlockedItem(id))
            .map(itemId -> unlockItem(itemId, npcId))
            .forEach(addErrorLogging("Failed to unlock item in on server npc loot"));
    }

    public void onItemSpawned(ItemSpawned event) {
        if (unlockedItemsDataProviderNotReady()) {
            return;
        }

        // Check if inventory is full (28 items)
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            return;
        }

        Item[] items = inventory.getItems();
        int itemCount = 0;
        for (Item item : items) {
            if (item.getId() > 0) {
                itemCount++;
            }
        }
        if (itemCount < 28) {
            return;
        }

        // Check if item spawned at player's tile
        TileItem tileItem = event.getItem();
        Tile tile = event.getTile();

        // Only unlock items that belong to us (our drops when inventory is full)
        // Ignore items dropped by other players
        int ownership = tileItem.getOwnership();
        if (ownership != TileItem.OWNERSHIP_SELF && ownership != TileItem.OWNERSHIP_GROUP) {
            return;
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer == null) {
            return;
        }

        WorldPoint playerLocation = localPlayer.getWorldLocation();
        WorldPoint itemLocation = tile.getWorldLocation();

        if (!playerLocation.equals(itemLocation)) {
            return;
        }

        int itemId = tileItem.getId();
        if (hasUnlockedItem(itemId)) {
            return;
        }

        withErrorLogging(unlockItem(itemId), "Failed to unlock ground item");
    }

    // Code from: RuneProfile Plugin
    // Repository: https://github.com/ReinhardtR/runeprofile-plugin
    // License: BSD 2-Clause License
    // Unlock all unlocked items from the collection log when the interface is opened
    public void onScriptPreFired(ScriptPreFired preFired) {
        if (preFired.getScriptId() != 4100) {
            return;
        }

        // prevent reacting to scripts fired when opened from adventure log
        // e.g. other plugins might fire the collection log script when viewing other players' collection logs
        boolean isOpenedFromAdventureLog = client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
        if (isOpenedFromAdventureLog) {
            return;
        }

        int itemId = (int)preFired.getScriptEvent().getArguments()[1];
        withErrorLogging(unlockItem(itemId), "Failed to unlock item in on script pre fired");
    }

    public boolean hasUnlockedItem(int initialItemId) throws IllegalStateException {
        if (unlockedItemsDataProviderNotReady()) {
            throw new IllegalStateException("State is not READY");
        }

        int itemId = canonicalizeItemId(initialItemId);

        if (AUTO_UNLOCKED_ITEMS.contains(itemId)) {
//            log.info("Item with id {} is auto unlocked", itemId);
            return true;
        }

        Map<Integer, UnlockedItem> map = unlockedItemsDataProvider.getUnlockedItemsMap();
        if (map == null) {
            throw new IllegalStateException("Unlocked items map is null");
        }
        return map.containsKey(itemId);
    }

    public CompletableFuture<Void> removeUnlockedItemById(int itemId) {
        boolean hasUnlockedItem;
        try {
            hasUnlockedItem = hasUnlockedItem(itemId);
        } catch (Exception ex) {
            return CompletableFuture.failedFuture(ex);
        }
        if (!hasUnlockedItem) {
            log.warn("Attempted to remove unlocked item with id {} but it is not unlocked yet", itemId);
            return CompletableFuture.completedFuture(null);
        }

        return unlockedItemsDataProvider.removeUnlockedItemById(itemId)
            .thenRun(() -> log.debug("Removed unlocked item with id {}", itemId));
    }

    private boolean unlockedItemsDataProviderNotReady() {
        return unlockedItemsDataProvider.getState().get() != UnlockedItemsDataProvider.State.Ready;
    }

    private void currentAccountConfigurationChangeListener(
        AccountConfiguration accountConfiguration) {
        if (accountConfiguration == null) {
            return;
        }
        checkAndNotifyNonSupportedWorldType();
    }

    private void checkAndNotifyNonSupportedWorldType() {
        boolean isSupported = worldTypeService.isCurrentWorldSupported();

        if (isSupported) {
            return;
        }
        // Because this check can invoked from logging in/hopping to a new world
        // as well as configuring the plugin, we need to make sure we only notify
        // once for an unsupported world type
        if (hasNotifiedPlayerOfNonSupportedWorldType) {
            return;
        }
        hasNotifiedPlayerOfNonSupportedWorldType = true;
        buChatService.sendMessage(chatMessageProvider.messageFor(MessageKey.ITEM_UNLOCKS_UNSUPPORTED_WORLD));
    }

    private CompletableFuture<Void> unlockItem(int initialItemId) {
        return unlockItem(initialItemId, null);
    }

    private CompletableFuture<Void> unlockItem(int initialItemId, Integer droppedByNPCId) {
        if (initialItemId <= 1) {
            return CompletableFuture.failedFuture(new IllegalArgumentException("Item id must be greater than 1"));
        }

        // We don't support all world types, for example we don't want unlocks on seasonal modes
        if (!worldTypeService.isCurrentWorldSupported()) {
            log.debug("Current world is not supported for unlocking items");
            return CompletableFuture.completedFuture(null);
        }

        // Disable LMS unlocks
        if (minigameService.isPlayingLastManStanding()) {
            return CompletableFuture.completedFuture(null);
        }
        if (ExcludedItemIds.IDS.contains(initialItemId)) {
            return CompletableFuture.completedFuture(null);
        }

        // Skip placeholders
        ItemComposition initialItemComposition = client.getItemDefinition(initialItemId);
        // This method returns -1 if the item is NOT a placeholder
        if (initialItemComposition.getPlaceholderTemplateId() != -1) {
            return CompletableFuture.completedFuture(null);
        }

        int itemId;
        try {
            itemId = canonicalizeItemId(initialItemId);

            if (hasUnlockedItem(itemId)) {
                return CompletableFuture.completedFuture(null);
            }
        } catch (Exception ex) {
            return CompletableFuture.failedFuture(ex);
        }

        // Get new item definition after canonicalization
        ItemComposition itemComposition = client.getItemDefinition(itemId);
        final boolean fIsTradeable = itemComposition.isTradeable();
        final String fItemName = itemComposition.getName();
        final int fItemId = itemId;
        // Cache accountHash before async call - client methods require client thread
        final long acquiredByAccountHash = client.getAccountHash();
        return gameRulesService
            .waitUntilGameRulesReady(null)
            .thenCompose(__ -> {
                GameRules gameRules = gameRulesService.getGameRules().get();
                log.debug(
                    "is only for traded items: {} - is tradeable: {}",
                    gameRules.isOnlyForTradeableItems(),
                    fIsTradeable
                );
                if (gameRules.isOnlyForTradeableItems() && !fIsTradeable) {
                    return CompletableFuture.completedFuture(null);
                }

                ISOOffsetDateTime acquiredAt = new ISOOffsetDateTime(OffsetDateTime.now());

                UnlockedItem unlockedItem = new UnlockedItem(
                    fItemId,
                    fItemName,
                    acquiredByAccountHash,
                    acquiredAt,
                    droppedByNPCId
                );
                log.debug("Unlocked item ({}) '{}'", fItemId, fItemName);
                return unlockedItemsDataProvider.addUnlockedItem(unlockedItem);
            });
    }

    private int canonicalizeItemId(int initialItemId) {
        // We want the base item, not a noted item or similar
        int itemId = itemManager.canonicalize(initialItemId);

        // If necessary, we also need to map the item to a different one
        // for example ensouled heads have multiple variations of the same item
        // one that you can re-animate, and one you cannot.
        // We don't want to unlock these multiple times
        if (ITEM_MAPPING_ITEM_IDS.contains(itemId)) {
            Collection<ItemMapping> mappings = ItemMapping.map(itemId);
            if (mappings == null || mappings.isEmpty()) {
                throw new RuntimeException("Failed to map item id " + itemId);
            }
            final ItemMapping mapping = mappings.stream().findFirst().get();
            itemId = mapping.getTradeableItem();
        }

        // If necessary, we also need to map the item to a different one by name
        // for example clue scrolls have like 50 variations, but they're
        // essentially the same item
        String itemName = client.getItemDefinition(itemId).getName();
        return MAP_ITEM_NAMES.getOrDefault(itemName, itemId);
    }

    private void unlockedItemDataProviderStateListener(AbstractDataProvider.State state) {
        if (state != AbstractDataProvider.State.Ready) {
            return;
        }
//        if (hasUnlockedItemDataProviderReadyStateBeenSeen) {
//            return;
//        }
//        hasUnlockedItemDataProviderReadyStateBeenSeen = true;

        clientThread.invokeLater(() -> {
            Map<Integer, UnlockedItem> map = unlockedItemsDataProvider.getUnlockedItemsMap();
            if (map == null) {
                throw new IllegalStateException("Unlocked items map is null");
            }
            int unlockedItemsSize = map.size();
            buChatService.sendMessage(String.format(
                "Loaded with %d unlocked items.",
                unlockedItemsSize
            ));

            // This is the first time the unlocked items are ready
            log.debug(
                "Unlocked items data provider ready for item unlock service first time, checking inventory");
            INCLUDED_CONTAINER_IDS.stream()
                .map(client::getItemContainer)
                .forEach(this::unlockItemsFromItemContainer);
        });
    }

    private void unlockItemsFromItemContainer(ItemContainer itemContainer) {
        if (unlockedItemsDataProviderNotReady()) {
            return;
        }

        if (itemContainer == null) {
            return;
        }

        Arrays.stream(itemContainer.getItems())
            .filter(Objects::nonNull)
            .filter(item -> item.getQuantity() > 0)
            .map(Item::getId)
            .filter(id -> !hasUnlockedItem(id))
            .map(this::unlockItem)
            .forEach(addErrorLogging("Failed to unlock item in item container changed"));
    }
}

package com.elertan;

import com.elertan.event.ValuableLootBUEvent;
import com.elertan.models.GameRules;
import com.elertan.models.ISOOffsetDateTime;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.time.OffsetDateTime;
import java.util.Collection;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;

@Slf4j
@Singleton
public class LootValuationService implements BUPluginLifecycle {

    @Inject
    private Client client;
    @Inject
    private ItemManager itemManager;
    @Inject
    private BUEventService buEventService;
    @Inject
    private GameRulesService gameRulesService;
    @Inject
    private AccountConfigurationService accountConfigurationService;

    @Override
    public void startUp() throws Exception {

    }

    @Override
    public void shutDown() throws Exception {

    }


    public void onServerNpcLoot(ServerNpcLoot event) {
        if (!accountConfigurationService.isReady()
            || accountConfigurationService.getCurrentAccountConfiguration() == null) {
            return;
        }

        Collection<ItemStack> itemStacks = event.getItems();
        if (itemStacks == null) {
            return;
        }
        GameRules gameRules = gameRulesService.getGameRules().get();
        if (gameRules == null) {
            return;
        }
        Integer valuableLootNotificationThreshold = gameRules.getValuableLootNotificationThreshold();
        if (valuableLootNotificationThreshold == null || valuableLootNotificationThreshold <= 0) {
            return;
        }
        NPCComposition npcComposition = event.getComposition();
        int npcId = npcComposition.getId();

        for (ItemStack itemStack : itemStacks) {
            int itemId = itemStack.getId();
            long quantity = itemStack.getQuantity();
            long price = itemManager.getItemPrice(itemId);
            long totalPrice = price * quantity;

            if (totalPrice >= valuableLootNotificationThreshold) {
                ValuableLootBUEvent valuableLootBUEvent = new ValuableLootBUEvent(
                    client.getAccountHash(),
                    new ISOOffsetDateTime(OffsetDateTime.now()),
                    itemId,
                    quantity,
                    price,
                    npcId
                );
                buEventService.publishEvent(valuableLootBUEvent).whenComplete((__, throwable) -> {
                    if (throwable != null) {
                        log.error("error publishing valuable loot event", throwable);
                        return;
                    }
                    log.debug("published valuable loot event");
                });
            }
        }
    }
}

package com.elertan;

import com.elertan.data.MembersDataProvider;
import com.elertan.models.AccountConfiguration;
import com.elertan.models.ISOOffsetDateTime;
import com.elertan.models.Member;
import com.elertan.models.MemberRole;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;
import com.elertan.utils.Subscription;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageBuilder;

@Slf4j
@Singleton
public class MemberService implements BUPluginLifecycle {

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private AccountConfigurationService accountConfigurationService;
    @Inject
    private MembersDataProvider membersDataProvider;
    private Subscription accountConfigSubscription;
    @Inject
    private BUChatService buChatService;
    @Inject
    private BUPluginConfig buPluginConfig;
    private MembersDataProvider.MemberMapListener memberMapListener;

    @Override
    public void startUp() throws Exception {
        // Data provider callbacks are not on client thread - wrap in clientThread.invoke()
        memberMapListener = new MembersDataProvider.MemberMapListener() {
            @Override
            public void onUpdate(Member member, Member old) {
                clientThread.invoke(() -> {
                    log.debug(
                        "member service -> member update: {} - old: {}",
                        member == null ? null : member.toString(),
                        old == null ? null : old.toString()
                    );

                    if (old == null) {
                        // If the updated member is not us, inform of a join
                        if (member.getAccountHash() != client.getAccountHash()) {
                            ChatMessageBuilder builder = new ChatMessageBuilder();
                            builder.append(buPluginConfig.chatPlayerNameColor(), member.getName());
                            builder.append(" has joined your Group Bronzeman.");
                            buChatService.sendMessage(builder.build());
                        }
                    } else {
                        if (!Objects.equals(member.getName(), old.getName())) {
                            ChatMessageBuilder builder = new ChatMessageBuilder();
                            builder.append(buPluginConfig.chatPlayerNameColor(), old.getName());
                            builder.append(" has changed their name to ");
                            builder.append(buPluginConfig.chatPlayerNameColor(), member.getName());
                            builder.append(".");
                            buChatService.sendMessage(builder.build());
                        }
                        if (member.getRole() != old.getRole()) {
                            ChatMessageBuilder builder = new ChatMessageBuilder();
                            builder.append(buPluginConfig.chatPlayerNameColor(), member.getName());
                            builder.append(" has changed their role from ");
                            builder.append(
                                buPluginConfig.chatHighlightColor(),
                                old.getRole().toString()
                            );
                            builder.append(" to ");
                            builder.append(
                                buPluginConfig.chatHighlightColor(),
                                member.getRole().toString()
                            );
                            builder.append(".");
                            buChatService.sendMessage(builder.build());
                        }
                    }
                });
            }

            @Override
            public void onDelete(Member member) {
                clientThread.invoke(() -> {
                    ChatMessageBuilder builder = new ChatMessageBuilder();
                    builder.append(buPluginConfig.chatPlayerNameColor(), member.getName());
                    builder.append(" has left your Group Bronzeman.");
                    buChatService.sendMessage(builder.build());
                });
            }
        };

        accountConfigSubscription = accountConfigurationService.currentAccountConfiguration()
            .subscribe(this::currentAccountConfigurationChangeListener);
        membersDataProvider.addMemberMapListener(memberMapListener);
    }

    @Override
    public void shutDown() throws Exception {
        membersDataProvider.removeMemberMapListener(memberMapListener);
        if (accountConfigSubscription != null) {
            accountConfigSubscription.dispose();
            accountConfigSubscription = null;
        }
    }

    public Member getMemberByName(String playerName) {
        if (playerName == null) {
            return null;
        }
        if (membersDataProvider.getState().get() != MembersDataProvider.State.Ready) {
            throw new IllegalStateException("Member data provider is not ready");
        }
        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null || membersMap.isEmpty()) {
            return null;
        }
        for (Member member : membersMap.values()) {
            String name = member.getName();
            if (playerName.equalsIgnoreCase(name)) {
                return member;
            }
        }
        return null;
    }

    public Member getMemberByAccountHash(long accountHash) {
        if (membersDataProvider.getState().get() != MembersDataProvider.State.Ready) {
            throw new IllegalStateException("Member data provider is not ready");
        }
        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null) {
            return null;
        }
        return membersMap.get(accountHash);
    }

    public Member getMyMember() {
        return getMemberByAccountHash(client.getAccountHash());
    }

    public boolean isPlayingAlone() {
        if (membersDataProvider.getState().get() != MembersDataProvider.State.Ready) {
            throw new IllegalStateException("Member data provider is not ready");
        }
        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null || membersMap.isEmpty()) {
            return true;
        }
        return membersMap.size() == 1;
    }

    private void currentAccountConfigurationChangeListener(
        AccountConfiguration accountConfiguration) {
        if (accountConfiguration == null) {
            return;
        }

        // When we have an account, we want to wait until the members are ready
        // if we have no members, we add ourselves as the owner
        // if we do have members, but not us, we add ourselves as a member
        membersDataProvider.await(null)
            .whenComplete((void1, awaitThrowable) -> {
                if (awaitThrowable != null) {
                    log.error(
                        "member service error whilst waiting till members data provider to become ready",
                        awaitThrowable
                    );
                    return;
                }

                clientThread.invokeLater(this::whenMembersDataProviderReadyAfterAccountConfigurationSet);
            });
    }

    private void whenMembersDataProviderReadyAfterAccountConfigurationSet() {
        Player player = client.getLocalPlayer();
        String name = player.getName();
        if (name == null) {
            // Wait till name gets set...
            clientThread.invokeLater(this::whenMembersDataProviderReadyAfterAccountConfigurationSet);
            return;
        }

        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null) {
            log.error("member service error members map is null but should be init here");
            return;
        }

        long accountHash = client.getAccountHash();
        if (accountHash == -1) {
            log.error("member service error whilst getting account hash");
            return;
        }

        log.debug("member service check if we need to add a member...");

        boolean shouldUpdateMember = false;
        boolean shouldBeOwner = false;
        if (membersMap.isEmpty()) {
            shouldUpdateMember = true;
            shouldBeOwner = true;
        } else if (!membersMap.containsKey(accountHash)) {
            shouldUpdateMember = true;
        } else {
            Member member = membersMap.get(accountHash);
            String memberName = member.getName();
            if (memberName == null || !memberName.equals(name)) {
                log.debug(
                    "member service -> name changed from '{}' to '{}' issue-ing member update",
                    memberName,
                    name
                );
                shouldUpdateMember = true;
            }
        }

        log.debug(
            "should update member: {} - should be owner: {}",
            shouldUpdateMember,
            shouldBeOwner
        );

        if (shouldUpdateMember) {
            log.debug("adding member...");
            ISOOffsetDateTime now = new ISOOffsetDateTime(OffsetDateTime.now());

            MemberRole memberRole = shouldBeOwner ? MemberRole.Owner : MemberRole.Member;
            Member member = new Member(
                accountHash,
                name,
                now,
                memberRole
            );

            membersDataProvider.addMember(member).whenComplete((void2, addMemberThrowable) -> {
                if (addMemberThrowable != null) {
                    log.error("member service error whilst adding member", addMemberThrowable);
                    return;
                }
                log.debug("member added!");
            });
        }
    }

    public CompletableFuture<Void> promoteMemberToOwner(long accountHash) {
        CompletableFuture<Void> future = new CompletableFuture<>();

        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null) {
            future.completeExceptionally(new IllegalStateException("members map is null"));
            return future;
        }
        Member memberToPromote = membersMap.get(accountHash);
        if (memberToPromote == null) {
            future.completeExceptionally(new IllegalStateException("member to promote is null"));
            return future;
        }
        if (memberToPromote.getRole() == MemberRole.Owner) {
            future.complete(null);
            return future;
        }

        List<Member> membersToDemote = membersMap.values()
            .stream()
            .filter(x -> x.getAccountHash() != accountHash && x.getRole() == MemberRole.Owner)
            .collect(Collectors.toList());

        Member newMemberToPromote = new Member(
            memberToPromote.getAccountHash(),
            memberToPromote.getName(),
            memberToPromote.getJoinedAt(),
            MemberRole.Owner
        );
        membersDataProvider.updateMember(newMemberToPromote).whenComplete((void1, throwable) -> {
            if (throwable != null) {
                future.completeExceptionally(throwable);
                return;
            }

            List<CompletableFuture<Void>> demoteFutures = new ArrayList<>();
            for (Member memberToDemote : membersToDemote) {
                Member newMemberToDemote = new Member(
                    memberToDemote.getAccountHash(),
                    memberToDemote.getName(),
                    memberToDemote.getJoinedAt(),
                    MemberRole.Member
                );
                CompletableFuture<Void> fut = membersDataProvider.updateMember(newMemberToDemote);
                demoteFutures.add(fut);
            }

            if (!demoteFutures.isEmpty()) {
                CompletableFuture.allOf(demoteFutures.toArray(new CompletableFuture[0]))
                    .whenComplete((void2, throwable2) -> {
                        if (throwable2 != null) {
                            future.completeExceptionally(throwable2);
                            return;
                        }

                        future.complete(null);
                    });
                return;
            }

            future.complete(null);
        });

        return future;
    }

    public CompletableFuture<Void> leaveGroup() {
        CompletableFuture<Void> future = new CompletableFuture<>();

        Member myMember;
        try {
            myMember = getMyMember();
        } catch (Exception e) {
            future.completeExceptionally(e);
            return future;
        }
        if (myMember == null) {
            log.warn("Attempted to leave group but we are not a member");
            future.complete(null);
            return future;
        }

        membersDataProvider.removeMember(myMember.getAccountHash())
            .whenComplete((void1, throwable) -> {
                if (throwable != null) {
                    log.error("Failed to remove member", throwable);
                    future.completeExceptionally(throwable);
                    return;
                }

                future.complete(null);
            });

        return future;
    }

    public CompletableFuture<Void> leaveGroupAndPromoteOldestMember() {
        CompletableFuture<Void> future = new CompletableFuture<>();

        Member myMember;
        try {
            myMember = getMyMember();
        } catch (Exception e) {
            future.completeExceptionally(e);
            return future;
        }
        if (myMember == null) {
            log.warn("Attempted to leave group but we are not a member");
            future.complete(null);
            return future;
        }

        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null) {
            future.completeExceptionally(new IllegalStateException("members map is null"));
            return future;
        }

        Optional<Member> otherOldestMemberOpt = membersMap.values()
            .stream()
            .filter(x -> x.getAccountHash() != myMember.getAccountHash())
            .min(Comparator.comparing(x -> x.getJoinedAt().getValue()));

        if (!otherOldestMemberOpt.isPresent()) {
            log.warn("Attempted to leave group and promote but there are no other members");
            future.complete(null);
            return future;
        }
        Member otherOldestMember = otherOldestMemberOpt.get();

        promoteMemberToOwner(otherOldestMember.getAccountHash()).whenComplete((void1, throwable) -> {
            if (throwable != null) {
                future.completeExceptionally(throwable);
                return;
            }

            leaveGroup().whenComplete((void2, throwable2) -> {
                if (throwable2 != null) {
                    future.completeExceptionally(throwable2);
                    return;
                }

                future.complete(null);
            });
        });

        return future;
    }
}

package com.elertan;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.Set;
import net.runelite.api.Client;

@Singleton
public class MinigameService {

    // Varbits - https://github.com/runelite/runelite/blob/master/runelite-api/src/main/java/net/runelite/api/Varbits.java
    private static final int LAST_MAN_STANDING_VARBIT_ID = 5314;
    private static final int IN_RAID_VARBIT = 5432;  // CoX
    private static final int TOB_VARBIT = 6440;      // ToB
    private static final int BA_VARBIT = 3923;       // Barbarian Assault

    // Inferno - https://github.com/JourneyDeprecated/OpenOSRS/blob/master/runelite-client/src/main/java/net/runelite/client/plugins/inferno/InfernoPlugin.java
    private static final int INFERNO_REGION = 9043;
    // Gauntlet - https://github.com/runelite/runelite/blob/master/runelite-client/src/main/java/net/runelite/client/plugins/screenshot/ScreenshotPlugin.java
    private static final int GAUNTLET_REGION = 7512;
    private static final int CORRUPTED_GAUNTLET_REGION = 7768;

    // ToA Region IDs - https://github.com/LlemonDuck/tombs-of-amascut
    private static final Set<Integer> TOA_REGIONS = ImmutableSet.of(
        13454,  // Lobby
        14160,  // Nexus
        15698,  // Crondis
        15700,  // Zebak
        14162,  // Scabaras
        14164,  // Kephri
        15186,  // Apmeken
        15188,  // Ba-Ba
        14674,  // Het
        14676,  // Akkha
        15184,  // Wardens P1
        15696,  // Wardens P2
        14672   // Tomb
    );

    // Fight Caves Region IDs - https://github.com/runelite/runelite/pull/2351
    private static final Set<Integer> FIGHT_CAVES_REGIONS = ImmutableSet.of(
        9294, 9295, 9296,
        9550, 9551, 9552,
        9806, 9807, 9808
    );

    @Inject
    private Client client;

    public boolean isPlayingLastManStanding() {
        return client.getVarbitValue(LAST_MAN_STANDING_VARBIT_ID) == 1;
    }

    public boolean isInMinigameOrInstance() {
        if (isPlayingLastManStanding()) {
            return true;
        }

        // Raids via varbit
        if (client.getVarbitValue(IN_RAID_VARBIT) > 0) {
            return true;
        }
        if (client.getVarbitValue(TOB_VARBIT) > 0) {
            return true;
        }
        if (client.getVarbitValue(BA_VARBIT) > 0) {
            return true;
        }

        // Region-based (Inferno, Gauntlet, ToA, Fight Caves)
        int[] regions = client.getTopLevelWorldView().getMapRegions();
        if (regions != null) {
            for (int region : regions) {
                if (region == INFERNO_REGION ||
                    region == GAUNTLET_REGION ||
                    region == CORRUPTED_GAUNTLET_REGION ||
                    TOA_REGIONS.contains(region) ||
                    FIGHT_CAVES_REGIONS.contains(region)) {
                    return true;
                }
            }
        }

        return false;
    }
}

package com.elertan;

import com.elertan.chat.CollectionLogUnlockParsedGameMessage;
import com.elertan.chat.GameMessageParser;
import com.elertan.event.PetDropBUEvent;
import com.elertan.models.ISOOffsetDateTime;
import com.elertan.utils.TextUtils;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.time.OffsetDateTime;
import java.util.HashSet;
import java.util.Set;
import java.util.regex.Pattern;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;

/**
 * Service for detecting pet drops and emitting PetDropBUEvent.
 *
 * <p>Detection strategy:
 * <ol>
 *   <li><b>Collection log message</b> - When "New item added to your collection log: X" fires,
 *       we parse the pet name directly from the message. This only works for first-time drops.</li>
 *   <li><b>Follower check</b> - When a "funny feeling" message fires and the player didn't have
 *       a follower before, we check client.getFollower() to get the pet name.</li>
 *   <li><b>Inventory check</b> - When a "funny feeling" message fires and the player had a follower,
 *       we check for new pet items in inventory.</li>
 *   <li><b>Probita edge case</b> - When the player has a follower and full inventory, the pet
 *       goes to Probita (pet insurance NPC) and we cannot identify which pet it was.
 *       In this case, we emit the event with petName = null.</li>
 * </ol>
 *
 * <p>We track follower state pre-emptively on each game tick because we need to know
 * if the player had a follower BEFORE the pet drop message appeared.
 */
@Slf4j
@Singleton
public class PetDropService implements BUPluginLifecycle {

    // Chat message patterns
    private static final String PET_MESSAGE_FOLLOWING = "You have a funny feeling like you're being followed";
    private static final String PET_MESSAGE_BACKPACK = "You feel something weird sneaking into your backpack";
    private static final String PET_MESSAGE_DUPLICATE = "You have a funny feeling like you would have been followed";
    private static final Pattern COLLECTION_LOG_PATTERN = Pattern.compile(
        "New item added to your collection log: (.+)");

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private BUEventService buEventService;
    @Inject
    private ItemManager itemManager;
    @Inject
    private AccountConfigurationService accountConfigurationService;

    // All pet item IDs loaded from game enum
    private Set<Integer> petItemIds = new HashSet<>();

    // Track state for pet detection
    private boolean hadFollower = false;
    private Set<Integer> inventoryPetItemIds = new HashSet<>();
    // Previous tick's inventory pets - used to detect new pets added this tick
    private Set<Integer> previousInventoryPetItemIds = new HashSet<>();
    private boolean petsLoaded = false;

    @Override
    public void startUp() throws Exception {
        // Pets will be loaded on first game tick when client is ready
    }

    @Override
    public void shutDown() throws Exception {
        petItemIds.clear();
        inventoryPetItemIds.clear();
        previousInventoryPetItemIds.clear();
        petsLoaded = false;
        hadFollower = false;
    }

    /**
     * Load all pet item IDs from the game's PETS enum. Must be called on client thread when game
     * state is LOGGED_IN.
     */
    private void loadPetItemIds() {
        if (petsLoaded || client.getGameState() != GameState.LOGGED_IN) {
            return;
        }

        try {
            EnumComposition petsEnum = client.getEnum(EnumID.PETS);
            petItemIds.clear();
            for (int i = 0; i < petsEnum.size(); i++) {
                int petItemId = petsEnum.getIntValue(i);
                petItemIds.add(petItemId);
            }
            petsLoaded = true;
        } catch (Exception e) {
            log.error("Failed to load pet item IDs", e);
        }
    }

    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGIN_SCREEN) {
            petsLoaded = false;
            hadFollower = false;
            inventoryPetItemIds.clear();
            previousInventoryPetItemIds.clear();
        }
    }

    public void onGameTick(GameTick event) {
        if (client.getGameState() != GameState.LOGGED_IN) {
            return;
        }

        // Load pets on first tick after login
        if (!petsLoaded) {
            loadPetItemIds();
        }

        // Track follower state for pet detection
        hadFollower = client.getFollower() != null;

        // Track current pet items in inventory (save previous state first)
        updateInventoryPetItems();
    }

    private void updateInventoryPetItems() {
        // Save current state as previous before updating
        previousInventoryPetItemIds.clear();
        previousInventoryPetItemIds.addAll(inventoryPetItemIds);

        inventoryPetItemIds.clear();
        ItemContainer inventory = client.getItemContainer(InventoryID.INV);
        if (inventory == null) {
            return;
        }

        for (Item item : inventory.getItems()) {
            if (item.getId() > 0 && petItemIds.contains(item.getId())) {
                inventoryPetItemIds.add(item.getId());
            }
        }
    }

    public void onChatMessage(ChatMessage event) {
        if (event.getType() != ChatMessageType.GAMEMESSAGE
            && event.getType() != ChatMessageType.SPAM) {
            return;
        }

        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }

        String message = event.getMessage();
        handleGameMessage(message);
    }

    private void handleCollectionLogPet(String itemName) {
        String cleanName = TextUtils.sanitizeItemName(itemName);
        for (int petItemId : petItemIds) {
            ItemComposition comp = itemManager.getItemComposition(petItemId);
            String petName = TextUtils.sanitizeItemName(comp.getName());
            if (cleanName.equals(petName)) {
                emitPetDropEvent(petItemId, false);
                return;
            }
        }
    }

    private void handlePetDropMessage(String message) {
        // Use clientThread.invokeLater to ensure game state has updated
        clientThread.invokeLater(() -> {
            Integer petItemId = identifyPetItemId(message);
            boolean isDuplicate = message.contains(PET_MESSAGE_DUPLICATE);
            log.debug("Pet drop detected: {} (itemId: {}, isDuplicate: {})", message, petItemId, isDuplicate);
            emitPetDropEvent(petItemId, isDuplicate);
        });
    }

    /**
     * Identify which pet was received based on current game state.
     *
     * @param message the chat message that triggered detection
     * @return pet item ID, or null if cannot be identified (Probita edge case)
     */
    @Nullable
    private Integer identifyPetItemId(String message) {
        // Case 1: Player didn't have a follower - check for new follower
        if (!hadFollower) {
            NPC follower = client.getFollower();
            if (follower != null) {
                String followerName = follower.getName();
                // Look up item ID from follower name
                for (int petItemId : petItemIds) {
                    ItemComposition comp = itemManager.getItemComposition(petItemId);
                    if (TextUtils.sanitizeItemName(comp.getName()).equals(TextUtils.sanitizeItemName(followerName))) {
                        return petItemId;
                    }
                }
                // Follower found but no matching pet item - return null
                log.warn("Found follower '{}' but no matching pet item ID", followerName);
                return null;
            }
        }

        // Case 2: Player had a follower - check inventory for new pet
        // Compare against previous tick's inventory to find newly added pet
        if (hadFollower || message.contains(PET_MESSAGE_BACKPACK)) {
            ItemContainer inventory = client.getItemContainer(InventoryID.INV);
            if (inventory != null) {
                for (Item item : inventory.getItems()) {
                    int itemId = item.getId();
                    if (itemId > 0 && petItemIds.contains(itemId) &&
                        !previousInventoryPetItemIds.contains(itemId)) {
                        // Found a new pet in inventory (wasn't there last tick)
                        return itemId;
                    }
                }
            }
        }

        // Case 3: Probita edge case - had follower and full inventory
        // Cannot identify pet, return null
        log.info(
            "Could not identify pet - likely Probita edge case (follower + full inventory) (message: {})",
            message
        );
        return null;
    }

    private void emitPetDropEvent(@Nullable Integer petItemId, boolean isDuplicate) {
        PetDropBUEvent event = new PetDropBUEvent(
            client.getAccountHash(),
            new ISOOffsetDateTime(OffsetDateTime.now()),
            petItemId,
            isDuplicate
        );
        buEventService.publishEvent(event);
    }

    /**
     * Handle a game message
     *
     * @param message the message to handle
     */
    public void handleGameMessage(String message) {
        // Check for collection log message first (gives exact pet name for first-time drops)
        CollectionLogUnlockParsedGameMessage parsedGameMessage =
            GameMessageParser.tryParseCollectionLogUnlock(message);
        if (parsedGameMessage != null) {
            handleCollectionLogPet(parsedGameMessage.getItemName());
            return;
        }

        if (message.contains(PET_MESSAGE_FOLLOWING) ||
            message.contains(PET_MESSAGE_BACKPACK) ||
            message.contains(PET_MESSAGE_DUPLICATE)) {
            handlePetDropMessage(message);
        }
    }
}

package com.elertan;

import com.elertan.chat.ChatMessageProvider;
import com.elertan.chat.ChatMessageProvider.MessageKey;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import lombok.Getter;

@Singleton
public class PolicyService implements BUPluginLifecycle {

    @Inject
    private BUPluginConfig buPluginConfig;
    @Inject
    private BUChatService buChatService;
    @Inject
    private ChatMessageProvider chatMessageProvider;

    @Getter
    private boolean hasNotifiedGameRulesNotLoaded = false;

    @Override
    public void startUp() throws Exception {

    }

    @Override
    public void shutDown() throws Exception {

    }

    public void notifyGameRulesNotLoaded() {
        if (hasNotifiedGameRulesNotLoaded) {
            return;
        }
        hasNotifiedGameRulesNotLoaded = true;

        buChatService.sendErrorMessage(chatMessageProvider.messageFor(
            MessageKey.STILL_LOADING_TEMPORARY_STRICT_GAME_RULES_ENFORCEMENT));
    }
}

package com.elertan;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.EnumSet;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.WorldType;

@Singleton
public class WorldTypeService implements BUPluginLifecycle {

    private static final Set<WorldType> SUPPORTED_WORLD_TYPES = Set.of(
        WorldType.MEMBERS,
        WorldType.PVP,
        WorldType.BOUNTY,
        WorldType.SKILL_TOTAL,
        WorldType.HIGH_RISK,
        WorldType.FRESH_START_WORLD,
        WorldType.LAST_MAN_STANDING
    );

    @Inject
    private Client client;

    @Override
    public void startUp() throws Exception {
    }

    @Override
    public void shutDown() throws Exception {
    }

    /**
     * Checks if the current world type is supported for bronzeman features.
     * Must be called from client thread.
     *
     * @return true if policies and unlocks should apply, false otherwise
     */
    public boolean isCurrentWorldSupported() {
        EnumSet<WorldType> worldTypes = client.getWorldType();
        // Empty set returns true (vacuous truth via allMatch), which is expected
        return worldTypes.stream().allMatch(SUPPORTED_WORLD_TYPES::contains);
    }
}

package com.elertan.chat;

import com.elertan.BUChatService;
import com.elertan.BUEventService;
import com.elertan.BUPluginConfig;
import com.elertan.BUPluginLifecycle;
import com.elertan.MemberService;
import com.elertan.event.*;
import com.elertan.models.Member;
import com.elertan.utils.AsyncUtils;
import com.google.common.collect.ImmutableMap;
import com.elertan.utils.Subscription;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import java.util.function.BiFunction;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.chat.ChatMessageBuilder;

import static com.elertan.utils.AsyncUtils.withErrorLogging;

@Slf4j
@Singleton
public class ChatMessageEventBroadcaster implements BUPluginLifecycle {

    @Inject
    private Client client;
    @Inject
    private AsyncUtils asyncUtils;
    @Inject
    private BUPluginConfig config;
    @Inject
    private BUEventService buEventService;
    @Inject
    private BUChatService buChatService;
    @Inject
    private MemberService memberService;

    private final Map<BUEventType, BiFunction<BUEvent, Member, CompletableFuture<String>>>
        eventToChatMessageTransformers =
        ImmutableMap.<BUEventType, BiFunction<BUEvent, Member, CompletableFuture<String>>>builder()
            .put(BUEventType.SkillLevelUpAchievement, this::transformSkillLevelUpAchievementEvent)
            .put(BUEventType.TotalLevelAchievement, this::transformTotalLevelAchievementEvent)
            .put(BUEventType.CombatLevelUpAchievement, this::transformCombatLevelUpAchievementEvent)
            .put(BUEventType.CombatTaskAchievement, this::transformCombatTaskAchievementEvent)
            .put(BUEventType.QuestCompletionAchievement, this::transformQuestCompletionAchievementEvent)
            .put(BUEventType.DiaryCompletionAchievement, this::transformDiaryCompletionAchievementEvent)
            .put(BUEventType.CollectionLogUnlockAchievement, this::transformCollectionLogAchievementEvent)
            .put(BUEventType.ValuableLoot, this::transformValuableLootEvent)
            .put(BUEventType.PetDrop, this::transformPetDropEvent)
            .build();

    private Subscription eventSubscription;

    @Override
    public void startUp() throws Exception {
        eventSubscription = buEventService.getLastEvent().subscribe(this::onEvent);
    }

    @Override
    public void shutDown() throws Exception {
        if (eventSubscription != null) {
            eventSubscription.dispose();
            eventSubscription = null;
        }
    }

    private void onEvent(BUEvent event) {
        BUEventType type = event.getType();
        BiFunction<BUEvent, Member, CompletableFuture<String>> chatMessageTransformer =
            eventToChatMessageTransformers.get(type);
        if (chatMessageTransformer == null) {
            return;
        }

        Member member = memberService.getMemberByAccountHash(event.getDispatchedFromAccountHash());
        if (member == null) {
            log.error("could not find member by hash {}", event.getDispatchedFromAccountHash());
            return;
        }

        // Skip if the event was dispatched from the same account
        asyncUtils.runOnClientThread(() -> client.getAccountHash() == event.getDispatchedFromAccountHash())
            .thenAccept((sameAccount) -> {
                if (sameAccount) {
                    return;
                }

                // Transform the event to a message and send it
                CompletableFuture<String> messageFuture = chatMessageTransformer.apply(event, member);
                withErrorLogging(messageFuture, "Failed to transform event to chat message")
                    .thenAccept((message) ->
                        Optional.ofNullable(message).ifPresent(buChatService::sendMessage));
            });
    }

    private ChatMessageBuilder getChatMessagePlayerNameBuilder(Member member) {
        ChatMessageBuilder builder = new ChatMessageBuilder();
        builder.append(config.chatPlayerNameColor(), member.getName());
        return builder;
    }

    private CompletableFuture<String> transformSkillLevelUpAchievementEvent(BUEvent event, Member member) {
        SkillLevelUpAchievementBUEvent e = (SkillLevelUpAchievementBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);

        int level = e.getLevel();
        if (level == 99) {
            builder.append(" has reached the highest possible ");
            builder.append(e.getSkill());
            builder.append(" level of 99.");
            return CompletableFuture.completedFuture(builder.build());
        }

        builder.append(" has reached ");
        builder.append(e.getSkill());
        builder.append(" level ");
        builder.append(String.valueOf(level));
        builder.append(".");
        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformTotalLevelAchievementEvent(BUEvent event, Member member) {
        TotalLevelAchievementBUEvent e = (TotalLevelAchievementBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);
        builder.append(" has reached a total level of ");
        builder.append(String.valueOf(e.getTotalLevel()));
        builder.append(".");

        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformCombatLevelUpAchievementEvent(BUEvent event, Member member) {
        CombatLevelUpAchievementBUEvent e = (CombatLevelUpAchievementBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);

        int level = e.getLevel();
        if (level == 126) {
            builder.append(" has reached the highest possible combat level of 126.");
            return CompletableFuture.completedFuture(builder.build());
        }

        builder.append(" has reached combat level " + level + ".");
        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformCombatTaskAchievementEvent(BUEvent event, Member member) {
        CombatTaskAchievementBUEvent e = (CombatTaskAchievementBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);
        builder.append(" has completed a " + e.getTier() + " combat task: ");
        builder.append(config.chatCombatTaskColor(), e.getName());

        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformQuestCompletionAchievementEvent(BUEvent event, Member member) {
        QuestCompletionAchievementBUEvent e = (QuestCompletionAchievementBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);
        builder.append(" has completed a quest: ");
        builder.append(config.chatQuestNameColor(), e.getName());

        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformDiaryCompletionAchievementEvent(BUEvent event, Member member) {
        DiaryCompletionAchievementBUEvent e = (DiaryCompletionAchievementBUEvent) event;

        String tierText;
        switch (e.getTier()) {
            case Easy:
                tierText = "Easy";
                break;
            case Medium:
                tierText = "Medium";
                break;
            case Hard:
                tierText = "Hard";
                break;
            case Elite:
                tierText = "Elite";
                break;
            default:
                throw new IllegalStateException("Unexpected tier value: " + e.getTier());
        }

        String areaText;
        switch (e.getArea()) {
            case Ardougne:
                areaText = "Ardougne";
                break;
            case Desert:
                areaText = "Desert";
                break;
            case Falador:
                areaText = "Falador";
                break;
            case Kandarin:
                areaText = "Kandarin";
                break;
            case Karamja:
                areaText = "Karamja";
                break;
            case Kourend:
                areaText = "Kourend & Kebos";
                break;
            case Lumbridge:
                areaText = "Lumbridge & Draynor";
                break;
            case Morytania:
                areaText = "Morytania";
                break;
            case Varrock:
                areaText = "Varrock";
                break;
            case Western:
                areaText = "Western Provinces";
                break;
            case Wilderness:
                areaText = "Wilderness";
                break;
            case Fremennik:
                areaText = "Fremennik Province";
                break;
            default:
                throw new IllegalStateException("Unexpected area value: " + e.getArea());
        }

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);
        builder.append(" has completed the " +  tierText + " tier of the ");
        builder.append(config.chatHighlightColor(), areaText);
        builder.append(" diary.");

        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformCollectionLogAchievementEvent(BUEvent event, Member member) {
        CollectionLogUnlockAchievementBUEvent e = (CollectionLogUnlockAchievementBUEvent) event;

        ChatMessageBuilder builder = new ChatMessageBuilder();
        builder.append("New item added to ");
        builder.append(config.chatPlayerNameColor(), member.getName());
        builder.append("'s collection log: ");
        builder.append(config.chatHighlightColor(), e.getItemName());

        return CompletableFuture.completedFuture(builder.build());
    }

    private CompletableFuture<String> transformValuableLootEvent(BUEvent event, Member member) {
        ValuableLootBUEvent e = (ValuableLootBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);
        builder.append(" has received a drop: ");
        if (e.getQuantity() > 1) {
            builder.append(config.chatHighlightColor(), String.format("%d", e.getQuantity()));
            builder.append(" x ");
        }

        CompletableFuture<String> iconFuture = buChatService.getItemIconTagIfEnabled(e.getItemId());
        return withErrorLogging(iconFuture, "Failed to get item icon tag")
            .thenAccept((itemIconTag) -> {
                if (itemIconTag != null) {
                    builder.append(config.chatHighlightColor(), itemIconTag + " ");
                }
            })
            // Get the item definition on the client thread
            .thenCompose(asyncUtils.onClientThread(() -> client.getItemDefinition(e.getItemId())))
            .thenAccept((itemComposition) -> {
                builder.append(config.chatItemNameColor(), itemComposition.getName());

                long totalCoins = e.getPricePerItem() * e.getQuantity();
                String formattedCoins = String.format("%,d", totalCoins);
                builder.append(" (" + formattedCoins + " coins) from ");
            })
            // Get the NPC definition on the client thread
            .thenCompose(asyncUtils.onClientThread(() -> client.getNpcDefinition(e.getNpcId())))
            .thenApply((npcComposition) -> {
                builder.append(config.chatNPCNameColor(), npcComposition.getName());
                builder.append(".");

                return builder.build();
            });
    }

    private CompletableFuture<String> transformPetDropEvent(BUEvent event, Member member) {
        PetDropBUEvent e = (PetDropBUEvent) event;

        ChatMessageBuilder builder = getChatMessagePlayerNameBuilder(member);

        String followedText = e.isDuplicate()
            ? " has a funny feeling like they would have been followed: "
            : " has a funny feeling like they are being followed: ";
        builder.append(followedText);

        Integer petItemId = e.getPetItemId();
        if (petItemId == null) {
            builder.append(config.chatHighlightColor(), "Unknown");
            return CompletableFuture.completedFuture(builder.build());
        }

        CompletableFuture<String> iconFuture = buChatService.getItemIconTagIfEnabled(petItemId);
        return withErrorLogging(iconFuture, "Failed to get pet icon tag")
            .thenAccept((itemIconTag) -> {
                if (itemIconTag != null) {
                    builder.append(config.chatHighlightColor(), itemIconTag + " ");
                }
            })
            .thenCompose(asyncUtils.onClientThread(() -> client.getItemDefinition(petItemId).getName()))
            .thenApply((petName) -> {
                builder.append(config.chatHighlightColor(), petName);
                return builder.build();
            });
    }
}

package com.elertan.chat;

import com.elertan.MemberService;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.EnumMap;
import java.util.Map;
import java.util.function.Supplier;

/**
 * Composes chat messages based on game state. Designed for both error and future non-error
 * messages.
 */
@Singleton
public final class ChatMessageProvider {

    private final MemberService memberService;
    private final Map<MessageKey, Supplier<String>> resolvers;

    @Inject
    public ChatMessageProvider(final MemberService memberService) {
        this.memberService = memberService;
        this.resolvers = new EnumMap<>(MessageKey.class);
        this.resolvers.put(
            MessageKey.STILL_LOADING_TEMPORARY_STRICT_GAME_RULES_ENFORCEMENT,
            this::stillLoadingTemporaryStrictGameRulesEnforcement
        );
        this.resolvers.put(
            MessageKey.STILL_LOADING_PLEASE_WAIT,
            this::stillLoadingPleaseWaitError
        );
        this.resolvers.put(MessageKey.TRADE_RESTRICTION, this::tradeRestrictionMessage);
        this.resolvers.put(
            MessageKey.GROUND_ITEM_TAKE_RESTRICTION,
            this::groundItemTakeRestrictionMessage
        );
        this.resolvers.put(
            MessageKey.GROUND_ITEM_CAST_RESTRICTION,
            this::groundItemCastRestrictionMessage
        );
        this.resolvers.put(
            MessageKey.POH_ENTER_RESTRICTION,
            this::pohEnterRestrictionMessage
        );
        this.resolvers.put(
            MessageKey.PLAYER_VERSUS_PLAYER_LOOT_RESTRICTION,
            this::playerVersusPlayerLootRestrictionMessage
        );
        this.resolvers.put(
            MessageKey.PLAYER_VERSUS_PLAYER_LOOT_KEY_RESTRICTION,
            this::playerVersusPlayerLootKeyRestrictionMessage
        );
        this.resolvers.put(
            MessageKey.ITEM_UNLOCKS_UNSUPPORTED_WORLD,
            this::itemUnlocksUnsupportedWorldMessage
        );
        this.resolvers.put(
            MessageKey.FALADOR_PARTY_ROOM_BALLOON_RESTRICTION,
            this::faladorPartyRoomBalloonRestrictionMessage
        );
    }

    /**
     * Returns a message for the given key. Never returns null.
     */
    public String messageFor(final MessageKey key) {
        final Supplier<String> supplier = resolvers.get(key);
        if (supplier == null) {
            throw new IllegalArgumentException("Unknown message key: " + key);
        }
        return supplier.get();
    }

    private boolean isSolo() {
        try {
            return memberService.isPlayingAlone();
        } catch (Exception ignored) {
            // Fail safe to solo semantics if the service is unavailable.
            return true;
        }
    }

    private String getIdentity(boolean isSolo) {
        if (isSolo) {
            return "Bronzeman";
        } else {
            return "Group Bronzeman";
        }
    }

    private String stillLoadingTemporaryStrictGameRulesEnforcement() {
        return "Bronzeman Unleashed is still loading. Temporarily enforcing strict game rules to ensure integrity.";
    }

    private String stillLoadingPleaseWaitError() {
        return "Bronzeman Unleashed is still loading. Please wait a moment before interacting to ensure integrity.";
    }

    private String tradeRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You are a %s with trade restrictions.%s",
            identity,
            isSolo ? " You stand alone." : " You can only trade members of your group."
        );
    }

    private String groundItemTakeRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot take this item due to %s ground item restrictions.%s",
            identity,
            isSolo ? "" : " Only items of your group may be taken."
        );
    }

    private String groundItemCastRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot cast on this ground item due to %s restrictions.%s",
            identity,
            isSolo ? "" : " Only items of your group may be casted on."
        );
    }

    private String pohEnterRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot enter this Player Owned House due to %s restrictions.%s",
            identity,
            isSolo ? "" : " You may only enter one owned by your group."
        );
    }

    private String playerVersusPlayerLootRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot loot this player due to %s restrictions.%s",
            identity,
            isSolo ? "" : " You may only loot players of your group."
        );
    }

    private String playerVersusPlayerLootKeyRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot take or bank any items from loot keys due to %s restrictions.",
            identity
        );
    }

    private String itemUnlocksUnsupportedWorldMessage() {
        return "Item unlocks are disabled on this world type. Seasonal or special mode worlds do not support adding new unlocked items.";
    }

    private String faladorPartyRoomBalloonRestrictionMessage() {
        boolean isSolo = isSolo();
        String identity = getIdentity(isSolo);
        return String.format(
            "You cannot burst the Falador Party Room balloons due to %s restrictions.",
            identity
        );
    }

    /**
     * Keys for message lookups. Extend with non-error keys later without changing call sites.
     */
    public enum MessageKey {
        STILL_LOADING_TEMPORARY_STRICT_GAME_RULES_ENFORCEMENT,
        STILL_LOADING_PLEASE_WAIT,
        TRADE_RESTRICTION,
        GROUND_ITEM_TAKE_RESTRICTION,
        POH_ENTER_RESTRICTION,
        GROUND_ITEM_CAST_RESTRICTION,
        PLAYER_VERSUS_PLAYER_LOOT_RESTRICTION,
        PLAYER_VERSUS_PLAYER_LOOT_KEY_RESTRICTION,
        ITEM_UNLOCKS_UNSUPPORTED_WORLD,
        FALADOR_PARTY_ROOM_BALLOON_RESTRICTION,
    }
}

