package com.elertan.panel.screens.main;

import com.elertan.panel.ViewportWidthTrackingPanel;
import com.elertan.panel.components.GameRulesEditor;
import com.elertan.panel.components.GameRulesEditorViewModel;
import com.elertan.ui.Bindings;
import com.elertan.ui.Property;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.util.Arrays;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;

public class ConfigScreen extends JPanel implements AutoCloseable {

    private final AutoCloseable backButtonEnabledBinding;
    private final AutoCloseable updateGameRulesButtonEnabledBinding;
    private final AutoCloseable leaveButtonEnabledBinding;
    private final AutoCloseable errorMessageLabelVisibleBinding;
    private final AutoCloseable errorMessageLabelTextBinding;
    private final GameRulesEditor gameRulesEditor;

    private ConfigScreen(ConfigScreenViewModel viewModel,
        GameRulesEditorViewModel gameRulesEditorViewModel,
        GameRulesEditor.Factory gameRulesEditorFactory) {
        this.gameRulesEditor = gameRulesEditorFactory.create(gameRulesEditorViewModel);
        setLayout(new GridBagLayout());
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

        GridBagConstraints gbc = new GridBagConstraints();
        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.anchor = GridBagConstraints.NORTH;
        gbc.gridx = 0;
        gbc.gridy = 0;

        gbc.weighty = 0.0;
        JButton backButton = new JButton("Back");
        backButton.setBorder(BorderFactory.createEmptyBorder(10, 0, 10, 0));
        backButton.addActionListener(e -> viewModel.onBackButtonClick());
        backButtonEnabledBinding = Bindings.bindEnabled(
            backButton,
            viewModel.isSubmittingProperty.derive(b -> !b)
        );
        add(backButton, gbc);
        gbc.gridy++;

        add(Box.createVerticalStrut(10), gbc);
        gbc.gridy++;

        JLabel titleLabel = new JLabel("Game Rules");
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 15f));
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        add(titleLabel, gbc);
        gbc.gridy++;

        add(Box.createVerticalStrut(10), gbc);
        gbc.gridy++;

        gbc.weightx = 1.0;
        gbc.weighty = 1.0;
        gbc.fill = GridBagConstraints.BOTH;

        ViewportWidthTrackingPanel viewportWrapper = new ViewportWidthTrackingPanel(new BorderLayout());
        viewportWrapper.add(gameRulesEditor, BorderLayout.NORTH);

        JScrollPane scrollPane = new JScrollPane(viewportWrapper);
        scrollPane.setBorder(null);
        scrollPane.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        // Dynamically add right padding only when vertical scrollbar is visible
        scrollPane.getVerticalScrollBar().addAdjustmentListener(e -> {
            boolean visible = scrollPane.getVerticalScrollBar().isVisible();
            if (visible) {
                viewportWrapper.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 10));
            } else {
                viewportWrapper.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 0));
            }
            viewportWrapper.revalidate();
        });

        add(scrollPane, gbc);

        gbc.fill = GridBagConstraints.HORIZONTAL;
        gbc.weighty = 0.0;
        gbc.gridy++;

        add(Box.createVerticalStrut(5), gbc);
        gbc.gridy++;

        JLabel errorMessageLabel = new JLabel();
        errorMessageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        errorMessageLabelVisibleBinding = Bindings.bindVisible(
            errorMessageLabel,
            viewModel.errorMessageProperty.derive(errorMessage -> errorMessage != null
                && !errorMessage.isEmpty())
        );
        errorMessageLabelTextBinding = Bindings.bindLabelText(
            errorMessageLabel, viewModel.errorMessageProperty.derive(errorMessage -> {
                if (errorMessage == null || errorMessage.isEmpty()) {
                    return "";
                }

                String sb = "<html><div style=\"text-align:center;color:red;\">" +
                    errorMessage +
                    "</div></html>";

                return sb;
            })
        );
        add(errorMessageLabel, gbc);
        gbc.gridy++;

        add(Box.createVerticalStrut(5), gbc);
        gbc.gridy++;

        JButton updateGameRulesButton = new JButton("Update Game Rules");
        updateGameRulesButton.setBorder(BorderFactory.createEmptyBorder(15, 0, 15, 0));
        updateGameRulesButton.addActionListener(e -> viewModel.updateGameRulesClick());
        updateGameRulesButtonEnabledBinding = Bindings.bindEnabled(
            updateGameRulesButton,
            Property.deriveMany(
                Arrays.asList(
                    viewModel.gameRulesEditorViewModelPropsProperty,
                    viewModel.isSubmittingProperty
                ),
                (values) -> {
                    GameRulesEditorViewModel.Props props = viewModel.gameRulesEditorViewModelPropsProperty.get();
                    Boolean isSubmitting = viewModel.isSubmittingProperty.get();

                    if (props == null || isSubmitting == null) {
                        return false;
                    }

                    return !props.isViewOnlyMode() && !isSubmitting;
                }
            )
        );
        add(updateGameRulesButton, gbc);
        gbc.gridy++;

        add(Box.createVerticalStrut(15), gbc);
        gbc.gridy++;

        JButton leaveButton = new JButton("Leave Bronzeman");
        leaveButton.setBackground(new Color(183, 48, 48));
        leaveButton.setBorder(BorderFactory.createEmptyBorder(5, 0, 5, 0));
        leaveButton.addActionListener(e -> viewModel.leaveButtonClick());
        leaveButtonEnabledBinding = Bindings.bindEnabled(
            leaveButton,
            viewModel.isSubmittingProperty.derive(b -> !b)
        );
        add(leaveButton, gbc);
        gbc.gridy++;
    }

    @Override
    public void close() throws Exception {
        gameRulesEditor.close();
        leaveButtonEnabledBinding.close();
        errorMessageLabelVisibleBinding.close();
        errorMessageLabelTextBinding.close();
        updateGameRulesButtonEnabledBinding.close();
        backButtonEnabledBinding.close();
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        ConfigScreen create(ConfigScreenViewModel viewModel);
    }

    @Singleton
    private static final class FactoryImpl implements Factory {

        @Inject
        private GameRulesEditor.Factory gameRulesEditorFactory;
        @Inject
        private GameRulesEditorViewModel.Factory gameRulesEditorViewModelFactory;

        @Override
        public ConfigScreen create(ConfigScreenViewModel viewModel) {
            GameRulesEditorViewModel gameRulesEditorViewModel = gameRulesEditorViewModelFactory.create(
                viewModel.gameRulesEditorViewModelPropsProperty.get());

            // Add listener FIRST to catch any async updates
            viewModel.gameRulesEditorViewModelPropsProperty.addListener((event) -> {
                GameRulesEditorViewModel.Props newProps = viewModel.gameRulesEditorViewModelPropsProperty.get();
                gameRulesEditorViewModel.setProps(newProps);
            });

            // Then explicitly set current value (in case async already completed)
            gameRulesEditorViewModel.setProps(viewModel.gameRulesEditorViewModelPropsProperty.get());

            return new ConfigScreen(viewModel, gameRulesEditorViewModel, gameRulesEditorFactory);
        }
    }
}

package com.elertan.panel.screens.main;

import com.elertan.AccountConfigurationService;
import com.elertan.GameRulesService;
import com.elertan.MemberService;
import com.elertan.data.GameRulesDataProvider;
import com.elertan.data.MembersDataProvider;
import com.elertan.models.AccountConfiguration;
import com.elertan.models.GameRules;
import com.elertan.models.Member;
import com.elertan.models.MemberRole;
import com.elertan.models.AccountConfiguration.StorageMode;
import com.elertan.panel.components.GameRulesEditorViewModel;
import com.elertan.ui.Property;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.concurrent.CompletableFuture;
import java.util.function.Supplier;
import javax.swing.JOptionPane;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;

@Slf4j
public class ConfigScreenViewModel implements AutoCloseable {

    public final Property<GameRulesEditorViewModel.Props> gameRulesEditorViewModelPropsProperty;
    public final Property<Boolean> isSubmittingProperty = new Property<>(false);
    public final Property<String> errorMessageProperty = new Property<>(null);

    private final AccountConfigurationService accountConfigurationService;
    private final MemberService memberService;
    private final GameRulesDataProvider gameRulesDataProvider;
    private final MembersDataProvider membersDataProvider;
    private final Runnable navigateToMainScreen;
    private final MembersDataProvider.MemberMapListener memberMapListener;

    private GameRules gameRules;
    private Supplier<GameRulesEditorViewModel.Props> propsSupplier;
    private volatile boolean closed;

    private ConfigScreenViewModel(Client client,
        AccountConfigurationService accountConfigurationService, GameRulesService gameRulesService,
        GameRulesDataProvider gameRulesDataProvider, MembersDataProvider membersDataProvider,
        MemberService memberService,
        Runnable navigateToMainScreen) {
        this.accountConfigurationService = accountConfigurationService;
        this.memberService = memberService;
        this.gameRulesDataProvider = gameRulesDataProvider;
        this.membersDataProvider = membersDataProvider;
        this.navigateToMainScreen = navigateToMainScreen;
        propsSupplier = () -> {
            GameRules gameRules = gameRulesService.getGameRules().get();
            Member member = null;
            try {
                member = memberService.getMyMember();
            } catch (Exception ignored) {
            }
            boolean isViewOnlyMode = member == null || member.getRole() != MemberRole.Owner;
            boolean isLocalMode = false;
            AccountConfiguration accountConfiguration =
                accountConfigurationService.currentAccountConfiguration().get();
            if (accountConfiguration != null) {
                isLocalMode = accountConfiguration.getStorageMode() == StorageMode.LOCAL;
            }

            return new GameRulesEditorViewModel.Props(
                client.getAccountHash(),
                gameRules,
                (newGameRules) -> setGameRules(newGameRules),
                isViewOnlyMode,
                isLocalMode
            );
        };

        gameRulesEditorViewModelPropsProperty = new Property<>(propsSupplier.get());
        memberMapListener = new MembersDataProvider.MemberMapListener() {
            @Override
            public void onUpdate(Member newMember, Member oldMember) {
                refreshGameRulesEditorProps();
            }

            @Override
            public void onDelete(Member member) {
                refreshGameRulesEditorProps();
            }
        };
        membersDataProvider.addMemberMapListener(memberMapListener);
        membersDataProvider.await(null)
            .whenComplete((__, throwable) -> {
                if (throwable != null) {
                    log.error("error waiting for members data to be ready", throwable);
                    return;
                }
                refreshGameRulesEditorProps();
            });

        gameRulesService.waitUntilGameRulesReady(null)
            .whenComplete((__, throwable) -> {
                if (throwable != null) {
                    log.error("error waiting for game rules to be ready", throwable);
                    return;
                }
                setGameRules(gameRulesService.getGameRules().get());
                refreshGameRulesEditorProps();
            });
    }

    @Override
    public void close() {
        closed = true;
        membersDataProvider.removeMemberMapListener(memberMapListener);
    }

    public void onBackButtonClick() {
        // Reset game rules to the last saved game rules.
        gameRulesEditorViewModelPropsProperty.set(propsSupplier.get());

        navigateToMainScreen.run();
    }

    public void updateGameRulesClick() {
        int result = JOptionPane.showConfirmDialog(
            null,
            "Are you sure you want to update the game rules?",
            "Confirm update game rules",
            JOptionPane.OK_CANCEL_OPTION,
            JOptionPane.WARNING_MESSAGE
        );
        if (result != JOptionPane.OK_OPTION) {
            return;
        }

        isSubmittingProperty.set(true);

        gameRulesDataProvider.updateGameRules(gameRules)
            .whenComplete((__, throwable) -> {
                try {
                    if (throwable != null) {
                        log.error(
                            "An error occurred while trying to save the game rules.",
                            throwable
                        );
                        errorMessageProperty.set(
                            "An error occurred while trying to save the game rules.");
                        return;
                    }

                    errorMessageProperty.set(null);
                    navigateToMainScreen.run();
                } finally {
                    isSubmittingProperty.set(false);
                }
            });
    }

    private void setGameRules(GameRules gameRules) {
        this.gameRules = gameRules;
        log.debug("config screen set game rules: {}", gameRules);
    }

    private void refreshGameRulesEditorProps() {
        if (closed) {
            return;
        }
        gameRulesEditorViewModelPropsProperty.set(propsSupplier.get());
    }

    public void leaveButtonClick() {
        boolean isPlayingAlone = memberService.isPlayingAlone();
        Member member = memberService.getMyMember();
        int result = JOptionPane.showConfirmDialog(
            null,
            buildLeaveConfirmationMessage(isPlayingAlone, member),
            "Leave Bronzeman for this account?",
            JOptionPane.OK_CANCEL_OPTION,
            JOptionPane.WARNING_MESSAGE
        );
        if (result != JOptionPane.OK_OPTION) {
            return;
        }

        isSubmittingProperty.set(true);

        CompletableFuture<Void> future = new CompletableFuture<>();

        if (!isPlayingAlone) {
            memberService.leaveGroupAndPromoteOldestMember().whenComplete((__, throwable) -> {
                if (throwable != null) {
                    future.completeExceptionally(throwable);
                    return;
                }
                future.complete(null);
            });
        } else {
            future.complete(null);
        }

        future.whenComplete((__, throwable) -> {
            if (throwable != null) {
                log.error("error leaving group", throwable);
                errorMessageProperty.set("An error occurred while trying to leave the group.");
                return;
            }
            errorMessageProperty.set(null);

            navigateToMainScreen.run();
            accountConfigurationService.setCurrentAccountConfiguration(null);
            isSubmittingProperty.set(false);
        });

    }

    private String buildLeaveConfirmationMessage(boolean isPlayingAlone, Member member) {
        StringBuilder messageBuilder = new StringBuilder();
        messageBuilder.append("This will turn off Bronzeman for this account.\n");

        if (!isPlayingAlone) {
            messageBuilder.append("You will also be removed from the group.\n");
            if (member != null && member.getRole() == MemberRole.Owner) {
                messageBuilder.append(
                    "Group ownership will be passed to the member who has been in the group the longest.\n"
                );
            }
        }

        StorageMode storageMode = null;
        AccountConfiguration accountConfiguration =
            accountConfigurationService.currentAccountConfiguration().get();
        if (accountConfiguration != null) {
            storageMode = accountConfiguration.getStorageMode();
        }

        if (storageMode == StorageMode.LOCAL) {
            messageBuilder.append("Your local progress will stay saved on this computer.\n");
        } else {
            messageBuilder.append("Your saved progress will not be deleted.\n");
        }

        messageBuilder.append("You can set Bronzeman up again later from this panel.");
        return messageBuilder.toString();
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        ConfigScreenViewModel create(Runnable navigateToMainScreen);
    }

    @Singleton
    private static final class FactoryImpl implements Factory {

        @Inject
        private Client client;
        @Inject
        private AccountConfigurationService accountConfigurationService;
        @Inject
        private GameRulesService gameRulesService;
        @Inject
        private GameRulesDataProvider gameRulesDataProvider;
        @Inject
        private MembersDataProvider membersDataProvider;
        @Inject
        private MemberService memberService;

        @Override
        public ConfigScreenViewModel create(Runnable navigateToMainScreen) {
            return new ConfigScreenViewModel(
                client,
                accountConfigurationService,
                gameRulesService,
                gameRulesDataProvider,
                membersDataProvider,
                memberService,
                navigateToMainScreen
            );
        }
    }
}

