import java.awt.Dimension;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.IconTextField;

@Slf4j
public class HeaderView extends JPanel implements AutoCloseable {

    private final AutoCloseable searchFieldBinding;
    private final AutoCloseable sortedByComboBoxBinding;
    private final AutoCloseable unlockedByComboBoxBinding;
    private final AutoCloseable unlockedByRowVisibleBinding;

    private HeaderView(HeaderViewViewModel viewModel, BUResourceService buResourceService) {
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 0, 3));

        IconTextField searchField = new IconTextField();
        searchField.setIcon(IconTextField.Icon.SEARCH);
        searchField.setPreferredSize(new Dimension(BUPanel.PANEL_WIDTH - 20, 30));
        searchField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        searchField.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
        searchField.setMinimumSize(new Dimension(0, 30));
        searchFieldBinding = Bindings.bindIconTextFieldText(searchField, viewModel.searchText);

        JButton configButton = new JButton();
        configButton.setIcon(new ImageIcon(buResourceService.getConfigureIconBufferedImage()));
        configButton.setToolTipText("Open configuration");
        configButton.setPreferredSize(new Dimension(30, 30));
        configButton.setFocusable(false);
        configButton.setBorderPainted(false);
        configButton.setContentAreaFilled(true);
        configButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        configButton.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                configButton.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e) {
                configButton.setBackground(ColorScheme.DARKER_GRAY_COLOR);
            }
        });
        configButton.addActionListener(e -> viewModel.onOpenConfigurationClick());

        JPanel searchbarHeader = new JPanel(new BorderLayout(5, 0));
        searchbarHeader.add(searchField, BorderLayout.CENTER);
        searchbarHeader.add(configButton, BorderLayout.EAST);

        add(searchbarHeader);

        add(Box.createVerticalStrut(8));

        JPanel filterAndSortPanel = new JPanel();
        filterAndSortPanel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 7));
        filterAndSortPanel.setLayout(new BoxLayout(filterAndSortPanel, BoxLayout.Y_AXIS));

        JPanel sortedByRow = new JPanel(new BorderLayout(5, 0));
        JLabel sortedByLabel = new JLabel("Sorted by:");
        sortedByLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 5));
        JComboBox<UnlockedItemsScreenViewModel.SortedBy> sortedByComboBox = new JComboBox<>();

        Map<UnlockedItemsScreenViewModel.SortedBy, String> sortedByEnumToStringMap = ImmutableMap.<UnlockedItemsScreenViewModel.SortedBy, String>builder()
            .put(
                UnlockedItemsScreenViewModel.SortedBy.UNLOCKED_AT_ASC,
                "Unlocked at (asc)"
            )
            .put(
                UnlockedItemsScreenViewModel.SortedBy.ALPHABETICAL_ASC,
                "Alphabetical (asc)"
            )
            .put(
                UnlockedItemsScreenViewModel.SortedBy.PLAYER_ASC,
                "Player (asc)"
            )
            .put(
                UnlockedItemsScreenViewModel.SortedBy.UNLOCKED_AT_DESC,
                "Unlocked at (desc)"
            )
            .put(
                UnlockedItemsScreenViewModel.SortedBy.ALPHABETICAL_DESC,
                "Alphabetical (desc)"
            )
            .put(
                UnlockedItemsScreenViewModel.SortedBy.PLAYER_DESC,
                "Player (desc)"
            )
            .build();
        sortedByComboBoxBinding = Bindings.bindComboBox(
            sortedByComboBox,
            viewModel.sortedByOptions,
            viewModel.sortedBy,
            new Property<>(sortedByEnumToStringMap)
        );

        sortedByRow.add(sortedByLabel, BorderLayout.WEST);
        sortedByRow.add(sortedByComboBox, BorderLayout.CENTER);

        filterAndSortPanel.add(sortedByRow);

        filterAndSortPanel.add(Box.createVerticalStrut(5));

        JPanel unlockedByRow = new JPanel(new BorderLayout(5, 0));
        JLabel unlockedByLabel = new JLabel("Unlocked by:");
        unlockedByLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 0, 5));
        JComboBox<Long> unlockedByComboBox = new JComboBox<>();

        Property<List<Long>> unlockedByOptions = viewModel
            .accountHashesFromAllUnlockedItems
            .derive((list) -> {
                List<Long> result = new ArrayList<>(list.size() + 1);
                // The "Everyone" option
                result.add(null);
                result.addAll(list);
                return result;
            });

        Property<Map<Long, String>> unlockedByValueToStringMapProperty = viewModel
            .accountHashToMemberNameMap
            .derive((map) -> {
                Map<Long, String> result = new HashMap<>(map);
                result.put(null, "Everyone");
                return result;
            });

        unlockedByComboBoxBinding = Bindings.bindComboBox(
            unlockedByComboBox,
            unlockedByOptions,
            viewModel.unlockedByAccountHash,
            unlockedByValueToStringMapProperty
        );
        unlockedByRowVisibleBinding = Bindings.bindVisible(
            unlockedByRow,
            viewModel.showUnlockedByFilter
        );

        unlockedByRow.add(unlockedByLabel, BorderLayout.WEST);
        unlockedByRow.add(unlockedByComboBox, BorderLayout.CENTER);

        filterAndSortPanel.add(unlockedByRow);

        add(filterAndSortPanel);
    }

    @Override
    public void close() throws Exception {
        unlockedByRowVisibleBinding.close();
        unlockedByComboBoxBinding.close();
        sortedByComboBoxBinding.close();
        searchFieldBinding.close();
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        HeaderView create(HeaderViewViewModel viewModel);
    }

    private static final class FactoryImpl implements Factory {

        @Inject
        private BUResourceService buResourceService;

        @Override
        public HeaderView create(HeaderViewViewModel viewModel) {
            return new HeaderView(viewModel, buResourceService);
        }
    }

}

package com.elertan.panel.screens.main.unlockedItems.items;

import com.elertan.AccountConfigurationService;
import com.elertan.models.AccountConfiguration;
import com.elertan.models.AccountConfiguration.StorageMode;
import com.elertan.data.MembersDataProvider;
import com.elertan.models.Member;
import com.elertan.models.UnlockedItem;
import com.elertan.panel.screens.main.UnlockedItemsScreenViewModel;
import com.elertan.panel.screens.main.UnlockedItemsScreenViewModel.SortedBy;
import com.elertan.ui.Property;
import com.elertan.utils.Subscription;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class HeaderViewViewModel implements AutoCloseable {

    public final Property<String> searchText;
    public final Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy;
    public final Property<Long> unlockedByAccountHash;
    public final Property<List<UnlockedItemsScreenViewModel.SortedBy>> sortedByOptions;
    public final Property<Boolean> showUnlockedByFilter;
    public final Property<List<Long>> accountHashesFromAllUnlockedItems;
    public final Property<Map<Long, String>> accountHashToMemberNameMap;
    private final Runnable navigateToConfiguration;
    private final MembersDataProvider membersDataProvider;
    private final MembersDataProvider.MemberMapListener memberMapListener;
    private final Subscription accountConfigurationSubscription;

    private HeaderViewViewModel(
        Property<List<UnlockedItem>> allUnlockedItems,
        Property<String> searchText,
        Property<SortedBy> sortedBy,
        Property<Long> unlockedByAccountHash,
        AccountConfigurationService accountConfigurationService,
        MembersDataProvider membersDataProvider,
        Runnable navigateToConfiguration) {
        this.membersDataProvider = membersDataProvider;

        this.searchText = searchText;
        this.sortedBy = sortedBy;
        this.unlockedByAccountHash = unlockedByAccountHash;
        this.sortedByOptions = new Property<>(buildSortedByOptions(false));
        this.showUnlockedByFilter = new Property<>(true);

        accountHashesFromAllUnlockedItems = allUnlockedItems.deriveAsync(items -> {
            if (items == null || items.isEmpty()) {
                return new ArrayList<>();
            }

            return items.stream()
                .map(UnlockedItem::getAcquiredByAccountHash)
                .distinct()
                .collect(Collectors.toList());
        });
        this.navigateToConfiguration = navigateToConfiguration;

        accountHashToMemberNameMap = new Property<>(buildAccountHashToMemberNameMap());

        memberMapListener = new MembersDataProvider.MemberMapListener() {
            @Override
            public void onUpdate(Member newMember, Member oldMember) {
                accountHashToMemberNameMap.set(buildAccountHashToMemberNameMap());
            }

            @Override
            public void onDelete(Member member) {
                accountHashToMemberNameMap.set(buildAccountHashToMemberNameMap());
            }
        };
        membersDataProvider.addMemberMapListener(memberMapListener);

        membersDataProvider.await(null).whenComplete((__, throwable) -> {
            if (throwable != null) {
                return;
            }
            accountHashToMemberNameMap.set(buildAccountHashToMemberNameMap());
        });

        accountConfigurationSubscription = accountConfigurationService.currentAccountConfiguration()
            .subscribeImmediate((accountConfiguration, __) ->
                onAccountConfigurationChanged(accountConfiguration)
            );
    }

    @Override
    public void close() throws Exception {
        accountConfigurationSubscription.dispose();
        membersDataProvider.removeMemberMapListener(memberMapListener);
    }

    public void onOpenConfigurationClick() {
        navigateToConfiguration.run();
    }

    private Map<Long, String> buildAccountHashToMemberNameMap() {
        Map<Long, Member> membersMap = membersDataProvider.getMembersMap();
        if (membersMap == null) {
            return Collections.emptyMap();
        }

        Map<Long, String> accountHashToMemberNameMap = new HashMap<>();
        for (Member member : membersMap.values()) {
            accountHashToMemberNameMap.put(member.getAccountHash(), member.getName());
        }
        return accountHashToMemberNameMap;
    }

    private void onAccountConfigurationChanged(AccountConfiguration accountConfiguration) {
        boolean isLocalMode = accountConfiguration != null
            && accountConfiguration.getStorageMode() == StorageMode.LOCAL;
        sortedByOptions.set(buildSortedByOptions(isLocalMode));
        showUnlockedByFilter.set(!isLocalMode);

        if (isLocalMode) {
            // Normalize hidden multiplayer-only state when switching into local mode.
            SortedBy sortedByValue = sortedBy.get();
            if (sortedByValue == SortedBy.PLAYER_ASC || sortedByValue == SortedBy.PLAYER_DESC) {
                sortedBy.set(SortedBy.UNLOCKED_AT_DESC);
            }
            unlockedByAccountHash.set(null);
        }
    }

    private List<SortedBy> buildSortedByOptions(boolean isLocalMode) {
        List<SortedBy> options = new ArrayList<>();
        options.add(SortedBy.UNLOCKED_AT_ASC);
        options.add(SortedBy.ALPHABETICAL_ASC);
        if (!isLocalMode) {
            options.add(SortedBy.PLAYER_ASC);
        }
        options.add(SortedBy.UNLOCKED_AT_DESC);
        options.add(SortedBy.ALPHABETICAL_DESC);
        if (!isLocalMode) {
            options.add(SortedBy.PLAYER_DESC);
        }
        return options;
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        HeaderViewViewModel create(
            Property<List<UnlockedItem>> allUnlockedItems,
            Property<String> searchText,
            Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy,
            Property<Long> unlockedByAccountHash,
            Runnable navigateToConfiguration
        );
    }

    @Singleton
    private static final class FactoryImpl implements Factory {

        @Inject
        private AccountConfigurationService accountConfigurationService;
        @Inject
        private MembersDataProvider membersDataProvider;

        @Override
        public HeaderViewViewModel create(
            Property<List<UnlockedItem>> allUnlockedItems,
            Property<String> searchText,
            Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy,
            Property<Long> unlockedByAccountHash,
            Runnable navigateToConfiguration
        ) {
            return new HeaderViewViewModel(
                allUnlockedItems,
                searchText,
                sortedBy,
                unlockedByAccountHash,
                accountConfigurationService,
                membersDataProvider,
                navigateToConfiguration
            );
        }
    }
}

package com.elertan.panel.screens.main.unlockedItems.items;

import com.elertan.BUResourceService;
import com.elertan.models.Member;
import com.elertan.models.UnlockedItem;
import com.elertan.ui.Bindings;
import com.elertan.utils.OffsetDateTimeUtils;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.GridBagLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.beans.PropertyChangeListener;
import java.time.OffsetDateTime;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JMenuItem;
import javax.swing.JPanel;
import javax.swing.JPopupMenu;
import javax.swing.JScrollPane;
import javax.swing.SwingConstants;
import javax.swing.Timer;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

@Slf4j
public class MainView extends JPanel implements AutoCloseable {

    private final MainViewViewModel viewModel;
    private final BUResourceService buResourceService;
    private final AutoCloseable cardLayoutBinding;
    private AutoCloseable listBinding;
    private Timer relativeTimeUpdateTimer;

    private MainView(MainViewViewModel viewModel, BUResourceService buResourceService) {
        this.viewModel = viewModel;
        this.buResourceService = buResourceService;

        CardLayout cardLayout = new CardLayout();
        setLayout(cardLayout);
        cardLayoutBinding = Bindings.bindCardLayout(
            this,
            cardLayout,
            viewModel.viewState,
            this::buildViewState
        );
    }

    @Override
    public void close() throws Exception {
        if (relativeTimeUpdateTimer != null && relativeTimeUpdateTimer.isRunning()) {
            relativeTimeUpdateTimer.stop();
        }
        if (listBinding != null) {
            listBinding.close();
        }
        cardLayoutBinding.close();
    }

    private JPanel buildViewState(MainViewViewModel.ViewState viewState) {
        switch (viewState) {
            case LOADING:
                return buildLoadingViewState();
            case EMPTY:
                return buildEmptyViewState();
            case READY:
                return buildReadyViewState();
        }

        throw new IllegalStateException("Unknown view state: " + viewState);
    }

    private JPanel buildLoadingViewState() {
        JPanel panel = new JPanel(new GridBagLayout());
        JLabel label = new JLabel();
        label.setIcon(buResourceService.getLoadingSpinnerImageIcon());
        label.setHorizontalAlignment(SwingConstants.CENTER);
        panel.add(label);
        return panel;
    }

    private JPanel buildEmptyViewState() {
        JPanel panel = new JPanel(new GridBagLayout());
        JLabel label = new JLabel("Nothing unlocked yet");
        label.setHorizontalAlignment(SwingConstants.CENTER);
        panel.add(label);
        return panel;
    }

    private JPanel buildReadyViewState() {
        JPanel panel = new JPanel(new BorderLayout());
        Set<Integer> iconRepaintHooks = new HashSet<>();

        JList<MainViewViewModel.ListItem> list = new JList<>();
        list.setBorder(BorderFactory.createEmptyBorder(5, 5, 5, 5));
        list.setBackground(ColorScheme.DARK_GRAY_COLOR);

        list.setLayoutOrientation(JList.HORIZONTAL_WRAP);
        list.setVisibleRowCount(-1);

        JPopupMenu contextMenu = new JPopupMenu();
        JMenuItem removeFromUnlockedItemsMenuItem = new JMenuItem("Remove from unlocked items");
        contextMenu.add(removeFromUnlockedItemsMenuItem);

        removeFromUnlockedItemsMenuItem.addActionListener(e -> {
            MainViewViewModel.ListItem selected = list.getSelectedValue();
            if (selected == null) {
                return;
            }

            viewModel.removeFromUnlockedItems(selected);
        });

        // Show the popup on right click and select the item under the cursor
        list.addMouseListener(new MouseAdapter() {
            private void maybeShowPopup(MouseEvent e) {
                if (e.isPopupTrigger()) {
                    int index = list.locationToIndex(e.getPoint());
                    if (index != -1) {
                        list.setSelectedIndex(index);
                        contextMenu.show(list, e.getX(), e.getY());
                    }
                }
            }

            @Override
            public void mousePressed(MouseEvent e) {
                maybeShowPopup(e);
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                maybeShowPopup(e);
            }
        });

        list.setCellRenderer((jl, listItem, index, isSelected, cellHasFocus) -> {
            JLabel label = new JLabel();
            label.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));
            label.setHorizontalAlignment(SwingConstants.CENTER);

            AsyncBufferedImage icon = listItem.getIcon();
            int itemId = listItem.getItem().getId();
            // The renderer is invoked repeatedly, so register at most one repaint hook per item id.
            if (iconRepaintHooks.add(itemId)) {
                icon.onLoaded(() -> Bindings.invokeOnEDT(list::repaint));
            }
            icon.addTo(label);

            UnlockedItem item = listItem.getItem();
            // rich tooltip
            String name = item.getName();
            Member acquiredByMember = listItem.getAcquiredByMember();
            String acquiredBy = acquiredByMember == null ? null : acquiredByMember.getName();

            String acquiredAt = null;
            if (item.getAcquiredAt() != null) {
                OffsetDateTime now = OffsetDateTime.now();
                acquiredAt = OffsetDateTimeUtils.formatRelativeTime(
                    now,
                    item.getAcquiredAt().getValue()
                );
            }

            StringBuilder tooltipBuilder = new StringBuilder();
            tooltipBuilder.append("<html>");
            tooltipBuilder.append(String.format("<b>%s</b><br>", name));
            if (acquiredBy != null) {
                tooltipBuilder.append(String.format(
                    "<p><font color='gray'>by </font>%s</p>",
                    acquiredBy
                ));
            }
            String droppedByNPCName = listItem.getDroppedByNPCName();
            if (droppedByNPCName != null) {
                tooltipBuilder.append(String.format(
                    "<p><font color='gray'>drop from </font>%s</p>",
                    droppedByNPCName
                ));
            }
            if (acquiredAt != null) {
                tooltipBuilder.append(String.format("<font color='gray'>%s</font>", acquiredAt));
            }
            tooltipBuilder.append("</html>");

            label.setToolTipText(tooltipBuilder.toString());

            return label;
        });

        scheduleRelativeTimeUpdate(list);

        Consumer<List<MainViewViewModel.ListItem>> setter = (newListItems) -> Bindings.invokeOnEDT(() -> {
            if (newListItems == null) {
                list.setListData(new MainViewViewModel.ListItem[0]);
                return;
            }
            list.setListData(newListItems.toArray(new MainViewViewModel.ListItem[0]));
        });

        PropertyChangeListener listItemsListener = (event) -> {
            @SuppressWarnings("unchecked")
            List<MainViewViewModel.ListItem> newListItems = (List<MainViewViewModel.ListItem>) event.getNewValue();
            setter.accept(newListItems);
        };
        viewModel.unlockedItemListItems.addListener(listItemsListener);
        setter.accept(viewModel.unlockedItemListItems.get());

        panel.add(new JScrollPane(list), BorderLayout.CENTER);

        listBinding = () -> viewModel.unlockedItemListItems.removeListener(listItemsListener);

        return panel;
    }

    private void scheduleRelativeTimeUpdate(JList<?> list) {
        // cancel previous timer if active
        if (relativeTimeUpdateTimer != null && relativeTimeUpdateTimer.isRunning()) {
            relativeTimeUpdateTimer.stop();
        }

        // start a new 1-minute timer
        relativeTimeUpdateTimer = new Timer(
            60_000, e -> {
            list.repaint();               // update visible relative times
            scheduleRelativeTimeUpdate(list); // restart countdown
        }
        );
        relativeTimeUpdateTimer.setRepeats(false);
        relativeTimeUpdateTimer.start();
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        MainView create(MainViewViewModel viewModel);
    }

    private static final class FactoryImpl implements Factory {

        @Inject
        private BUResourceService buResourceService;

        @Override
        public MainView create(MainViewViewModel viewModel) {
            return new MainView(viewModel, buResourceService);
        }
    }
}

package com.elertan.panel.screens.main.unlockedItems.items;

import com.elertan.ItemUnlockService;
import com.elertan.data.MembersDataProvider;
import com.elertan.models.Member;
import com.elertan.models.UnlockedItem;
import com.elertan.panel.screens.main.UnlockedItemsScreenViewModel;
import com.elertan.ui.Property;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.beans.PropertyChangeEvent;
import java.beans.PropertyChangeListener;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.swing.JOptionPane;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.NPCComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.AsyncBufferedImage;

public class MainViewViewModel implements AutoCloseable {

    public final Property<ViewState> viewState;
    public final Property<List<ListItem>> unlockedItemListItems;
    private final Property<List<UnlockedItem>> allUnlockedItems;
    private final Property<Map<Long, Member>> membersMap;
    private final Property<Map<Integer, String>> npcIdToNameMap = new Property<>(null);
    private final Map<Integer, AsyncBufferedImage> iconCache = new ConcurrentHashMap<>();
    private final MembersDataProvider membersDataProvider;
    private final ClientThread clientThread;
    private final Client client;
    private final ItemUnlockService itemUnlockService;
    private final PropertyChangeListener allUnlockedItemsListener = this::allUnlockedItemsListener;
    private final MembersDataProvider.MemberMapListener memberMapListener;
    private final ItemManager itemManager;

    private MainViewViewModel(
        Property<List<UnlockedItem>> allUnlockedItems,
        Property<String> searchText,
        Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy,
        Property<Long> unlockedByAccountHash,
        MembersDataProvider membersDataProvider,
        ItemManager itemManager,
        ClientThread clientThread,
        Client client,
        ItemUnlockService itemUnlockService
    ) {
        this.allUnlockedItems = allUnlockedItems;
        this.membersDataProvider = membersDataProvider;
        this.clientThread = clientThread;
        this.client = client;
        this.itemUnlockService = itemUnlockService;

        allUnlockedItems.addListener(allUnlockedItemsListener);
        onNewUnlockedItems(allUnlockedItems.get());

        memberMapListener = new MembersDataProvider.MemberMapListener() {
            @Override
            public void onUpdate(Member newMember, Member oldMember) {
                membersMap.set(membersDataProvider.getMembersMap());
            }

            @Override
            public void onDelete(Member member) {
                membersMap.set(membersDataProvider.getMembersMap());
            }
        };
        this.itemManager = itemManager;
        membersDataProvider.addMemberMapListener(memberMapListener);
        membersMap = new Property<>(membersDataProvider.getMembersMap());

        membersDataProvider.await(null).whenComplete((__, throwable) -> {
            if (throwable != null) {
                return;
            }
            membersMap.set(membersDataProvider.getMembersMap());
        });

        unlockedItemListItems = Property.deriveManyAsync(
            Arrays.asList(
                allUnlockedItems,
                membersMap,
                npcIdToNameMap,
                searchText,
                sortedBy,
                unlockedByAccountHash
            ),
            (values) -> {
                @SuppressWarnings("unchecked")
                List<UnlockedItem> allUnlockedItemsValue = (List<UnlockedItem>) values.get(0);
                @SuppressWarnings("unchecked")
                Map<Long, Member> membersMapValue = (Map<Long, Member>) values.get(1);
                @SuppressWarnings("unchecked")
                Map<Integer, String> npcIdToNameMapValue = (Map<Integer, String>) values.get(2);
                String searchTextValue = (String) values.get(3);
                UnlockedItemsScreenViewModel.SortedBy sortedByValue = (UnlockedItemsScreenViewModel.SortedBy) values.get(
                    4);
                Long unlockedByAccountHashValue = (Long) values.get(5);

                if (allUnlockedItemsValue == null || membersMapValue == null
                    || npcIdToNameMapValue == null) {
                    return null;
                }

                String searchTextLowerCase =
                    searchTextValue == null ? null : searchTextValue.toLowerCase().trim();
                if (searchTextLowerCase != null && searchTextLowerCase.isEmpty()) {
                    searchTextLowerCase = null;
                }

                final String searchTerm = searchTextLowerCase;
                return allUnlockedItemsValue.stream()
                    .filter(item -> {
                        if (unlockedByAccountHashValue != null
                            && item.getAcquiredByAccountHash() != unlockedByAccountHashValue) {
                            return false;
                        }
                        return searchTerm == null || item.getName()
                            .toLowerCase()
                            .contains(searchTerm);
                    })
                    .sorted((left, right) -> {
                        int value = 0;

                        switch (sortedByValue) {
                            case UNLOCKED_AT_ASC:
                                value = left.getAcquiredAt()
                                    .getValue()
                                    .compareTo(right.getAcquiredAt().getValue());
                                break;
                            case ALPHABETICAL_ASC:
                                value = left.getName().compareToIgnoreCase(right.getName());
                                break;
                            case PLAYER_ASC: {
                                Member leftMember = membersMapValue.get(left.getAcquiredByAccountHash());
                                Member rightMember = membersMapValue.get(right.getAcquiredByAccountHash());
                                if (leftMember != null && rightMember != null) {
                                    value = leftMember.getName()
                                        .compareToIgnoreCase(rightMember.getName());
                                } else if (leftMember == null) {
                                    value = 1;
                                } else {
                                    value = -1;
                                }
                                break;
                            }
                            case UNLOCKED_AT_DESC:
                                value = right.getAcquiredAt()
                                    .getValue()
                                    .compareTo(left.getAcquiredAt().getValue());
                                break;
                            case ALPHABETICAL_DESC:
                                value = right.getName().compareToIgnoreCase(left.getName());
                                break;
                            case PLAYER_DESC: {
                                Member leftMember = membersMapValue.get(left.getAcquiredByAccountHash());
                                Member rightMember = membersMapValue.get(right.getAcquiredByAccountHash());
                                if (leftMember != null && rightMember != null) {
                                    value = rightMember.getName()
                                        .compareToIgnoreCase(leftMember.getName());
                                } else if (leftMember == null) {
                                    value = -1;
                                } else {
                                    value = 1;
                                }
                                break;
                            }
                        }
                        if (value == 0) {
                            // Default to unlocked at descending for consistency when items are equal
                            return right.getAcquiredAt()
                                .getValue()
                                .compareTo(left.getAcquiredAt().getValue());
                        }
                        return value;
                    })
                    .map((unlockedItem) -> {
                        Member acquiredByMember = membersMapValue.get(unlockedItem.getAcquiredByAccountHash());
                        AsyncBufferedImage icon = getCachedIcon(unlockedItem.getId());
                        String droppedByNPCName = npcIdToNameMapValue.get(unlockedItem.getDroppedByNPCId());
                        return new ListItem(
                            unlockedItem,
                            acquiredByMember,
                            icon,
                            droppedByNPCName
                        );
                    })
                    .collect(Collectors.toList());
            }
        );
        viewState = unlockedItemListItems.derive(list -> list == null ? ViewState.LOADING
            : ViewState.READY);
    }

    @Override
    public void close() throws Exception {
        membersDataProvider.removeMemberMapListener(memberMapListener);
        allUnlockedItems.removeListener(allUnlockedItemsListener);
    }

    public void removeFromUnlockedItems(ListItem listItem) {
        UnlockedItem unlockedItem = listItem.getItem();
        if (unlockedItem == null) {
            return;
        }

        int result = JOptionPane.showConfirmDialog(
            null,
            String.format(
                "Removing '%s' from the unlocked items is a permanent action.\n\n",
                unlockedItem.getName()
            )
                + "This means in order to unlock this item again, you will need to acquire it again.",
            "Confirm remove unlocked item",
            JOptionPane.YES_NO_OPTION,
            JOptionPane.WARNING_MESSAGE
        );
        if (result != JOptionPane.YES_OPTION) {
            return;
        }

        int itemId = unlockedItem.getId();
        clientThread.invoke(() -> itemUnlockService.removeUnlockedItemById(itemId));

    }

    @SuppressWarnings("unchecked")
    private void allUnlockedItemsListener(PropertyChangeEvent propertyChangeEvent) {
        List<UnlockedItem> newUnlockedItems = (List<UnlockedItem>) propertyChangeEvent.getNewValue();
        onNewUnlockedItems(newUnlockedItems);
    }

    private void onNewUnlockedItems(List<UnlockedItem> newUnlockedItems) {
        clientThread.invokeLater(() -> {
            if (newUnlockedItems == null) {
                npcIdToNameMap.set(null);
                return;
            }

            Map<Integer, String> npcIdToNameMapValue = new HashMap<>();
            for (UnlockedItem unlockedItem : newUnlockedItems) {
                Integer npcId = unlockedItem.getDroppedByNPCId();
                if (npcId == null || npcIdToNameMapValue.containsKey(npcId)) {
                    continue;
                }
                NPCComposition npcComposition = client.getNpcDefinition(unlockedItem.getDroppedByNPCId());
                npcIdToNameMapValue.put(npcId, npcComposition.getName());
            }
            npcIdToNameMap.set(npcIdToNameMapValue);
        });
    }

    private AsyncBufferedImage getCachedIcon(int id) {
        return iconCache.computeIfAbsent(id, itemManager::getImage);
    }

    public enum ViewState {
        LOADING,
        EMPTY,
        READY
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        MainViewViewModel create(
            Property<List<UnlockedItem>> allUnlockedItems,
            Property<String> searchText,
            Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy,
            Property<Long> unlockedByAccountHash
        );
    }

    @Singleton
    private static final class FactoryImpl implements Factory {

        @Inject
        private MembersDataProvider membersDataProvider;
        @Inject
        private ItemManager itemManager;
        @Inject
        private ClientThread clientThread;
        @Inject
        private Client client;
        @Inject
        private ItemUnlockService itemUnlockService;

        @Override
        public MainViewViewModel create(
            Property<List<UnlockedItem>> allUnlockedItems,
            Property<String> searchText,
            Property<UnlockedItemsScreenViewModel.SortedBy> sortedBy,
            Property<Long> unlockedByAccountHash
        ) {
            return new MainViewViewModel(
                allUnlockedItems,
                searchText,
                sortedBy,
                unlockedByAccountHash,
                membersDataProvider,
                itemManager,
                clientThread,
                client,
                itemUnlockService
            );
        }
    }

    @Value
    public static class ListItem {

        UnlockedItem item;
        Member acquiredByMember;
        AsyncBufferedImage icon;
        String droppedByNPCName;
    }
}

