public class RemoteStepView extends JPanel implements AutoCloseable {

    private final RemoteStepViewViewModel viewModel;
    private final EntryViewViewModel entryViewViewModel;
    private final CheckingViewViewModel checkingViewViewModel;
    private final AutoCloseable stateViewCardLayoutBinding;

    private RemoteStepView(
        RemoteStepViewViewModel viewModel,
        EntryViewViewModel entryViewViewModel,
        CheckingViewViewModel checkingViewViewModel
    ) {
        this.viewModel = viewModel;
        this.entryViewViewModel = entryViewViewModel;
        this.checkingViewViewModel = checkingViewViewModel;

        setLayout(new BorderLayout(0, 10));
        setBorder(BorderFactory.createEmptyBorder(10, 5, 10, 5));

        // Title/header wrapper (stays static above cards)
        JLabel titleLabel = new JLabel("Remote Configuration");
        titleLabel.setFont(titleLabel.getFont().deriveFont(Font.BOLD, 15f));
        titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setOpaque(false);
        header.add(titleLabel);
        header.add(Box.createVerticalStrut(10));
        add(header, BorderLayout.NORTH);

        CardLayout stateViewCardLayout = new CardLayout();
        JPanel stateViewPanel = new JPanel(stateViewCardLayout);
        stateViewCardLayoutBinding = Bindings.bindCardLayout(
            stateViewPanel,
            stateViewCardLayout,
            viewModel.stateView,
            this::buildStateView
        );

        add(stateViewPanel, BorderLayout.CENTER);
    }

    @Override
    public void close() throws Exception {
        stateViewCardLayoutBinding.close();
        viewModel.close();
    }

    private JPanel buildStateView(RemoteStepViewViewModel.StateView stateView) {
        switch (stateView) {
            case ENTRY: {
                return new EntryView(entryViewViewModel);
            }
            case CHECKING: {
                return new CheckingView(checkingViewViewModel);
            }
        }

        throw new IllegalArgumentException("Unknown state view: " + stateView);
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        RemoteStepView create(RemoteStepViewViewModel viewModel);
    }

    @Singleton
    private static final class FactoryImpl implements Factory {

        private final EntryViewViewModel.Factory entryViewViewModelFactory;
        private final CheckingViewViewModel.Factory checkingViewViewModelFactory;

        @Inject
        public FactoryImpl(
            EntryViewViewModel.Factory entryViewViewModelFactory,
            CheckingViewViewModel.Factory checkingViewViewModelFactory
        ) {
            this.entryViewViewModelFactory = entryViewViewModelFactory;
            this.checkingViewViewModelFactory = checkingViewViewModelFactory;
        }

        @Override
        public RemoteStepView create(RemoteStepViewViewModel viewModel) {
            EntryViewViewModel entryViewViewModel = entryViewViewModelFactory.create(new EntryViewViewModel.Listener() {
                @Override
                public CompletableFuture<String> trySubmit(FirebaseRealtimeDatabaseURL url) {
                    return viewModel.onEntryViewTrySubmit(url);
                }

                @Override
                public void onBack() {
                    viewModel.onBack();
                }
            });
            CheckingViewViewModel checkingViewViewModel = checkingViewViewModelFactory.create(
                viewModel::onCancelChecking);

            return new RemoteStepView(viewModel, entryViewViewModel, checkingViewViewModel);
        }
    }
}

package com.elertan.panel.screens.setup;

import com.elertan.remote.firebase.FirebaseRealtimeDatabase;
import com.elertan.remote.firebase.FirebaseRealtimeDatabaseURL;
import com.elertan.ui.Property;
import com.google.inject.ImplementedBy;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicReference;
import lombok.Setter;
import okhttp3.OkHttpClient;

public final class RemoteStepViewViewModel implements AutoCloseable {

    public final Property<StateView> stateView = new Property<>(StateView.ENTRY);
    private final AtomicReference<TrySubmitAttempt> trySubmitAttempt = new AtomicReference<>(null);
    private final OkHttpClient httpClient;
    private final Listener listener;

    private RemoteStepViewViewModel(OkHttpClient httpClient, Listener listener) {
        this.httpClient = httpClient;
        this.listener = listener;
    }

    @Override
    public void close() throws Exception {
        TrySubmitAttempt attempt = trySubmitAttempt.getAndSet(null);
        if (attempt != null) {
            attempt.cancel();
        }
    }

    public CompletableFuture<String> onEntryViewTrySubmit(FirebaseRealtimeDatabaseURL url) {
        stateView.set(StateView.CHECKING);
        CompletableFuture<String> future = new CompletableFuture<>();

        TrySubmitAttempt attempt = trySubmitAttempt.get();
        if (attempt != null) {
            attempt.cancel();
            trySubmitAttempt.set(null);
        }

        attempt = new TrySubmitAttempt();
        attempt.setFuture(future);
        trySubmitAttempt.set(attempt);

        // Reset state when this attempt finishes
        future.whenComplete((__, throwable) -> {
            trySubmitAttempt.set(null);
            stateView.set(StateView.ENTRY);
        });

        CompletableFuture<Boolean> firebaseRealtimeDatabaseCanConnectToFuture = FirebaseRealtimeDatabase.canConnectTo(
            httpClient,
            url
        );
        attempt.setFirebaseRealtimeDatabaseCanConnectToFuture(
            firebaseRealtimeDatabaseCanConnectToFuture);

        TrySubmitAttempt finalAttempt = attempt;
        firebaseRealtimeDatabaseCanConnectToFuture.whenComplete((canConnect, throwable) -> {
            if (throwable != null) {
                future.completeExceptionally(throwable);
                return;
            }
            if (!canConnect) {
                future.complete(
                    "Could not connect to the Firebase Realtime database, please check the URL or try again later.");
                return;
            }

            CompletableFuture<Void> onRemoteStepFinishedFuture = listener.onRemoteStepFinished(url);
            finalAttempt.setOnRemoteStepFinishedFuture(onRemoteStepFinishedFuture);

            onRemoteStepFinishedFuture.whenComplete((__, throwable2) -> {
                if (throwable2 != null) {
                    future.completeExceptionally(throwable2);
                    return;
                }
                future.complete(null);
            });
        });

        return future;
    }

    public void onCancelChecking() {
        TrySubmitAttempt attempt = trySubmitAttempt.getAndSet(null);
        if (attempt != null) {
            attempt.cancel();
        }
        stateView.set(StateView.ENTRY);
    }

    public void onBack() {
        TrySubmitAttempt attempt = trySubmitAttempt.getAndSet(null);
        if (attempt != null) {
            attempt.cancel();
        }
        stateView.set(StateView.ENTRY);
        listener.onBack();
    }

    public enum StateView {
        ENTRY,
        CHECKING
    }

    @ImplementedBy(FactoryImpl.class)
    public interface Factory {

        RemoteStepViewViewModel create(Listener listener);
    }

    public interface Listener {

        CompletableFuture<Void> onRemoteStepFinished(FirebaseRealtimeDatabaseURL url);

        void onBack();
    }

    @Singleton
    private static class FactoryImpl implements Factory {

        private final OkHttpClient httpClient;

        @Inject
        public FactoryImpl(OkHttpClient httpClient) {
            this.httpClient = httpClient;
        }

        @Override
        public RemoteStepViewViewModel create(Listener listener) {
            return new RemoteStepViewViewModel(httpClient, listener);
        }
    }

    private static final class TrySubmitAttempt {

        @Setter
        private CompletableFuture<String> future;
        @Setter
        private CompletableFuture<Boolean> firebaseRealtimeDatabaseCanConnectToFuture;
        @Setter
        private CompletableFuture<Void> onRemoteStepFinishedFuture;

        public void cancel() {
            if (future != null) {
                future.cancel(true);
            }
            if (firebaseRealtimeDatabaseCanConnectToFuture != null) {
                firebaseRealtimeDatabaseCanConnectToFuture.cancel(true);
            }
            if (onRemoteStepFinishedFuture != null) {
                onRemoteStepFinishedFuture.cancel(true);
            }
        }
    }
}

