        groundItemOwnedByDataProviderListener = new GroundItemOwnedByDataProvider.Listener() {
            @Override
            public void onReadAll(ConcurrentHashMap<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> map) {
            }

            @Override
            public void onAdd(GroundItemOwnedByKey key, String entryKey, GroundItemOwnedByData value) {
            }

            @Override
            public void onRemove(GroundItemOwnedByKey key, String entryKey) {
            }
        };
        groundItemOwnedByDataProvider.addMapListener(groundItemOwnedByDataProviderListener);

        scheduler = Executors.newSingleThreadScheduledExecutor();
        scheduler.scheduleAtFixedRate(this::cleanupExpiredGroundItems, 10, 10, TimeUnit.SECONDS);

        groundItemOwnedByDataProvider.await(null).whenComplete((__, throwable) -> {
            if (throwable != null) {
                log.error("GroundItemOwnedByDataProvider await failed", throwable);
                return;
            }

            cleanupExpiredGroundItemsForEveryone();
        });
    }

    @Override
    public void shutDown() throws Exception {
        groundItemOwnedByDataProvider.removeMapListener(groundItemOwnedByDataProviderListener);

        scheduler.shutdown();
    }

    public void onItemSpawned(ItemSpawned event) {
        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }

        PolicyContext context = createContext();
        if (!context.shouldApplyForRules(GameRules::isRestrictGroundItems)) {
            return;
        }

        TileItem tileItem = event.getItem();
        if (tileItem.getOwnership() != TileItem.OWNERSHIP_SELF
            && tileItem.getOwnership() != TileItem.OWNERSHIP_GROUP) {
            // item does not belong to me, ignore it
            return;
        }
        Tile tile = event.getTile();
        WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());
        WorldView worldView = client.findWorldViewFromWorldPoint(worldPoint);
        int itemId = tileItem.getId();
        GroundItemOwnedByKey key = GroundItemOwnedByKey.of(itemId, client.getWorld(), worldView.getId(), worldPoint);

        ConcurrentHashMap<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> groundItemOwnedByMap = groundItemOwnedByDataProvider.getGroundItemOwnedByMap();
        if (groundItemOwnedByMap == null) {
            log.warn("Ground item spawned for me but groundItemOwnedByMap is null");
            return;
        }

        long despawnTimeTicks = tileItem.getDespawnTime() - client.getTickCount();
        Duration despawnDuration = TickUtils.ticksToDuration(despawnTimeTicks);
        OffsetDateTime despawnsAt = OffsetDateTime.now().plus(despawnDuration);
        GroundItemOwnedByData newGroundItemOwnedByData = new GroundItemOwnedByData(
            client.getAccountHash(),
            new ISOOffsetDateTime(despawnsAt),
            null
        );

        groundItemOwnedByDataProvider.addEntry(key, newGroundItemOwnedByData)
            .whenComplete((result, throwable) -> {
                if (throwable != null) {
                    log.error("GroundItemOwnedByDataProvider addEntry failed", throwable);
                }
            });
    }

    public void onItemDespawned(ItemDespawned event) {
        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }

        TileItem tileItem = event.getItem();
        if (tileItem.getOwnership() != TileItem.OWNERSHIP_SELF
            && tileItem.getOwnership() != TileItem.OWNERSHIP_GROUP) {
            // item does not belong to me, ignore it
            return;
        }
        Tile tile = event.getTile();
        WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());
        WorldView worldView = client.findWorldViewFromWorldPoint(worldPoint);
        int itemId = tileItem.getId();
        GroundItemOwnedByKey key = GroundItemOwnedByKey.of(itemId, client.getWorld(), worldView.getId(), worldPoint);

        if (!groundItemOwnedByDataProvider.hasEntries(key)) {
            log.debug("gi {} has no entries, ignore", key);
            return;
        }

        groundItemOwnedByDataProvider.removeOneEntry(key).whenComplete((result, throwable) -> {
            if (throwable != null) {
                log.error("GroundItemOwnedByDataProvider removeOneEntry failed", throwable);
            }
        });
    }

    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }

        PolicyContext context = createContext();
        enforceItemTakePolicyWhereNecessary(event, context);
    }

    private void enforceItemTakePolicyWhereNecessary(MenuOptionClicked event,
        PolicyContext context) {
        MenuAction menuAction = event.getMenuAction();
        String menuOption = event.getMenuOption();
        boolean isGroundItemMenuAction =
            menuAction.ordinal() >= MenuAction.GROUND_ITEM_FIRST_OPTION.ordinal()
                && menuAction.ordinal() <= MenuAction.GROUND_ITEM_FIFTH_OPTION.ordinal();
        boolean isWidgetTargetOnGroundItemAction =
            menuAction.ordinal() == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM.ordinal();
        if (!isGroundItemMenuAction && !isWidgetTargetOnGroundItemAction) {
            return;
        }

        if (!menuOption.equals("Take") && !menuOption.equals("Cast")) {
            return;
        }
        int itemId = event.getId();
        if (itemId <= 1) {
            return;
        }

        // In last man standing we want to allow taking any items
        if (minigameService.isPlayingLastManStanding()) {
            return;
        }

        GetClickedTileItemOutput output = getClickedTileItem(event);
        if (output == null) {
            log.warn(
                "Ground item not found at scene ({}, {}) for id {}",
                event.getParam0(),
                event.getParam1(),
                itemId
            );
            return;
        }
        Tile tile = output.getTile();
        TileItem tileItem = output.getTileItem();

        ItemComposition itemComposition = client.getItemDefinition(itemId);

        int ownership = tileItem.getOwnership();
        if (ownership == TileItem.OWNERSHIP_NONE) {
            log.debug("Item '{}' is not owned by anyone, allow take", itemComposition.getName());
            return;
        }

        WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());
        WorldView worldView = client.findWorldViewFromWorldPoint(worldPoint);
        GroundItemOwnedByKey key = GroundItemOwnedByKey.of(itemId, client.getWorld(), worldView.getId(), worldPoint);

        ConcurrentHashMap<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> groundItemOwnedByMap = groundItemOwnedByDataProvider.getGroundItemOwnedByMap();
        if (groundItemOwnedByMap == null) {
            boolean mustPerformCheck =
                context.isMustEnforceStrictPolicies() || (context.getGameRules() != null && (
                    context.getGameRules().isRestrictGroundItems() || context.getGameRules()
                        .isRestrictPlayerVersusPlayerLoot()
                ));
            if (mustPerformCheck) {
                event.consume();
                buChatService.sendErrorMessage(chatMessageProvider.messageFor(
                    MessageKey.STILL_LOADING_PLEASE_WAIT));
            }
            return;
        }

        if (groundItemOwnedByDataProvider.hasEntries(key)) {
            // Our group owns at least one instance of this item at this location

            // Check for pvp acquired items
            boolean mustPerformPlayerVersusPlayerCheck =
                context.isMustEnforceStrictPolicies() || (context.getGameRules() != null
                    && context.getGameRules().isRestrictPlayerVersusPlayerLoot());

            if (mustPerformPlayerVersusPlayerCheck) {
                ConcurrentHashMap<String, GroundItemOwnedByData> entries = groundItemOwnedByDataProvider.getEntries(key);
                if (entries != null) {
                    for (GroundItemOwnedByData data : entries.values()) {
                        String droppedByPlayerName = data.getDroppedByPlayerName();
                        if (droppedByPlayerName != null) {
                            log.debug(
                                "Performing player versus player loot check for item '{}' dropped by {}",
                                itemId,
                                droppedByPlayerName
                            );

                            Member member = null;
                            try {
                                member = memberService.getMemberByName(droppedByPlayerName);
                            } catch (Exception ignored) {
                            }
                            if (member != null) {
                                log.debug("Player '{}' is part of our group, allow take", droppedByPlayerName);
                                continue;
                            }

                            log.debug("Player '{}' is not part of our group, deny take", droppedByPlayerName);
                            buChatService.sendRestrictionMessage(MessageKey.PLAYER_VERSUS_PLAYER_LOOT_RESTRICTION);
                            return;
                        }
                    }
                }
            }
            return;
        }

        if (ownership == TileItem.OWNERSHIP_SELF) {
            log.debug("Item '{}' is owned by me, allow take", itemComposition.getName());
            return;
        }

        boolean mustPerformGroundItemsCheck =
            context.isMustEnforceStrictPolicies() || (context.getGameRules() != null
                && context.getGameRules().isRestrictGroundItems());
        if (mustPerformGroundItemsCheck) {
            event.consume();
            MessageKey messageKey = isWidgetTargetOnGroundItemAction
                ? MessageKey.GROUND_ITEM_CAST_RESTRICTION
                : MessageKey.GROUND_ITEM_TAKE_RESTRICTION;
            buChatService.sendRestrictionMessage(messageKey);
        }
    }

    private GetClickedTileItemOutput getClickedTileItem(MenuOptionClicked event) {
        // For ground item menu actions, param0 = scene X, param1 = scene Y, id = item ID
        final int sceneX = event.getParam0();
        final int sceneY = event.getParam1();
        final int itemId = event.getId();
        WorldView worldView = client.getTopLevelWorldView();
        final int plane = worldView.getPlane();

        Scene scene = worldView.getScene();
        if (scene == null) {
            return null;
        }

        Tile[][][] tiles = scene.getTiles();
        if (tiles == null || plane < 0 || plane >= tiles.length) {
            return null;
        }

        if (sceneX < 0 || sceneY < 0 || sceneX >= tiles[plane].length
            || sceneY >= tiles[plane][sceneX].length) {
            return null;
        }

        Tile tile = tiles[plane][sceneX][sceneY];
        if (tile == null || tile.getGroundItems() == null) {
            return null;
        }

        for (TileItem ti : tile.getGroundItems()) {
            if (ti.getId() == itemId) {
                return new GetClickedTileItemOutput(tile, ti);
            }
        }
        return null;
    }

    // Called from scheduler thread - must use clientThread.invoke() for client access
    private void cleanupExpiredGroundItems() {
        clientThread.invoke(() -> {
            ConcurrentHashMap<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> map = groundItemOwnedByDataProvider.getGroundItemOwnedByMap();
            if (map == null || map.isEmpty()) {
                return;
            }

            OffsetDateTime now = OffsetDateTime.now();
            long accountHash = client.getAccountHash();

            for (Map.Entry<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> keyEntry : map.entrySet()) {
                GroundItemOwnedByKey key = keyEntry.getKey();
                ConcurrentHashMap<String, GroundItemOwnedByData> entries = keyEntry.getValue();
                if (entries == null) {
                    continue;
                }

                for (Map.Entry<String, GroundItemOwnedByData> entry : entries.entrySet()) {
                    String entryKey = entry.getKey();
                    GroundItemOwnedByData data = entry.getValue();
                    if (data.getAccountHash() != accountHash) {
                        continue;
                    }
                    if (data.getDespawnsAt().getValue().isAfter(now)) {
                        continue;
                    }

                    log.debug("Cleaning up expired ground item {} entry {}", key, entryKey);

                    groundItemOwnedByDataProvider.removeEntry(key, entryKey).whenComplete((result, throwable) -> {
                        if (throwable != null) {
                            log.error("Failed to clean up expired ground item {} entry {}", key, entryKey, throwable);
                        }
                    });
                }
            }
        });
    }

    private void cleanupExpiredGroundItemsForEveryone() {
        log.debug("Cleaning up expired ground items for everyone");

        ConcurrentHashMap<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> map = groundItemOwnedByDataProvider.getGroundItemOwnedByMap();
        if (map == null || map.isEmpty()) {
            log.debug("Ground item owned by map is empty, nothing to clean up");
            return;
        }

        OffsetDateTime now = OffsetDateTime.now();

        for (Map.Entry<GroundItemOwnedByKey, ConcurrentHashMap<String, GroundItemOwnedByData>> keyEntry : map.entrySet()) {
            GroundItemOwnedByKey key = keyEntry.getKey();
            ConcurrentHashMap<String, GroundItemOwnedByData> entries = keyEntry.getValue();
            if (entries == null) {
                continue;
            }

            for (Map.Entry<String, GroundItemOwnedByData> entry : entries.entrySet()) {
                String entryKey = entry.getKey();
                GroundItemOwnedByData data = entry.getValue();
                if (data.getDespawnsAt().getValue().isAfter(now)) {
                    continue;
                }

                log.debug(
                    "Cleaning up expired ground item {} entry {} for account hash: {}",
                    key,
                    entryKey,
                    data.getAccountHash()
                );

                groundItemOwnedByDataProvider.removeEntry(key, entryKey).whenComplete((result, throwable) -> {
                    if (throwable != null) {
                        log.error("Failed to clean up expired ground item {} entry {}", key, entryKey, throwable);
                    }
                });
            }
        }
    }

    @Value
    private static class GetClickedTileItemOutput {

        @NonNull Tile tile;
        @NonNull TileItem tileItem;
    }
}

package com.elertan.policies;

import com.elertan.AccountConfigurationService;
import com.elertan.BUChatService;
import com.elertan.BUPluginConfig;
import com.elertan.BUPluginLifecycle;
import com.elertan.BUSoundHelper;
import com.elertan.GameRulesService;
import com.elertan.MemberService;
import com.elertan.PolicyService;
import com.elertan.WorldTypeService;
import com.elertan.chat.ChatMessageProvider;
import com.elertan.chat.ChatMessageProvider.MessageKey;
import com.elertan.models.GameRules;
import com.elertan.models.Member;
import com.elertan.utils.TextUtils;
import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.awt.event.KeyEvent;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicReference;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.ScriptEvent;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.KeyListener;
import net.runelite.client.input.KeyManager;

@Slf4j
@Singleton
public class PlayerOwnedHousePolicy extends PolicyBase implements BUPluginLifecycle {

    private static final int CHATBOX_INPUT_SCRIPT_ID = 112;
    private static final int CHATBOX_INPUT_CLOSE_SCRIPT_ID = 138;

    @Inject
    private Client client;
    @Inject
    private ClientThread clientThread;
    @Inject
    private BUPluginConfig buPluginConfig;
    @Inject
    private MemberService memberService;
    @Inject
    private BUChatService buChatService;
    @Inject
    private ChatMessageProvider chatMessageProvider;
    @Inject
    private BUSoundHelper buSoundHelper;
    @Inject
    private KeyManager keyManager;

    private volatile boolean isStarted = false;
    private volatile boolean isReadFriendsHouseChatboxInputLoopRunning = false;
    private String lastFriendsHouseEnteredName = null;
    private KeyListener keyListener;

    @Inject
    public PlayerOwnedHousePolicy(AccountConfigurationService accountConfigurationService,
        GameRulesService gameRulesService, PolicyService policyService,
        WorldTypeService worldTypeService) {
        super(accountConfigurationService, gameRulesService, policyService, worldTypeService);
    }

    @Override
    public void startUp() throws Exception {
        isStarted = true;

        keyListener = new KeyListener() {
            @Override
            public void keyTyped(KeyEvent e) {
                if (!isReadFriendsHouseChatboxInputLoopRunning) {
                    return;
                }

                if (e.getKeyChar() == '\n') {
                    if (lastFriendsHouseEnteredName != null
                        && !lastFriendsHouseEnteredName.isEmpty()) {
                        e.consume();
                    }
                }
            }

            @Override
            public void keyPressed(KeyEvent e) {
                if (!isReadFriendsHouseChatboxInputLoopRunning) {
                    return;
                }

                if (e.getKeyCode() == KeyEvent.VK_ENTER) {
                    if (lastFriendsHouseEnteredName != null
                        && !lastFriendsHouseEnteredName.isEmpty()) {
                        PolicyContext context = createContext();
                        if (!context.shouldApplyForRules(GameRules::isPreventPlayerOwnedHouse)) {
                            return;
                        }
                        enforcePolicyEnterKeyPressedOnFriendsHouseName(e);
                    }
                }
            }

            @Override
            public void keyReleased(KeyEvent e) {
                if (!isReadFriendsHouseChatboxInputLoopRunning) {
                    return;
                }

                if (e.getKeyCode() == KeyEvent.VK_ENTER) {
                    if (lastFriendsHouseEnteredName != null
                        && !lastFriendsHouseEnteredName.isEmpty()) {
                        e.consume();
                    }
                }
            }
        };
        keyManager.registerKeyListener(keyListener);
    }

    @Override
    public void shutDown() throws Exception {
        keyManager.unregisterKeyListener(keyListener);
        keyListener = null;

        isStarted = false;
    }

    public void onMenuOptionClicked(MenuOptionClicked event) {
        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }

        PolicyContext context = createContext();
        if (!context.shouldApplyForRules(GameRules::isPreventPlayerOwnedHouse)) {
            return;
        }
        MenuAction menuAction = event.getMenuAction();
        String menuOption = event.getMenuOption();
        // Enter house via POH board
        if (menuOption.equalsIgnoreCase("enter house")) {
            enforcePolicyEnterHouseMenuOptionClicked(event);
        }
        // Enter house via menu option right click on portal
        if (menuOption.equalsIgnoreCase("friend's house")) {
            enforcePolicyViewHouseMenuOptionClicked(event);
        }
        // Potentially continue'ing

        if (menuAction.ordinal() == MenuAction.WIDGET_CONTINUE.ordinal()) {
            Widget widget = event.getWidget();
            if (widget == null) {
                return;
            }
            String text = widget.getText();
            if (text.equalsIgnoreCase("go to a friend's house")) {
                enforcePolicyGoToAFriendsHouseMenuOptionClicked(event);
            }
        }
    }

    private void enforcePolicyEnterHouseMenuOptionClicked(MenuOptionClicked event) {
        Widget buttonWidget = event.getWidget();
        if (buttonWidget == null) {
            log.error("Button widget is null played owner house policy");
            return;
        }
        Widget pohboardNameWidget = client.getWidget(InterfaceID.PohBoard.NAME);
        if (pohboardNameWidget == null) {
            log.error("Pohboard name widget is null player owned house policy");
            return;
        }
        int buttonWidgetIdx = buttonWidget.getIndex();
        Widget pohNameWidget = pohboardNameWidget.getChild(buttonWidgetIdx);
        if (pohNameWidget == null) {
            log.error("Poh name widget is null player owned house policy");
            return;
        }
        String pohNameWidgetText = pohNameWidget.getText();
        if (pohNameWidgetText == null) {
            log.error("Poh name widget text is null player owned house policy");
            return;
        }

        boolean couldEnter = validateHouseEntryForPlayer(pohNameWidgetText);
        if (!couldEnter) {
            event.consume();
        }
    }

    private void enforcePolicyViewHouseMenuOptionClicked(MenuOptionClicked event) {
        log.debug(
            "Friend's house menu option clicked, waiting for friends house chatbox input ready");
        waitForFriendsHouseChatboxInputReady()
            .whenComplete((__, throwable) -> {
                if (throwable != null) {
                    log.error("Error waiting for friends house chatbox input ready", throwable);
                    return;
                }

                log.debug("Friends house chatbox input ready, starting checker");
                startReadFriendsHouseChatboxInputLoop();
            });
    }

    private void enforcePolicyGoToAFriendsHouseMenuOptionClicked(MenuOptionClicked event) {
        log.debug(
            "Go to a friend's house menu option clicked, waiting for friends house chatbox input ready");
        waitForFriendsHouseChatboxInputReady()
            .whenComplete((__, throwable) -> {
                if (throwable != null) {
                    log.error("Error waiting for friends house chatbox input ready", throwable);
                    return;
                }

                log.debug("Friends house chatbox input ready, starting checker");
                startReadFriendsHouseChatboxInputLoop();
            });
    }


    private CompletableFuture<Void> waitForFriendsHouseChatboxInputReady() {
        CompletableFuture<Void> future = new CompletableFuture<>();
        AtomicReference<Runnable> runnableRef = new AtomicReference<>();
        Runnable runnable = () -> {
            if (!isStarted) {
                Exception ex = new IllegalStateException("Policy is not started");
                future.completeExceptionally(ex);
                return;
            }
            boolean isReady = isFriendsHouseChatboxInputReady();
            if (isReady) {
                future.complete(null);
                return;
            }
            clientThread.invokeLater(runnableRef.get());
        };
        runnableRef.set(runnable);
        clientThread.invokeLater(runnable);

        return future;
    }

    private boolean isFriendsHouseChatboxInputReady() {
        Widget mesTextWidget = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
        if (mesTextWidget == null || mesTextWidget.isHidden()) {
            return false;
        }
        Widget mesText2Widget = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
        if (mesText2Widget == null || mesText2Widget.isHidden()) {
            return false;
        }
        String mesTextWidgetText = mesTextWidget.getText();
        if (mesTextWidgetText == null) {
            return false;
        }
        String mesText2WidgetText = mesText2Widget.getText();
        if (mesText2WidgetText == null) {
            return false;
        }
        return mesTextWidgetText.equalsIgnoreCase("enter name:");
    }

    private void startReadFriendsHouseChatboxInputLoop() {
        if (isReadFriendsHouseChatboxInputLoopRunning) {
            return;
        }
        isReadFriendsHouseChatboxInputLoopRunning = true;

        AtomicReference<Runnable> monitorLoopRef = new AtomicReference<>();
        Runnable monitorLoop = () -> {
            if (!isReadFriendsHouseChatboxInputLoopRunning) {
                return;
            }

            if (!isFriendsHouseChatboxInputReady()) {
                log.debug(
                    "reading friends house chatbox input halted because chatbox is not ready anymore");
                isReadFriendsHouseChatboxInputLoopRunning = false;
                return;
            }
            clientThread.invokeLater(monitorLoopRef.get());
        };
        monitorLoopRef.set(monitorLoop);
        clientThread.invokeLater(monitorLoopRef.get());
    }

    public void onScriptPreFired(ScriptPreFired event) {
        if (!accountConfigurationService.isBronzemanEnabled()) {
            return;
        }
        if (!isReadFriendsHouseChatboxInputLoopRunning) {
            return;
        }

        if (event.getScriptId() == CHATBOX_INPUT_SCRIPT_ID) {
            ScriptEvent scriptEvent = event.getScriptEvent();
            int typedChar = scriptEvent.getTypedKeyChar();
            if (typedChar == 0) {
                return;
            }
            if (typedChar == 8) {
                // 'Backspace'
                if (lastFriendsHouseEnteredName != null && !lastFriendsHouseEnteredName.isEmpty()) {
                    String newName = lastFriendsHouseEnteredName.substring(
                        0,
                        lastFriendsHouseEnteredName.length() - 1
                    );
                    if (newName.isEmpty()) {
                        newName = null;
                    }
                    setLastFriendsHouseEnteredName(newName);
                }
                return;
            }
            if (typedChar == 10) {
                return;
            }
            char typedCharChar = (char) typedChar;
            String newName =
                lastFriendsHouseEnteredName == null ? "" : lastFriendsHouseEnteredName;
            newName += typedCharChar;
            setLastFriendsHouseEnteredName(newName);
        } else if (event.getScriptId() == CHATBOX_INPUT_CLOSE_SCRIPT_ID) {
            isReadFriendsHouseChatboxInputLoopRunning = false;

            lastFriendsHouseEnteredName = null;
        }
    }

    private void setLastFriendsHouseEnteredName(String name) {
        if (Objects.equals(lastFriendsHouseEnteredName, name)) {
            return;
        }
        lastFriendsHouseEnteredName = name;
    }

    private void enforcePolicyEnterKeyPressedOnFriendsHouseName(KeyEvent e) {
        boolean couldEnter = validateHouseEntryForPlayer(lastFriendsHouseEnteredName);
        if (!couldEnter) {
            e.consume();
            clientThread.invoke(() -> client.runScript(
                CHATBOX_INPUT_CLOSE_SCRIPT_ID));
        }
    }

    private boolean validateHouseEntryForPlayer(String inputName) {
        String playerName = TextUtils.sanitizePlayerName(inputName);
        Member member;
        try {
            member = memberService.getMemberByName(playerName);
        } catch (Exception ex) {
            buChatService.sendRestrictionMessage(MessageKey.STILL_LOADING_PLEASE_WAIT);
            return false;
        }

        if (member == null) {
            buChatService.sendRestrictionMessage(MessageKey.POH_ENTER_RESTRICTION);
            return false;
        }

        return true;
    }
}

