package com.elertan.remote.firebase;

import com.elertan.remote.KeyListStoragePort;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;
import java.util.function.Function;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FirebaseKeyListStorageAdapterBase<K, V> implements KeyListStoragePort<K, V> {

    private final String basePath;
    private final FirebaseRealtimeDatabase db;
    private final Gson gson;
    private final ConcurrentLinkedQueue<Listener<K, V>> listeners = new ConcurrentLinkedQueue<>();
    private final Function<String, K> stringToKeyTransformer;
    private final Function<K, String> keyToStringTransformer;
    private final Function<JsonElement, V> deserializeFromJsonElement;

    private final ConcurrentHashMap<K, ConcurrentHashMap<String, V>> localCache = new ConcurrentHashMap<>();

    private final Consumer<FirebaseSSE> sseListener = this::sseListener;

    public FirebaseKeyListStorageAdapterBase(
        String basePath,
        FirebaseRealtimeDatabase db,
        Gson gson,
        Function<String, K> stringToKeyTransformer,
        Function<K, String> keyToStringTransformer,
        Function<JsonElement, V> deserializeFromJsonElement
    ) {
        if (basePath == null) {
            throw new IllegalArgumentException("basePath must not be null");
        }
        if (!basePath.startsWith("/")) {
            throw new IllegalArgumentException("basePath must start with '/'");
        }
        int lastIndexOfForwardSlash = basePath.lastIndexOf("/");
        if (lastIndexOfForwardSlash != 0) {
            throw new IllegalArgumentException("basePath must only be a starting resource");
        }
        this.basePath = basePath;
        this.db = db;
        this.gson = gson;
        this.stringToKeyTransformer = stringToKeyTransformer;
        this.keyToStringTransformer = keyToStringTransformer;
        this.deserializeFromJsonElement = deserializeFromJsonElement;

        FirebaseSSEStream stream = db.getStream();
        stream.addServerSentEventListener(sseListener);
    }

    @Override
    public void close() throws Exception {
        listeners.clear();
        localCache.clear();

        FirebaseSSEStream stream = db.getStream();
        stream.removeServerSentEventListener(sseListener);
    }

    @Override
    public CompletableFuture<Map<String, V>> read(K key) {
        String path = basePath + "/" + keyToStringTransformer.apply(key);
        return db.get(path)
            .thenApply(jsonElement -> {
                if (jsonElement == null || jsonElement.isJsonNull()) {
                    return Collections.emptyMap();
                }
                JsonObject obj = jsonElement.getAsJsonObject();
                Map<String, V> map = new HashMap<>();
                for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                    V value = deserializeFromJsonElement.apply(entry.getValue());
                    if (value != null) {
                        map.put(entry.getKey(), value);
                    }
                }
                return map;
            });
    }

    @Override
    public CompletableFuture<Map<K, Map<String, V>>> readAll() {
        return db.get(basePath)
            .thenApply(jsonElement -> {
                if (jsonElement == null || jsonElement.isJsonNull()) {
                    return Collections.emptyMap();
                }

                JsonObject obj = jsonElement.getAsJsonObject();
                Map<K, Map<String, V>> map = new HashMap<>();

                for (Map.Entry<String, JsonElement> keyEntry : obj.entrySet()) {
                    K key = stringToKeyTransformer.apply(keyEntry.getKey());
                    JsonElement keyValue = keyEntry.getValue();
                    if (keyValue == null || keyValue.isJsonNull() || !keyValue.isJsonObject()) {
                        continue;
                    }

                    Map<String, V> innerMap = new HashMap<>();
                    JsonObject innerObj = keyValue.getAsJsonObject();
                    for (Map.Entry<String, JsonElement> entryEntry : innerObj.entrySet()) {
                        V value = deserializeFromJsonElement.apply(entryEntry.getValue());
                        if (value != null) {
                            innerMap.put(entryEntry.getKey(), value);
                        }
                    }
                    if (!innerMap.isEmpty()) {
                        map.put(key, innerMap);
                    }
                }

                return map;
            });
    }

    @Override
    public CompletableFuture<String> add(K key, V value) {
        String path = basePath + "/" + keyToStringTransformer.apply(key);
        JsonElement jsonElement = gson.toJsonTree(value);
        return db.post(path, jsonElement)
            .thenApply(response -> {
                if (response != null && response.isJsonObject()) {
                    JsonObject obj = response.getAsJsonObject();
                    if (obj.has("name")) {
                        return obj.get("name").getAsString();
                    }
                }
                return null;
            });
    }

    @Override
    public CompletableFuture<Void> removeOne(K key) {
        ConcurrentHashMap<String, V> innerMap = localCache.get(key);
        if (innerMap == null || innerMap.isEmpty()) {
            return CompletableFuture.completedFuture(null);
        }

        Iterator<String> iterator = innerMap.keySet().iterator();
        if (!iterator.hasNext()) {
            return CompletableFuture.completedFuture(null);
        }
        String entryKey = iterator.next();

        return remove(key, entryKey);
    }

    @Override
    public CompletableFuture<Void> remove(K key, String entryKey) {
        String path = basePath + "/" + keyToStringTransformer.apply(key) + "/" + entryKey;
        return db.delete(path);
    }

    @Override
    public void addListener(Listener<K, V> listener) {
        listeners.add(listener);
    }

    @Override
    public void removeListener(Listener<K, V> listener) {
        listeners.remove(listener);
    }

    public ConcurrentHashMap<K, ConcurrentHashMap<String, V>> getLocalCache() {
        return localCache;
    }

    private void sseListener(FirebaseSSE event) {
        FirebaseSSEType type = event.getType();
        if (type != FirebaseSSEType.Put) {
            return;
        }

        String path = event.getPath();
        if (!path.startsWith(basePath)) {
            return;
        }
        String[] pathParts = Arrays.stream(path.split("/"))
            .filter(part -> !part.isEmpty())
            .toArray(String[]::new);
        int pathPartsLength = pathParts.length;

        if (pathPartsLength == 1) {
            // Full update of entire collection
            handleFullUpdate(event.getData());
        } else if (pathPartsLength == 2) {
            // Full list for a specific key
            String strKey = pathParts[1];
            K key = stringToKeyTransformer.apply(strKey);
            handleKeyFullUpdate(key, event.getData());
        } else if (pathPartsLength == 3) {
            // Single entry add/remove
            String strKey = pathParts[1];
            String entryKey = pathParts[2];
            K key = stringToKeyTransformer.apply(strKey);
            handleEntryUpdate(key, entryKey, event.getData());
        } else {
            log.debug(
                "FirebaseKeyListStorageAdapterBase ({}): too many path parts, ignoring: {}",
                basePath,
                path
            );
        }
    }

    private void handleFullUpdate(JsonElement jsonElement) {
        localCache.clear();
        Map<K, Map<String, V>> fullMap = new HashMap<>();

        if (jsonElement != null && !jsonElement.isJsonNull() && jsonElement.isJsonObject()) {
            JsonObject obj = jsonElement.getAsJsonObject();
            for (Map.Entry<String, JsonElement> keyEntry : obj.entrySet()) {
                K key;
                try {
                    key = stringToKeyTransformer.apply(keyEntry.getKey());
                } catch (Exception e) {
                    log.error("Failed to parse key: {}", keyEntry.getKey(), e);
                    continue;
                }

                JsonElement keyValue = keyEntry.getValue();
                if (keyValue == null || keyValue.isJsonNull() || !keyValue.isJsonObject()) {
                    continue;
                }

                ConcurrentHashMap<String, V> innerMap = new ConcurrentHashMap<>();
                JsonObject innerObj = keyValue.getAsJsonObject();

                for (Map.Entry<String, JsonElement> entryEntry : innerObj.entrySet()) {
                    String entryKey = entryEntry.getKey();
                    V value;
                    try {
                        value = deserializeFromJsonElement.apply(entryEntry.getValue());
                    } catch (Exception e) {
                        log.error("Failed to deserialize value for entry {}/{}", keyEntry.getKey(), entryKey, e);
                        continue;
                    }
                    if (value != null) {
                        innerMap.put(entryKey, value);
                    }
                }

                if (!innerMap.isEmpty()) {
                    localCache.put(key, innerMap);
                    fullMap.put(key, new HashMap<>(innerMap));
                }
            }
        }

        notifyListenersOnFullUpdate(fullMap);
    }

    private void handleKeyFullUpdate(K key, JsonElement jsonElement) {
        localCache.remove(key);

        if (jsonElement == null || jsonElement.isJsonNull()) {
            return;
        }

        if (!jsonElement.isJsonObject()) {
            return;
        }

        ConcurrentHashMap<String, V> innerMap = new ConcurrentHashMap<>();
        JsonObject obj = jsonElement.getAsJsonObject();

        for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
            String entryKey = entry.getKey();
            V value;
            try {
                value = deserializeFromJsonElement.apply(entry.getValue());
            } catch (Exception e) {
                log.error("Failed to deserialize value for entry {}", entryKey, e);
                continue;
            }
            if (value != null) {
                innerMap.put(entryKey, value);
                notifyListenersOnAdd(key, entryKey, value);
            }
        }

        if (!innerMap.isEmpty()) {
            localCache.put(key, innerMap);
        }
    }

    private void handleEntryUpdate(K key, String entryKey, JsonElement jsonElement) {
        if (jsonElement == null || jsonElement.isJsonNull()) {
            // Entry removed
            ConcurrentHashMap<String, V> innerMap = localCache.get(key);
            if (innerMap != null) {
                innerMap.remove(entryKey);
                if (innerMap.isEmpty()) {
                    localCache.remove(key);
                }
            }
            notifyListenersOnRemove(key, entryKey);
        } else {
            // Entry added/updated
            V value;
            try {
                value = deserializeFromJsonElement.apply(jsonElement);
            } catch (Exception e) {
                log.error("Failed to deserialize value for entry {}", entryKey, e);
                return;
            }

            if (value != null) {
                ConcurrentHashMap<String, V> innerMap = localCache.computeIfAbsent(key, k -> new ConcurrentHashMap<>());
                innerMap.put(entryKey, value);
                notifyListenersOnAdd(key, entryKey, value);
            }
        }
    }

    private void notifyListenersOnFullUpdate(Map<K, Map<String, V>> map) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onFullUpdate(map);
            } catch (Exception e) {
                log.error("Failed to notify listener on full update", e);
            }
        }
    }

    private void notifyListenersOnAdd(K key, String entryKey, V value) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onAdd(key, entryKey, value);
            } catch (Exception e) {
                log.error("Failed to notify listener on add", e);
            }
        }
    }

    private void notifyListenersOnRemove(K key, String entryKey) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onRemove(key, entryKey);
            } catch (Exception e) {
                log.error("Failed to notify listener on remove", e);
            }
        }
    }
}

package com.elertan.remote.firebase;

import com.elertan.remote.KeyValueStoragePort;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;
import java.util.function.Function;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FirebaseKeyValueStorageAdapterBase<K, V> implements KeyValueStoragePort<K, V> {

    private final String basePath;
    private final FirebaseRealtimeDatabase db;
    private final Gson gson;
    private final ConcurrentLinkedQueue<Listener<K, V>> listeners = new ConcurrentLinkedQueue<>();
    private final Function<String, K> stringToKeyTransformer;
    private final Function<K, String> keyToStringTransformer;
    private final Function<JsonElement, V> deserializeFromJsonElement;

    private final Consumer<FirebaseSSE> sseListener = this::sseListener;

    public FirebaseKeyValueStorageAdapterBase(
        String basePath,
        FirebaseRealtimeDatabase db,
        Gson gson,
        Function<String, K> stringToKeyTransformer,
        Function<K, String> keyToStringTransformer,
        Function<JsonElement, V> deserializeFromJsonElement
    ) {
        FirebaseRealtimeDatabase.validateBasePath(basePath);
        this.basePath = basePath;
        this.db = db;
        this.gson = gson;
        this.stringToKeyTransformer = stringToKeyTransformer;
        this.keyToStringTransformer = keyToStringTransformer;
        this.deserializeFromJsonElement = deserializeFromJsonElement;

        FirebaseSSEStream stream = db.getStream();
        stream.addServerSentEventListener(sseListener);
    }

    @Override
    public void close() throws Exception {
        listeners.clear();

        FirebaseSSEStream stream = db.getStream();
        stream.removeServerSentEventListener(sseListener);
    }

    @Override
    public CompletableFuture<V> read(K key) {
        String path = basePath + "/" + keyToStringTransformer.apply(key);
        return db.get(path)
            .thenApply(this.deserializeFromJsonElement);
    }

    @Override
    public CompletableFuture<Map<K, V>> readAll() {
        return db.get(basePath)
            .thenApply(jsonElement -> {
                if (jsonElement == null || jsonElement.isJsonNull()) {
                    return Collections.emptyMap();
                }

                JsonObject obj = jsonElement.getAsJsonObject();
                HashMap<K, V> map = new HashMap<>();

                for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                    K key = stringToKeyTransformer.apply(entry.getKey());
                    JsonElement entryValue = entry.getValue();
                    map.put(key, deserializeFromJsonElement.apply(entryValue));
                }

                return map;
            });
    }

    @Override
    public CompletableFuture<Void> update(K key, V value) {
        String path = basePath + "/" + keyToStringTransformer.apply(key);
        JsonElement jsonElement = gson.toJsonTree(value);
        return db.put(path, jsonElement).thenApply(__ -> null);
    }

    @Override
    public CompletableFuture<Void> updateAll(Map<K, V> map) {
        Map<K, JsonElement> jsonElementMap = new HashMap<>();
        for (Map.Entry<K, V> entry : map.entrySet()) {
            jsonElementMap.put(entry.getKey(), gson.toJsonTree(entry.getValue()));
        }
        JsonElement jsonElement = gson.toJsonTree(jsonElementMap);

        return db.put(basePath, jsonElement).thenApply(__ -> null);
    }

    @Override
    public CompletableFuture<Void> delete(K key) {
        String path = basePath + "/" + keyToStringTransformer.apply(key);
        return db.delete(path);
    }

    @Override
    public void addListener(Listener<K, V> listener) {
        listeners.add(listener);
    }

    @Override
    public void removeListener(Listener<K, V> listener) {
        listeners.remove(listener);
    }

    private void sseListener(FirebaseSSE event) {
        FirebaseSSEType type = event.getType();
        if (type != FirebaseSSEType.Put) {
            return;
        }

        String path = event.getPath();
        if (!path.startsWith(basePath)) {
            return;
        }
        String[] pathParts = Arrays.stream(path.split("/"))
            .filter(part -> !part.isEmpty())
            .toArray(String[]::new);
        int pathPartsLength = pathParts.length;
        if (pathPartsLength == 1) {
            // Full update
            JsonElement jsonElement = event.getData();
            Map<K, V> map = null;
            if (jsonElement != null && !jsonElement.isJsonNull()) {
                JsonObject obj = jsonElement.getAsJsonObject();
                map = new HashMap<>();
                for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                    K key = stringToKeyTransformer.apply(entry.getKey());
                    JsonElement entryValue = entry.getValue();
                    V value;
                    try {
                        value = deserializeFromJsonElement.apply(entryValue);
                    } catch (Exception e) {
                        log.error(
                            "RepositoryFirebaseStorageAdapterbase ({}): failed to deserialize value in full update for key ({}): {}",
                            basePath,
                            keyToStringTransformer.apply(key),
                            jsonElement,
                            e
                        );
                        return;
                    }
                    map.put(key, value);
                }
            }
            notifyListenersOnFullUpdate(map);
        } else if (pathPartsLength == 2) {
            String strKey = pathParts[1];
            K key = stringToKeyTransformer.apply(strKey);

            JsonElement jsonElement = event.getData();
            V value;
            try {
                value = deserializeFromJsonElement.apply(jsonElement);
            } catch (Exception e) {
                log.error(
                    "RepositoryFirebaseStorageAdapterbase ({}): failed to deserialize value for key ({}): {}",
                    basePath,
                    strKey,
                    jsonElement,
                    e
                );
                return;
            }

            if (value == null) {
                // Value deleted
                notifyListenersOnDelete(key);
            } else {
                // Value
                notifyListenersOnUpdate(key, value);
            }
        } else {
            log.debug(
                "RepositoryFirebaseStorageAdapterbase ({}): too many path parts for unlocked items sse event, will ignored: {}",
                basePath,
                path
            );
        }
    }

    private void notifyListenersOnFullUpdate(Map<K, V> map) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onFullUpdate(map);
            } catch (Exception e) {
                log.error("Failed to notify listeners on full update", e);
            }
        }
    }

    private void notifyListenersOnUpdate(K key, V value) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onUpdate(key, value);
            } catch (Exception e) {
                log.error("Failed to notify listener on update", e);
            }
        }
    }

    private void notifyListenersOnDelete(K key) {
        for (Listener<K, V> listener : listeners) {
            try {
                listener.onDelete(key);
            } catch (Exception e) {
                log.error("Failed to notify listener on delete", e);
            }
        }
    }
}

package com.elertan.remote.firebase;

import com.elertan.remote.ObjectListStoragePort;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;
import java.util.function.Function;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FirebaseObjectListStorageAdapterBase<V> implements ObjectListStoragePort<V> {

    private final String basePath;
    private final FirebaseRealtimeDatabase db;
    private final Function<V, JsonElement> serializer;
    private final Function<JsonElement, V> deserializer;
    private final ConcurrentLinkedQueue<Listener<V>> listeners = new ConcurrentLinkedQueue<>();

    private final ConcurrentHashMap<String, V> localCache = new ConcurrentHashMap<>();

    private final Consumer<FirebaseSSE> sseListener = this::sseListener;

    public FirebaseObjectListStorageAdapterBase(
        String basePath,
        FirebaseRealtimeDatabase db,
        Function<V, JsonElement> serializer,
        Function<JsonElement, V> deserializer
    ) {
        FirebaseRealtimeDatabase.validateBasePath(basePath);
        this.basePath = basePath;
        this.db = db;
        this.serializer = serializer;
        this.deserializer = deserializer;

        FirebaseSSEStream stream = db.getStream();
        stream.addServerSentEventListener(sseListener);
    }

    @Override
    public void close() throws Exception {
        listeners.clear();
        localCache.clear();

        FirebaseSSEStream stream = db.getStream();
        stream.removeServerSentEventListener(sseListener);
    }

    @Override
    public CompletableFuture<Map<String, V>> readAll() {
        return db.get(basePath)
            .thenApply(jsonElement -> {
                if (jsonElement == null || jsonElement.isJsonNull()) {
                    return Collections.emptyMap();
                }

                JsonObject obj = jsonElement.getAsJsonObject();
                Map<String, V> map = new HashMap<>();

                for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                    V value = deserializer.apply(entry.getValue());
                    if (value != null) {
                        map.put(entry.getKey(), value);
                    }
                }

                return map;
            });
    }

    @Override
    public CompletableFuture<String> add(V value) {
        JsonElement jsonElement = serializer.apply(value);
        return db.post(basePath, jsonElement)
            .thenApply(response -> {
                if (response != null && response.isJsonObject()) {
                    JsonObject obj = response.getAsJsonObject();
                    if (obj.has("name")) {
                        return obj.get("name").getAsString();
                    }
                }
                return null;
            });
    }

    @Override
    public CompletableFuture<Void> remove(String entryKey) {
        String path = basePath + "/" + entryKey;
        return db.delete(path);
    }

    @Override
    public void addListener(Listener<V> listener) {
        listeners.add(listener);
    }

    @Override
    public void removeListener(Listener<V> listener) {
        listeners.remove(listener);
    }

    public ConcurrentHashMap<String, V> getLocalCache() {
        return localCache;
    }

    private void sseListener(FirebaseSSE event) {
        FirebaseSSEType type = event.getType();
        if (type != FirebaseSSEType.Put) {
            return;
        }

        String path = event.getPath();
        if (!path.startsWith(basePath)) {
            return;
        }
        String[] pathParts = Arrays.stream(path.split("/"))
            .filter(part -> !part.isEmpty())
            .toArray(String[]::new);
        int pathPartsLength = pathParts.length;

        if (pathPartsLength == 1) {
            // Full update of entire collection
            handleFullUpdate(event.getData());
        } else if (pathPartsLength == 2) {
            // Single entry add/remove
            String entryKey = pathParts[1];
            handleEntryUpdate(entryKey, event.getData());
        } else {
            log.debug(
                "FirebaseObjectListStorageAdapterBase ({}): too many path parts, ignoring: {}",
                basePath,
                path
            );
        }
    }

    private void handleFullUpdate(JsonElement jsonElement) {
        localCache.clear();
        Map<String, V> fullMap = new HashMap<>();

        if (jsonElement != null && !jsonElement.isJsonNull() && jsonElement.isJsonObject()) {
            JsonObject obj = jsonElement.getAsJsonObject();
            for (Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                String entryKey = entry.getKey();
                V value;
                try {
                    value = deserializer.apply(entry.getValue());
                } catch (Exception e) {
                    log.error("Failed to deserialize value for entry {}", entryKey, e);
                    continue;
                }
                if (value != null) {
                    localCache.put(entryKey, value);
                    fullMap.put(entryKey, value);
                }
            }
        }

        notifyListenersOnFullUpdate(fullMap);
    }

    private void handleEntryUpdate(String entryKey, JsonElement jsonElement) {
        if (jsonElement == null || jsonElement.isJsonNull()) {
            // Entry removed
            localCache.remove(entryKey);
            notifyListenersOnRemove(entryKey);
        } else {
            // Entry added/updated
            V value;
            try {
                value = deserializer.apply(jsonElement);
            } catch (Exception e) {
                log.error("Failed to deserialize value for entry {}", entryKey, e);
                return;
            }

            if (value != null) {
                localCache.put(entryKey, value);
                notifyListenersOnAdd(entryKey, value);
            }
        }
    }

    private void notifyListenersOnFullUpdate(Map<String, V> map) {
        for (Listener<V> listener : listeners) {
            try {
                listener.onFullUpdate(map);
            } catch (Exception e) {
                log.error("Failed to notify listener on full update", e);
            }
        }
    }

    private void notifyListenersOnAdd(String entryKey, V value) {
        for (Listener<V> listener : listeners) {
            try {
                listener.onAdd(entryKey, value);
            } catch (Exception e) {
                log.error("Failed to notify listener on add", e);
            }
        }
    }

    private void notifyListenersOnRemove(String entryKey) {
        for (Listener<V> listener : listeners) {
            try {
                listener.onRemove(entryKey);
            } catch (Exception e) {
                log.error("Failed to notify listener on remove", e);
            }
        }
    }
}

package com.elertan.remote.firebase;

import com.elertan.remote.ObjectStoragePort;
import com.google.gson.JsonElement;
import java.util.Arrays;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.function.Consumer;
import java.util.function.Function;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class FirebaseObjectStorageAdapterBase<T> implements ObjectStoragePort<T> {

    private final String path;
    private final FirebaseRealtimeDatabase db;
    private final Function<T, JsonElement> serializer;
    private final Function<JsonElement, T> deserializer;
    private final ConcurrentLinkedQueue<Listener<T>> listeners = new ConcurrentLinkedQueue<>();
    private final Consumer<FirebaseSSE> sseListener = this::sseListener;

    public FirebaseObjectStorageAdapterBase(
        String path,
        FirebaseRealtimeDatabase db,
        Function<T, JsonElement> serializer,
        Function<JsonElement, T> deserializer
    ) {
        FirebaseRealtimeDatabase.validateBasePath(path);
        this.path = path;
        this.db = db;
        this.serializer = serializer;
        this.deserializer = deserializer;

        FirebaseSSEStream stream = db.getStream();
        stream.addServerSentEventListener(sseListener);
    }

    @Override
    public void close() throws Exception {
        FirebaseSSEStream stream = db.getStream();
        stream.removeServerSentEventListener(sseListener);
    }

    @Override
    public CompletableFuture<T> read() {
        CompletableFuture<T> future = new CompletableFuture<>();
        db.get(path).whenComplete((jsonElement, throwable) -> {
            if (throwable != null) {
                future.completeExceptionally(throwable);
                return;
            }
            boolean isJsonNull = jsonElement.isJsonNull();
            T value = this.deserializer.apply(jsonElement);
            if (value == null && !isJsonNull) {
                Exception ex = new IllegalStateException("deserialisation failed when reading value");
                log.error("deserialisation failed when reading value: {}", jsonElement, ex);
                future.completeExceptionally(ex);
                return;
            }

            future.complete(value);
        });
        return future;
    }

    @Override
    public CompletableFuture<Void> update(T value) {
        CompletableFuture<Void> future = new CompletableFuture<>();
        JsonElement jsonElement = this.serializer.apply(value);
        if (jsonElement == null || jsonElement.isJsonNull()) {
            Exception ex = new IllegalArgumentException(
                "value must not be null, call delete instead. Maybe the value failed to serialize?");
            future.completeExceptionally(ex);
            return future;
        }

        db.put(path, jsonElement).whenComplete((__, throwable) -> {
            if (throwable != null) {
                future.completeExceptionally(throwable);
                return;
            }

            future.complete(null);
        });

        return future;
    }

    @Override
    public CompletableFuture<Void> delete() {
        return db.delete(path);
    }

    @Override
    public void addListener(Listener<T> listener) {
        listeners.add(listener);
    }

    @Override
    public void removeListener(Listener<T> listener) {
        listeners.remove(listener);
    }

    private void sseListener(FirebaseSSE event) {
        FirebaseSSEType type = event.getType();
        if (type != FirebaseSSEType.Put) {
            return;
        }

        String path = event.getPath();
        if (!path.startsWith(this.path)) {
            return;
        }
        String[] pathParts = Arrays.stream(path.split("/"))
            .filter(part -> !part.isEmpty())
            .toArray(String[]::new);
        int pathPartsLength = pathParts.length;
        if (pathPartsLength != 1) {
            log.warn("put received but at a deeper level than just the object store, ignoring");
            return;
        }

        JsonElement jsonElement = event.getData();

        if (jsonElement == null || jsonElement.isJsonNull()) {
            notifyListenersOnDelete();
            return;
        }

        T value = this.deserializer.apply(jsonElement);
        notifyListenersOnUpdate(value);
    }

    private void notifyListenersOnUpdate(T value) {
        for (Listener<T> listener : listeners) {
            try {
                listener.onUpdate(value);
            } catch (Exception e) {
                log.error("Failed to notify listener on update", e);
            }
        }
    }

    private void notifyListenersOnDelete() {
        for (Listener<T> listener : listeners) {
            try {
                listener.onDelete();
            } catch (Exception e) {
                log.error("Failed to notify listener on delete", e);
            }
        }
    }
}

package com.elertan.remote.firebase;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import java.io.IOException;
import java.io.Reader;
import java.util.concurrent.CompletableFuture;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.ResponseBody;

@Slf4j
public class FirebaseRealtimeDatabase implements AutoCloseable {

    private static final MediaType JSON_MEDIA_TYPE = MediaType.parse(
        "application/json; charset=utf-8");

    private final OkHttpClient httpClient;
    private final Gson gson;

    @Getter
    private final FirebaseRealtimeDatabaseURL databaseURL;
    @Getter
    private final FirebaseSSEStream stream;

    public FirebaseRealtimeDatabase(OkHttpClient httpClient, Gson gson,
        FirebaseRealtimeDatabaseURL databaseURL) {
        this.httpClient = httpClient;
        this.gson = gson;
        this.databaseURL = databaseURL;
        this.stream = new FirebaseSSEStream(httpClient, gson, databaseURL);
    }

    public static CompletableFuture<Boolean> canConnectTo(OkHttpClient httpClient,
        FirebaseRealtimeDatabaseURL url) {
        final String strUrl = url.getBaseUrl() + "/__BRONZEMAN_UNLEASED_CAN_CONNECT_TEST.json";
        Request request = FirebaseRealtimeDatabase.getRequestBuilder(strUrl).get().build();

        return enqueueAsync(httpClient, request).handle((response, error) -> {
            if (error != null) {
                log.error("FirebaseRealtimeDatabase canConnect() exception: ", error);
                return Boolean.FALSE;
            }
            try (okhttp3.Response res = response) {
                return res.isSuccessful();
            }
        });
    }

    public static Request.Builder getRequestBuilder(String url) {
        return new Request.Builder().url(url)
            .header("User-Agent", "BronzemanUnleashedPlugin");
    }

    /**
     * Validates that a base path is a single-level resource path (e.g., "/Resource").
     * @throws IllegalArgumentException if path is null, doesn't start with '/', or has multiple levels
     */
    public static void validateBasePath(String path) {
        if (path == null) {
            throw new IllegalArgumentException("path must not be null");
        }
        if (!path.startsWith("/")) {
            throw new IllegalArgumentException("path must start with '/'");
        }
        if (path.lastIndexOf("/") != 0) {
            throw new IllegalArgumentException("path must only be a starting resource");
        }
    }

    private static CompletableFuture<okhttp3.Response> enqueueAsync(OkHttpClient client,
        Request request) {
        final okhttp3.Call call = client.newCall(request);
        final CompletableFuture<okhttp3.Response> future = new CompletableFuture<>();
        future.whenComplete((r, t) -> {
            if (future.isCancelled()) {
                call.cancel();
            }
        });
        call.enqueue(new okhttp3.Callback() {
            @Override
            public void onFailure(Call c, IOException e) {
                if (!future.isDone()) {
                    future.completeExceptionally(e);
                }
            }

            @Override
            public void onResponse(okhttp3.Call c, okhttp3.Response response) {
                if (!future.isDone()) {
                    future.complete(response);
                } else {
                    response.close();
                }
            }
        });
        return future;
    }

    @Override
    public void close() throws Exception {
        FirebaseSSEStream stream = getStream();
        stream.stop();
    }

    public CompletableFuture<JsonElement> get(String path) {
        String url = getUrlForPath(path);
        Request request = getRequestBuilder(url)
            .get()
            .build();
        return executeJsonRequest(request);
    }

    public CompletableFuture<JsonElement> post(String path, JsonElement data) {
        return executeJsonRequest(buildJsonRequestWithBody(path, "POST", data));
    }

    public CompletableFuture<JsonElement> put(String path, JsonElement data) {
        return executeJsonRequest(buildJsonRequestWithBody(path, "PUT", data));
    }

    public CompletableFuture<Void> delete(String path) {
        String url = getUrlForPath(path);
        Request request = getRequestBuilder(url)
            .delete()
            .build();
        return executeVoidRequest(request);
    }

    private CompletableFuture<JsonElement> executeJsonRequest(Request request) {
        final long startNanos = System.nanoTime();
        final CompletableFuture<JsonElement> future = new CompletableFuture<>();
        final okhttp3.Call call = httpClient.newCall(request);

        future.whenComplete((r, t) -> {
            if (future.isCancelled()) {
                call.cancel();
            }
        });

        call.enqueue(new okhttp3.Callback() {
            @Override
            public void onFailure(Call c, IOException e) {
                if (!future.isDone()) {
                    log.error(
                        "{} {} failed after {} ms",
                        request.method(),
                        request.url(),
                        (System.nanoTime() - startNanos) / 1_000_000
                    );
                    future.completeExceptionally(e);
                }
            }

            @Override
            public void onResponse(okhttp3.Call c, okhttp3.Response response) {
                try (okhttp3.Response res = response) {
                    if (!res.isSuccessful()) {
                        String snippet = null;
                        ResponseBody errBody = res.body();
                        if (errBody != null) {
                            try {
                                snippet = errBody.string();
                            } catch (IOException ignore) { /* ignore */ }
                        }
                        String msg = String.format(
                            "%s %s -> HTTP %d %s%s",
                            request.method(), request.url(), res.code(), res.message(),
                            snippet != null ? ": " + snippet : ""
                        );
                        if (!future.isDone()) {
                            log.error(msg);
                            future.completeExceptionally(new IOException(msg));
                        }
                        return;
                    }

                    ResponseBody body = res.body();
                    if (body == null) {
                        String msg = String.format(
                            "%s %s -> empty body",
                            request.method(),
                            request.url()
                        );
                        if (!future.isDone()) {
                            log.error(msg);
                            future.completeExceptionally(new IOException(msg));
                        }
                        return;
                    }

                    try (Reader reader = body.charStream()) {
                        JsonElement jsonElement = gson.fromJson(reader, JsonElement.class);
                        if (!future.isDone()) {
                            future.complete(jsonElement);
                        }
                    } catch (Exception parseErr) {
                        if (!future.isDone()) {
                            future.completeExceptionally(parseErr);
                        }
                    }
                }
            }
        });

        return future;
    }

    private CompletableFuture<Void> executeVoidRequest(Request request) {
        final long startNanos = System.nanoTime();
        final CompletableFuture<Void> future = new CompletableFuture<>();
        final okhttp3.Call call = httpClient.newCall(request);

        future.whenComplete((r, t) -> {
            if (future.isCancelled()) {
                call.cancel();
            }
        });

        call.enqueue(new okhttp3.Callback() {
            @Override
            public void onFailure(Call c, IOException e) {
                if (!future.isDone()) {
                    log.error(
                        "{} {} failed after {} ms",
                        request.method(),
                        request.url(),
                        (System.nanoTime() - startNanos) / 1_000_000
                    );
                    future.completeExceptionally(e);
                }
            }

            @Override
            public void onResponse(okhttp3.Call c, okhttp3.Response response) {
                try (okhttp3.Response res = response) {
                    if (!res.isSuccessful()) {
                        String snippet = null;
                        ResponseBody errBody = res.body();
                        if (errBody != null) {
                            try {
                                snippet = errBody.string();
                            } catch (IOException ignore) { /* ignore */ }
                        }
                        String msg = String.format(
                            "%s %s -> HTTP %d %s%s",
                            request.method(), request.url(), res.code(), res.message(),
                            snippet != null ? ": " + snippet : ""
                        );
                        if (!future.isDone()) {
                            log.error(msg);
                            future.completeExceptionally(new IOException(msg));
                        }
                        return;
                    }

                    // Success: nothing to parse, just complete
                    if (!future.isDone()) {
                        future.complete(null);
                    }
                }
            }
        });

        return future;
    }

    private Request buildJsonRequestWithBody(String path, String method, JsonElement data) {
        String url = getUrlForPath(path);
        String jsonPayload = gson.toJson(data);
        RequestBody body = RequestBody.create(JSON_MEDIA_TYPE, jsonPayload);
        return getRequestBuilder(url)
            .header("Content-Type", "application/json")
            .method(method, body)
            .build();
    }

    private String getUrlForPath(String path) {
        HttpUrl base = HttpUrl.parse(databaseURL.getBaseUrl());
        if (base == null) {
            throw new IllegalArgumentException("Invalid base URL: " + databaseURL.getBaseUrl());
        }

        String rawPath = path;
        String rawQuery = null;
        int q = path.indexOf('?');
        if (q >= 0) {
            rawPath = path.substring(0, q);
            rawQuery = path.substring(q + 1);
        }

        // normalize leading slash
        if (rawPath.startsWith("/")) {
            rawPath = rawPath.substring(1);
        }

        // ensure .json suffix on the path portion
        if (!rawPath.endsWith(".json")) {
            rawPath = rawPath + ".json";
        }

        HttpUrl.Builder b = base.newBuilder();
        // add each segment to avoid double slashes
        if (!rawPath.isEmpty()) {
            for (String seg : rawPath.split("/")) {
                if (!seg.isEmpty()) {
                    b.addPathSegment(seg);
                }
            }
        }

        // preserve existing base query and add provided query parameters, if any
        if (rawQuery != null && !rawQuery.isEmpty()) {
            for (String kv : rawQuery.split("&")) {
                int eq = kv.indexOf('=');
                String k = eq >= 0 ? kv.substring(0, eq) : kv;
                String v = eq >= 0 ? kv.substring(eq + 1) : "";
                b.addEncodedQueryParameter(k, v);
            }
        }
        return b.build().toString();
    }
}

package com.elertan.remote.firebase;

import java.net.MalformedURLException;
import java.net.URL;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

/**
 * Value object for Firebase Realtime Database endpoints.
 * <p>
 * Ensures the host belongs to an allowed Firebase domain and provides a normalized base URL in the
 * form {@code scheme://host[:port]}. Handles IPv6 literals and omits default ports (80 for http,
 * 443 for https).
 */
public final class FirebaseRealtimeDatabaseURL {

    private static final List<String> ALLOWED_SUFFIXES = Arrays.asList(
        ".firebasedatabase.app",
        ".firebaseio.com"
    );

    private final URL url;

    /**
     * Construct from a {@link URL}.
     *
     * @param url non-null URL using http or https and pointing to an allowed Firebase host
     * @throws IllegalArgumentException if the URL is null, uses an unsupported scheme, or the host
     *                                  is not a Firebase host
     */
    public FirebaseRealtimeDatabaseURL(URL url) throws IllegalArgumentException {
        this.url = Objects.requireNonNull(url, "url");

        final String protocol = this.url.getProtocol();
        if (!"http".equalsIgnoreCase(protocol) && !"https".equalsIgnoreCase(protocol)) {
            throw new IllegalArgumentException("Protocol must be http or https");
        }

        if (!isFirebaseHost(this.url.getHost())) {
            throw new IllegalArgumentException(
                "The provided URL is not a valid FirebaseRealtimeDatabaseURL");
        }
    }

    /**
     * Construct from a string.
     *
     * @param urlString textual URL
     * @throws IllegalArgumentException if the string is not a valid URL or not a Firebase host
     */
    public FirebaseRealtimeDatabaseURL(String urlString)
        throws IllegalArgumentException, MalformedURLException {
        this(new URL(urlString));
    }

    private static boolean isDefaultPort(String protocol, int port) {
        return ("http".equalsIgnoreCase(protocol) && port == 80)
            || ("https".equalsIgnoreCase(protocol) && port == 443);
    }

    private static boolean isFirebaseHost(String host) {
        if (host == null || host.isEmpty()) {
            return false;
        }
        final String h = host.toLowerCase(Locale.ROOT);
        for (String suffix : ALLOWED_SUFFIXES) {
            if (h.endsWith(suffix)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Returns the normalized base URL: {@code scheme://host[:port]}. Omits default ports.
     */
    public String getBaseUrl() {
        final String protocol = url.getProtocol().toLowerCase(Locale.ROOT);
        final String host = url.getHost();
        final int port = url.getPort();

        final boolean isIpv6 = host != null && host.indexOf(':') >= 0; // literal IPv6 host

        StringBuilder base = new StringBuilder();
        base.append(protocol).append("://");
        if (isIpv6) {
            base.append('[').append(host).append(']');
        } else {
            base.append(host);
        }

        if (port != -1 && !isDefaultPort(protocol, port)) {
            base.append(":").append(port);
        }

        return base.toString();
    }

    /**
     * Exposes the underlying URL instance.
     */
    public URL getUrl() {
        return url;
    }

    @Override
    public String toString() {
        return url.toString();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }
        FirebaseRealtimeDatabaseURL that = (FirebaseRealtimeDatabaseURL) o;
        return url.equals(that.url);
    }

    @Override
    public int hashCode() {
        return url.hashCode();
    }
}

