    public static <T> AutoCloseable bindComboBox(
        JComboBox<T> comboBox,
        Property<List<T>> optionsProperty,
        Property<T> valueProperty,
        Property<Map<T, String>> valueToStringMapProperty
    ) {
        if (comboBox == null) {
            throw new IllegalArgumentException("comboBox must not be null");
        }
        if (valueProperty == null) {
            throw new IllegalArgumentException("valueProperty must not be null");
        }
        if (valueToStringMapProperty == null) {
            throw new IllegalArgumentException("valueToStringMapProperty must not be null");
        }

        AtomicReference<Boolean> isUpdatingOptions = new AtomicReference<>(false);

        Supplier<List<T>> optionsGetter = () -> {
            int itemCount = comboBox.getItemCount();
            List<T> options = new ArrayList<>(itemCount);
            for (int i = 0; i < itemCount; i++) {
                @SuppressWarnings("unchecked")
                T item = comboBox.getItemAt(i);
                options.add(item);
            }
            return options;
        };

        Consumer<List<T>> optionsSetter = (List<T> options) -> {
            isUpdatingOptions.set(true);
            try {
                DefaultComboBoxModel<T> model = new DefaultComboBoxModel<>();
                if (options != null) {
                    for (T o : options) {
                        model.addElement(o);
                    }
                }
                comboBox.setModel(model); // selects first internally
                comboBox.setSelectedItem(valueProperty.get()); // restore intended value
            } finally {
                isUpdatingOptions.set(false);
            }
        };

        Supplier<T> valueGetter = () -> {
            @SuppressWarnings("unchecked")
            T selected = (T) comboBox.getSelectedItem();
            return selected;
        };

        Consumer<T> valueSetter = comboBox::setSelectedItem;

        // Use provided mapping for display text, defaulting to enum name
        ListCellRenderer<? super T> renderer = new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(
                JList<?> list,
                Object value,
                int index,
                boolean isSelected,
                boolean cellHasFocus
            ) {
                @SuppressWarnings("unchecked")
                T typedValue = (T) value;
                Map<T, String> valueToStringMap = valueToStringMapProperty.get();
                String text = valueToStringMap.getOrDefault(typedValue, "Unknown");
                return super.getListCellRendererComponent(
                    list,
                    text,
                    index,
                    isSelected,
                    cellHasFocus
                );
            }
        };
        comboBox.setRenderer(renderer);

        ActionListener listener = e -> {
            Boolean isUpdatingOptionsValue = isUpdatingOptions.get();
            if (isUpdatingOptionsValue != null && isUpdatingOptionsValue) {
                return;
            }

            @SuppressWarnings("unchecked")
            T selected = (T) comboBox.getSelectedItem();
            valueProperty.set(selected);
        };
        comboBox.addActionListener(listener);

        @SuppressWarnings("resource")
        AutoCloseable optionsBinding = bind(optionsProperty, optionsGetter, optionsSetter);
        @SuppressWarnings("resource")
        AutoCloseable valueBinding = bind(valueProperty, valueGetter, valueSetter);

        PropertyChangeListener valueToStringMapPropertyListener = evt -> comboBox.repaint();
        valueToStringMapProperty.addListener(valueToStringMapPropertyListener);

        return () -> {
            valueToStringMapProperty.removeListener(valueToStringMapPropertyListener);
            valueBinding.close();
            optionsBinding.close();
            comboBox.removeActionListener(listener);
        };
    }

    public static <E extends Enum<E>, P extends JPanel> AutoCloseable bindCardLayout(
        JPanel host,
        CardLayout cardLayout,
        Property<E> property,
        Function<E, P> build
    ) {
        AtomicReference<E> lastEnum = new AtomicReference<>(null);
        final Map<E, P> builtPanels = new HashMap<>();

        Supplier<E> getter = lastEnum::get;

        Consumer<E> setter = (E enumValue) -> {
            if (enumValue == null) {
                throw new IllegalArgumentException("property must have a non-null value");
            }

            String key = enumValue.name();

            if (!builtPanels.containsKey(enumValue)) {
                P panel = build.apply(enumValue);
                builtPanels.put(enumValue, panel);
                host.add(panel, key);
            }

            lastEnum.set(enumValue);
            cardLayout.show(host, key);

            host.revalidate();
            host.repaint();
        };

        return bind(property, getter, setter);
    }

    public static <T> AutoCloseable bind(Property<T> property, Supplier<T> getter,
        Consumer<T> setter) {
        PropertyChangeListener listener = (event) -> invokeOnEDT(() -> {
            @SuppressWarnings("unchecked")
            T newValue = (T) event.getNewValue();

            T oldValue = getter.get();
            if (Objects.equals(oldValue, newValue)) {
                return;
            }
            setter.accept(newValue);
        });

        property.addListener(listener);
        setter.accept(property.get());

        return () -> property.removeListener(listener);
    }

    public static void invokeOnEDT(Runnable runnable) {
        if (SwingUtilities.isEventDispatchThread()) {
            runnable.run();
        } else {
            SwingUtilities.invokeLater(runnable);
        }
    }
}

package com.elertan.ui;

import java.beans.PropertyChangeListener;
import java.beans.PropertyChangeSupport;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import java.util.function.Function;

public final class Property<T> {

    private static final Executor DEFAULT_EXECUTOR = Executors.newCachedThreadPool();
    private final PropertyChangeSupport propertyChangeSupport = new PropertyChangeSupport(this);
    private volatile T value;

    public Property(T value) {
        this.value = value;
    }

    public static <R> Property<R> deriveMany(
        List<? extends Property<?>> properties,
        Function<List<?>, R> combiner
    ) {
        Objects.requireNonNull(properties, "properties");
        Objects.requireNonNull(combiner, "combiner");

        if (properties.contains(null)) {
            throw new NullPointerException("properties contains null");
        }

        // Initialize the derived property using the current values
        final List<Object> initialValues = new ArrayList<>(properties.size());
        for (Property<?> p : properties) {
            initialValues.add(p.get());
        }
        final Property<R> derived = new Property<>(
            combiner.apply(Collections.unmodifiableList(initialValues))
        );

        // Recompute the combined value whenever any source property changes
        final PropertyChangeListener listener = evt -> {
            if ("value".equals(evt.getPropertyName())) {
                final List<Object> values = new ArrayList<>(properties.size());
                for (Property<?> p : properties) {
                    values.add(p.get());
                }
                derived.set(combiner.apply(Collections.unmodifiableList(values)));
            }
        };

        for (Property<?> p : properties) {
            p.addListener(listener);
        }

        return derived;
    }

    public static <R> Property<R> deriveManyAsync(
        List<? extends Property<?>> properties,
        Function<List<?>, R> combiner
    ) {
        return deriveManyAsync(properties, combiner, DEFAULT_EXECUTOR);
    }

    public static <R> Property<R> deriveManyAsync(
        List<? extends Property<?>> properties,
        Function<List<?>, R> combiner,
        Executor executor
    ) {
        Objects.requireNonNull(properties, "properties");
        Objects.requireNonNull(combiner, "combiner");
        Objects.requireNonNull(executor, "executor");

        if (properties.contains(null)) {
            throw new NullPointerException("properties contains null");
        }

        final Property<R> derived = new Property<>(null);

        final Runnable recompute = () -> {
            final List<Object> values = new ArrayList<>(properties.size());
            for (Property<?> p : properties) {
                values.add(p.get());
            }
            derived.set(combiner.apply(Collections.unmodifiableList(values)));
        };

        // Initial compute on the provided executor
        executor.execute(recompute);

        // Recompute on any source change using the provided executor
        final PropertyChangeListener listener = evt -> {
            if ("value".equals(evt.getPropertyName())) {
                executor.execute(recompute);
            }
        };

        for (Property<?> p : properties) {
            p.addListener(listener);
        }

        return derived;
    }

    public T get() {
        return value;
    }

    public void set(T value) {
        T oldValue = this.value;
        if (Objects.equals(oldValue, value)) {
            return;
        }
        this.value = value;
        propertyChangeSupport.firePropertyChange("value", oldValue, value);
    }

    public void addListener(PropertyChangeListener listener) {
        propertyChangeSupport.addPropertyChangeListener(listener);
    }

    public void removeListener(PropertyChangeListener listener) {
        propertyChangeSupport.removePropertyChangeListener(listener);
    }

    public <U> Property<U> derive(Function<T, U> transform) {
        Objects.requireNonNull(transform, "transform");
        // Initialize derived property with the transformed current value
        Property<U> derived = new Property<>(transform.apply(this.value));

        // Update the derived property whenever this property's value changes
        PropertyChangeListener listener = evt -> {
            if ("value".equals(evt.getPropertyName())) {
                @SuppressWarnings("unchecked")
                T newValue = (T) evt.getNewValue();
                derived.set(transform.apply(newValue));
            }
        };
        this.addListener(listener);

        return derived;
    }

    public <U> Property<U> deriveAsync(Function<T, U> transform) {
        return deriveAsync(transform, DEFAULT_EXECUTOR);
    }

    public <U> Property<U> deriveAsync(Function<T, U> transform, Executor executor) {
        Objects.requireNonNull(transform, "transform");
        Objects.requireNonNull(executor, "executor");

        // Initialize derived property asynchronously using the current value
        Property<U> derived = new Property<>(null);
        executor.execute(() -> derived.set(transform.apply(this.value)));

        // Update the derived property on the provided executor whenever this property's value changes
        PropertyChangeListener listener = evt -> {
            if ("value".equals(evt.getPropertyName())) {
                @SuppressWarnings("unchecked")
                T newValue = (T) evt.getNewValue();
                executor.execute(() -> derived.set(transform.apply(newValue)));
            }
        };
        this.addListener(listener);

        return derived;
    }
}

package com.elertan.utils;

import com.google.inject.Inject;
import java.util.concurrent.CompletableFuture;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Supplier;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.callback.ClientThread;

/**
 * Utility methods for CompletableFuture operations.
 */
@Slf4j
public final class AsyncUtils {

    @Inject
    ClientThread clientThread;

    /**
     * Returns a BiConsumer that logs errors at ERROR level. Use with whenComplete() to add
     * standardized error logging.
     *
     * @param message the error message prefix
     * @param <T>     the result type
     * @return BiConsumer for use with whenComplete()
     */
    public static <T> BiConsumer<T, Throwable> logError(String message) {
        return (result, throwable) -> {
            if (throwable != null) {
                log.error(message, throwable);
            }
        };
    }

    /**
     * Attaches error logging to a CompletableFuture and returns it. The original future is returned
     * unchanged, just with logging attached.
     *
     * @param future  the future to attach logging to
     * @param message the error message prefix
     * @param <T>     the result type
     * @return the same future with error logging attached
     */
    public static <T> CompletableFuture<T> withErrorLogging(CompletableFuture<T> future,
        String message) {
        future.whenComplete(logError(message));
        return future;
    }

    /**
     * Returns a Consumer that attaches error logging to a CompletableFuture. The original future is
     * returned unchanged, just with logging attached. Useful when handling streams.
     *
     * @param message the error message prefix
     * @param <T>     the result type
     * @return a Consumer that attaches logging to a future
     */
    public static <T> Consumer<CompletableFuture<T>> addErrorLogging(String message) {
        return (future) -> withErrorLogging(future, message);
    }

    /**
     * Returns a Function that asynchronously runs the supplied Supplier on the client thread and
     * returns the result as a CompletableFuture
     *
     * @param fn  Supplier function to run on the client thread
     * @param <T> the result type
     * @param <U> discarded input value type, to be broadly compatible with Future handling methods
     * @return CompletableFuture of the return value of the supplied Supplier
     */
    public <T, U> Function<U, CompletableFuture<T>> onClientThread(Supplier<T> fn) {
        return (__) -> runOnClientThread(fn);
    }

    /**
     * Asynchronously run the supplied Supplier on the client thread and return the result as a
     * CompletableFuture
     *
     * @param fn  Supplier function to run on the client thread
     * @param <T> the result type
     * @return the return value of the supplied Supplier
     */
    public <T> CompletableFuture<T> runOnClientThread(Supplier<T> fn) {
        CompletableFuture<T> future = new CompletableFuture<>();
        clientThread.invokeLater(() -> {
            future.complete(fn.get());
        });
        return future;
    }
}

package com.elertan.utils;

import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonPrimitive;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;

public class JsonUtils {

    public static Object jsonElementToNative(JsonElement el) throws IllegalArgumentException {
        if (el == null || el.isJsonNull()) {
            return null;
        }

        if (el.isJsonPrimitive()) {
            JsonPrimitive p = el.getAsJsonPrimitive();
            if (p.isBoolean()) {
                return p.getAsBoolean();
            }
            if (p.isNumber()) {
                // Prefer integral types when possible, else fall back to double
                BigDecimal bd = p.getAsBigDecimal();
                try {
                    if (bd.scale() <= 0) { // no fractional part
                        try {
                            return bd.intValueExact();
                        } catch (ArithmeticException ignored) {
                            try {
                                return bd.longValueExact();
                            } catch (ArithmeticException ignored2) {
                                return bd.toBigIntegerExact();
                            }
                        }
                    }
                } catch (ArithmeticException ignored3) {
                    // fall through to double
                }
                return bd.doubleValue();
            }
            if (p.isString()) {
                return p.getAsString();
            }
        }

        if (el.isJsonArray()) {
            JsonArray arr = el.getAsJsonArray();
            ArrayList<Object> list = new ArrayList<>(arr.size());
            for (JsonElement e : arr) {
                list.add(jsonElementToNative(e));
            }
            return list;
        }

        if (el.isJsonObject()) {
            JsonObject obj = el.getAsJsonObject();
            LinkedHashMap<String, Object> map = new LinkedHashMap<>();
            for (java.util.Map.Entry<String, JsonElement> entry : obj.entrySet()) {
                map.put(entry.getKey(), jsonElementToNative(entry.getValue()));
            }
            return map;
        }

        throw new IllegalArgumentException("Unsupported JsonElement: " + el);
    }
}

package com.elertan.utils;

import java.time.Duration;
import java.util.Objects;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.BiConsumer;
import java.util.function.Consumer;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Thread-safe observable value with built-in ready state and subscriptions.
 *
 * @param <T> the value type
 */
@Slf4j
public final class Observable<T> {

    // ConcurrentLinkedQueue allows thread-safe iteration without locking,
    // enabling listeners to be added/removed while notifying
    private final ConcurrentLinkedQueue<BiConsumer<T, T>> listeners = new ConcurrentLinkedQueue<>();
    private volatile T value;
    // Tracks whether set() has been called at least once (ready state)
    private final AtomicBoolean hasBeenSet = new AtomicBoolean(false);

    private Observable() {
    }

    /**
     * Creates observable without initial value. Starts in NotReady state.
     *
     * @param <T> the value type
     * @return new Observable in NotReady state
     */
    public static <T> Observable<T> empty() {
        return new Observable<>();
    }

    /**
     * Creates observable with initial value. Starts in Ready state.
     *
     * @param <T>   the value type
     * @param value the initial value (can be null)
     * @return new Observable in Ready state
     */
    public static <T> Observable<T> of(T value) {
        Observable<T> observable = new Observable<>();
        observable.value = value;
        observable.hasBeenSet.set(true);
        return observable;
    }

    /**
     * Get current value.
     *
     * @return current value (may be null even when ready)
     */
    public T get() {
        return value;
    }

    /**
     * Set value and notify listeners.
     * First call transitions to Ready state.
     * Skips notification if value equals previous (using Objects.equals).
     *
     * @param newValue the new value
     */
    public void set(T newValue) {
        T oldValue = this.value;
        boolean wasReady = hasBeenSet.getAndSet(true);

        // Skip if value unchanged AND was already ready
        // First set() must always notify (transition to ready state is meaningful)
        if (wasReady && Objects.equals(oldValue, newValue)) {
            return;
        }

        this.value = newValue;
        notifyListeners(newValue, oldValue);
    }

    /**
     * Returns true after set() has been called at least once.
     *
     * @return true if ready
     */
    public boolean isReady() {
        return hasBeenSet.get();
    }

    /**
     * Returns a future that completes when ready.
     * If already ready, completes immediately with current value.
     * If timeout provided and exceeded, completes exceptionally with TimeoutException.
     *
     * @param timeout timeout duration, or null for no timeout
     * @return future that completes with the value when ready
     */
    public CompletableFuture<T> await(@Nullable Duration timeout) {
        CompletableFuture<T> future = new CompletableFuture<>();

        // Complete immediately if already ready
        if (isReady()) {
            future.complete(value);
            return future;
        }

        // Subscribe to changes
        Subscription[] subscriptionHolder = new Subscription[1];
        subscriptionHolder[0] = subscribe((newValue, oldValue) -> {
            if (isReady() && !future.isDone()) {
                subscriptionHolder[0].dispose();
                future.complete(newValue);
            }
        });

        // Race condition check: ready state might have changed between isReady() check and subscribe
        if (isReady() && !future.isDone()) {
            subscriptionHolder[0].dispose();
            future.complete(value);
        }

        // Timeout handling via ScheduledExecutorService
        if (timeout != null) {
            ScheduledExecutorService scheduler = Executors.newSingleThreadScheduledExecutor();
            scheduler.schedule(() -> {
                if (!future.isDone()) {
                    subscriptionHolder[0].dispose();
                    future.completeExceptionally(
                        new TimeoutException("Timeout waiting for Observable to become ready"));
                }
            }, timeout.toMillis(), TimeUnit.MILLISECONDS);
            // Ensure scheduler is shutdown when future completes (success, timeout, or cancellation)
            future.whenComplete((result, ex) -> scheduler.shutdown());
        }

        return future;
    }

    /**
     * Subscribe to value changes.
     * Listener receives (newValue, oldValue) on each change.
     * oldValue is null on first notification after ready.
     *
     * @param listener the listener to notify on changes
     * @return subscription that can be disposed to unsubscribe
     */
    public Subscription subscribe(BiConsumer<T, T> listener) {
        listeners.add(listener);
        return new ListenerSubscription(listener);
    }

    /**
     * Subscribe to value changes (simple form).
     * Listener receives only newValue.
     *
     * @param listener the listener to notify on changes
     * @return subscription that can be disposed to unsubscribe
     */
    public Subscription subscribe(Consumer<T> listener) {
        return subscribe((newValue, oldValue) -> listener.accept(newValue));
    }

    /**
     * Subscribe and immediately invoke with current value if ready.
     * Useful for "get current state + subscribe to changes" pattern.
     *
     * @param listener the listener to notify on changes
     * @return subscription that can be disposed to unsubscribe
     */
    public Subscription subscribeImmediate(BiConsumer<T, T> listener) {
        Subscription subscription = subscribe(listener);
        if (isReady()) {
            try {
                listener.accept(value, null);
            } catch (Exception e) {
                log.error("Observable immediate listener error", e);
            }
        }
        return subscription;
    }

    /**
     * Clear all subscriptions and reset to NotReady state.
     * Call during service shutdown.
     */
    public void clear() {
        listeners.clear();
        hasBeenSet.set(false);
    }

    private void notifyListeners(T newValue, T oldValue) {
        for (BiConsumer<T, T> listener : listeners) {
            try {
                listener.accept(newValue, oldValue);
            } catch (Exception e) {
                // Log error but continue notifying other listeners
                log.error("Observable listener notification error", e);
            }
        }
    }

    /**
     * Internal subscription implementation that removes the listener on dispose.
     */
    private final class ListenerSubscription implements Subscription {
        private final BiConsumer<T, T> listener;
        private final AtomicBoolean disposed = new AtomicBoolean(false);

        ListenerSubscription(BiConsumer<T, T> listener) {
            this.listener = listener;
        }

        @Override
        public void dispose() {
            if (disposed.compareAndSet(false, true)) {
                listeners.remove(listener);
            }
        }

        @Override
        public boolean isDisposed() {
            return disposed.get();
        }
    }
}

package com.elertan.utils;

import java.time.Duration;
import java.time.OffsetDateTime;
import java.time.format.DateTimeFormatter;
import lombok.NonNull;

public class OffsetDateTimeUtils {

    public static String formatRelativeTime(@NonNull OffsetDateTime now,
        @NonNull OffsetDateTime time) {
        Duration d = Duration.between(time, now);
        long seconds = d.getSeconds();

        if (seconds < 60) {
            return "Just now";
        }
        if (seconds < 3600) {
            int minutes = (int) (seconds / 60);
            if (minutes == 1) {
                return "1 minute ago";
            }
            return minutes + " minutes ago";
        }
        if (seconds < 86400) {
            int hours = (int) (seconds / 3600);
            if (hours == 1) {
                return "1 hour ago";
            }
            return hours + " hours ago";
        }
        if (seconds < 172800) {
            return "Yesterday at " + time.format(DateTimeFormatter.ofPattern("HH:mm"));
        }
        if (seconds < 604800) {
            String dayOfWeek = time.format(DateTimeFormatter.ofPattern("EEEE"));
            return dayOfWeek + " at " + time.format(DateTimeFormatter.ofPattern("HH:mm"));
        }
        return time.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm"));
    }
}

package com.elertan.utils;

/**
 * Handle to an active subscription.
 * Implements AutoCloseable for try-with-resources support.
 */
public interface Subscription extends AutoCloseable {

    /**
     * Remove this subscription from its observable.
     * Safe to call multiple times; subsequent calls are no-ops.
     */
    void dispose();

    /**
     * Check if this subscription has been disposed.
     *
     * @return true if dispose() has been called
     */
    boolean isDisposed();

    /**
     * Alias for dispose() to support try-with-resources.
     */
    @Override
    default void close() {
        dispose();
    }
}

package com.elertan.utils;

import net.runelite.client.util.Text;

public class TextUtils {

    public static String sanitizePlayerName(String playerName) {
        String sanitized = Text.sanitize(Text.removeTags(playerName));
        return sanitized.replaceAll("\\s*\\(level-\\d+\\)$", "");
    }

    public static String sanitizeItemName(String itemName) {
        if (itemName == null) {
            return null;
        }
        String sanitized = Text.removeTags(itemName);
        // Some game strings contain non-breaking spaces; normalize for reliable matching.
        sanitized = sanitized.replace('\u00A0', ' ').trim();
        return sanitized.replaceAll("\\s*\\(Members\\)$", "");
    }
}

package com.elertan.utils;

import java.time.Duration;

public class TickUtils {

    private static final int SECONDS_PER_TICK_NUM = 3;  // 0.6 seconds per tick = 3/5
    private static final int SECONDS_PER_TICK_DEN = 5;

    public static Duration ticksToDuration(long ticks) {
        long q = ticks / SECONDS_PER_TICK_DEN;           // quotient
        long r = ticks % SECONDS_PER_TICK_DEN;           // remainder 0..4

//        long seconds = Math.multiplyExact(q, SECONDS_PER_TICK_NUM);
//        long extraSeconds = (r * (long) SECONDS_PER_TICK_NUM) / SECONDS_PER_TICK_DEN;
//        seconds = Math.addExact(seconds, extraSeconds);

        long seconds = q * SECONDS_PER_TICK_NUM; // safe: q<=Long.MAX/5, so q*3 fits in long
        long extraSeconds = (r * (long) SECONDS_PER_TICK_NUM) / SECONDS_PER_TICK_DEN;
        seconds = seconds + extraSeconds; // also safe

        int nanos = (int) (((r * (long) SECONDS_PER_TICK_NUM) % SECONDS_PER_TICK_DEN)
            * 200_000_000L); // 1/5 sec = 200ms

        return Duration.ofSeconds(seconds, nanos);
    }
}

